window.CASES = [{"id":"rolex","title":"Il Rolex del notaio","place":"Masseria Ruggiero, Valle d'Itria","teaser":"Settant'anni, trenta invitati, un orologio sparito dal comodino.","intro":"Il notaio Ruggiero festeggia i settant'anni nella sua masseria. A fine cena si accorge che il suo Rolex d'epoca, 40.000 euro, non è più sul comodino della camera al piano di sopra. Nessuno ha lasciato la festa. I sospetti del notaio sono tre, e ti ha chiamato perché la polizia, dice lui, «fa troppe domande e guarda troppo poco».","details":[{"id":"d1","label":"La finestra della camera","text":"Aperta. Sul davanzale polvere e polline gialli, intatti.","insight":"Nessuno è entrato dalla finestra: il ladro è uno della casa."},{"id":"d2","label":"Il cassetto del comodino","text":"La scatola dell'orologio è stata rimessa nel cassetto, chiusa con cura.","insight":"Il ladro sapeva dove cercare e non aveva fretta."},{"id":"d3","label":"Il prato","text":"L'irrigazione automatica è partita alle 21:30. Il prato tra la casa e il parcheggio è fradicio.","insight":"Chi è andato verso le auto dopo le 21:30 si è bagnato le scarpe."},{"id":"d4","label":"Il telefono di Davide","text":"Lasciato sul tavolo. Notifiche di un'app di scommesse: «Saldo insufficiente».","insight":"Davide ha debiti di gioco."},{"id":"d5","label":"Il parcheggio","text":"Tre mezzi degli ospiti: la moto di Davide, la Panda di Ilenia, una berlina grigia di Franco Lattanzi.","insight":"L'unica auto scura nel parcheggio è la berlina grigia di Franco."},{"id":"d6","label":"Il bagno di sotto","text":"Cartello scritto a mano: «Guasto, usate quello di sopra».","insight":"Tutti sono saliti di sopra almeno una volta: salire non prova niente."},{"id":"d7","label":"La foto sul mobile","text":"Bianco e nero, 1979. Il notaio giovane a un tavolo da gioco con un altro uomo. Didascalia: «Con Vito Lattanzi, Circolo Unione». Al polso di Vito, lo stesso Rolex.","insight":"Nel 1979 l'orologio era al polso di Vito Lattanzi, il padre di Franco."}],"suspects":[{"id":"davide","name":"Davide Ruggiero","role":"Nipote, 28 anni","look":"Gamba che batte sotto il tavolo, telefono sempre in mano.","tell":"Guarda dritto negli occhi quando parla dello zio. Si irrigidisce solo quando si parla di soldi. È vergogna, non colpa.","questions":[{"id":"a1","q":"Dov'era durante la cena?","a":"A tavola. Sono salito una volta verso le nove, il bagno di sotto è rotto. Come tutti."},{"id":"a2","q":"Il suo telefono dice che ha debiti di gioco.","req":["d4"],"a":"Ottomila euro. Sì. Ma lo zio me li aveva già promessi stasera, prima del dolce. Me li dava lunedì. Perché dovrei rubargli un orologio?","insight":"Lo zio aveva già promesso a Davide il prestito: rubare non gli serviva."},{"id":"a3","q":"Cosa sa dell'orologio?","a":"Che lo zio non se lo toglie mai. Stasera l'ha lasciato di sopra perché il cinturino gli stringeva."}]},{"id":"ilenia","name":"Ilenia Carone","role":"Cameriera di sala, 23 anni","look":"Composta, professionale. Serve dalla cucina da inizio serata.","tell":"Mani dietro la schiena, postura da sala. Quando nomini Davide abbassa lo sguardo e trattiene un sorriso. Nasconde qualcosa, ma è una cosa che la fa sorridere.","questions":[{"id":"i1","q":"È salita al piano di sopra stasera?","a":"Una volta, alle 21:15, per portare un bicchiere d'acqua al notaio per la pillola. L'orologio era sul comodino, l'ho visto io.","insight":"Alle 21:15 l'orologio era ancora sul comodino."},{"id":"i2","q":"Che rapporto ha con Davide?","a":"Siamo usciti insieme un paio di volte. Non l'ho detto perché qui lavoro e non voglio chiacchiere.","insight":"Ilenia e Davide si frequentano: ecco il suo imbarazzo."},{"id":"i3","q":"Dalla cucina si vede il parcheggio. Ha notato qualcosa?","a":"Verso le dieci meno un quarto si è accesa la luce dentro una macchina scura. Ho pensato che qualcuno stesse andando via. Poi la luce si è spenta e non è partito nessuno.","insight":"Alle 21:45 qualcuno è andato a una macchina scura ed è tornato alla festa."}]},{"id":"franco","name":"Franco Lattanzi","role":"Socio dello studio, 66 anni","look":"Elegante, giacca di lino, scarpe di camoscio. Calmo.","tell":"Calmo, forse troppo. Ha le gambe accavallate e la punta delle scarpe di camoscio ha aloni scuri d'acqua. Il camoscio si macchia solo sul bagnato.","questions":[{"id":"f1","q":"Si è mosso dalla tavola durante la cena?","a":"Una volta sola, per il bagno di sopra. Fuori non sono uscito, se è questo che mi chiede.","insight":"Franco giura di non essere mai uscito di casa."},{"id":"f2","q":"Da quanto conosce il notaio?","a":"Quarant'anni. Prima di essere il mio socio era amico di mio padre. Giocavano a carte insieme, al circolo."},{"id":"f3","q":"Nella foto del '79 suo padre porta lo stesso Rolex. Come mai?","req":["d7"],"a":"(Un silenzio lungo.) Mio padre l'ha perso a carte con lui. Una sera sola. Tutto quello che aveva al polso. Non ne ha mai più parlato, fino alla morte.","insight":"Movente: l'orologio era del padre di Franco, perso a carte col notaio.","lie":true},{"id":"f4","q":"Il prato è bagnato dalle 21:30 e le sue scarpe hanno aloni d'acqua. Dov'è andato?","req":["d3","t_franco"],"a":"Sarò passato sull'erba mentre fumavo in terrazza.","aside":"La terrazza è lastricata e non tocca il prato. Lo sa anche lui. Tace.","insight":"Franco mente: dopo le 21:30 ha attraversato il prato verso il parcheggio.","lie":true}]}],"bluff":{"text":"Annunci ad alta voce che nel cinturino c'è un localizzatore e che tra dieci minuti sapremo dov'è l'orologio.","reactions":{"davide":"«Meglio, così la smettete di guardare me.» Sollievo sincero.","ilenia":"Continua a sparecchiare. Nessuna reazione.","franco":"Si alza per prendere la giacca, poi ci ripensa e si risiede. Chiede quanto è preciso, un localizzatore."},"insight":"Al bluff del localizzatore solo Franco si è mosso, verso la giacca con le chiavi della macchina."},"culprit":"franco","key":["f4","i3","t_franco","x1"],"solution":"Franco è salito «al bagno» e ha preso l'orologio dal comodino, rimettendo la scatola nel cassetto come chi conosce la casa. Alle 21:45 ha attraversato il prato appena irrigato per nasconderlo nella sua berlina: Ilenia ha visto la luce interna accendersi, il camoscio delle sue scarpe si è macchiato. Il movente sta nella foto del 1979: quell'orologio suo padre l'aveva perso a carte proprio con il notaio. Franco non l'ha rubato. Secondo lui se l'è ripreso.","contradictions":[{"id":"x1","a":"f1","b":"i3","who":"franco","reply":"Va bene, sono uscito un momento. A prendere le sigarette in macchina.","aside":"Ha un sigaro in tasca. Non fuma sigarette.","insight":"Franco ha ammesso di essere andato alla sua auto alle 21:45, dopo aver giurato di non essere mai uscito.","lie":true}]},{"id":"reliquiario","title":"Il braccio d'argento","place":"Chiesa di San Fortunato, centro storico di Lecce","teaser":"Domani la processione. Stanotte il santo ha perso il braccio.","intro":"Da trecento anni, la mattina di San Fortunato, il reliquiario d'argento con l'osso del braccio del santo esce in processione per le vie di Lecce. Stamattina alle sei il sacrestano ha trovato la teca vuota e una finestra laterale in frantumi. La processione è tra dieci ore e la città vuole un colpevole entro pranzo. Il parroco ti ha chiamato perché, dice, «qui le voci corrono più veloci dei carabinieri».","details":[{"id":"d1","label":"La finestra laterale","text":"Vetro colorato in frantumi. I pezzi sono quasi tutti fuori, sul marciapiede. Dentro, solo qualche scheggia.","insight":"Il vetro è stato rotto dall'interno: l'effrazione è una messinscena."},{"id":"d2","label":"La teca","text":"Cristallo e bronzo, intatta. La piccola serratura è aperta, senza un graffio.","insight":"La teca è stata aperta con la sua chiave."},{"id":"d3","label":"La centralina dell'allarme","text":"Registro: disinserito alle 23:10 con il codice della confraternita, reinserito alle 23:24. Nessun allarme per la finestra.","insight":"Alle 23:10 qualcuno col codice della confraternita è rimasto dentro quattordici minuti. La finestra l'ha rotta lui, ad allarme spento."},{"id":"d4","label":"La bacheca della confraternita","text":"Un avviso della Curia: «Lunedì 14, inventario e perizia degli argenti sacri. Presenti il priore e un perito orafo.»","insight":"Tra tre giorni un perito avrebbe esaminato e pesato il reliquiario."},{"id":"d5","label":"La giacca del priore","text":"Appesa in sagrestia, sotto l'abito della confraternita. Nella tasca interna, una lettera della banca aperta e riaperta: «Ultimo avviso prima del pignoramento dell'immobile di via Palmieri».","insight":"Il priore sta per perdere il negozio: gli servono soldi."},{"id":"d6","label":"Il mazzo del sacrestano","text":"Sul chiodo accanto alla porta della sagrestia: tutte le chiavi della chiesa, compresa quella piccola della teca. Etichetta: «Rocco».","insight":"Rocco ha la chiave della teca, e la lascia appesa in vista."},{"id":"d7","label":"Le foto delle processioni","text":"Due foto incorniciate in sagrestia. Tre anni fa il reliquiario è opaco, quasi nero nelle pieghe. L'anno scorso brilla come appena uscito dal negozio.","insight":"L'argento annerisce da solo. Dall'anno scorso il reliquiario non annerisce più."}],"suspects":[{"id":"rocco","name":"Rocco Negro","role":"Sacrestano, 60 anni","look":"Mani da muratore, giacca della banda sulla spalla. È il primo che tutti guardano.","tell":"Ti guarda negli occhi e risponde a tutto, anche a quello che non chiedi. Quando qualcuno bisbiglia alle sue spalle si irrigidisce: è abituato a essere il primo sospettato. Le mani sono ferme. Ha paura del paese, non di te.","questions":[{"id":"r1","q":"In giro dicono che lei ha già rubato.","a":"Vent'anni fa. Rame dai tetti, a Galatina. Ho fatto il mio e ho pagato. Don Pietro mi ha preso lo stesso, e da allora qui dentro non è sparito nemmeno un cero.","insight":"Rocco ha un precedente per furto, vecchio di vent'anni."},{"id":"r2","q":"La chiave della teca è sul suo mazzo.","req":["d6"],"a":"Da trent'anni, su quel chiodo. Ma stanotte ero in piazza con la banda, prova generale, dalle dieci a mezzanotte e mezza. Suono il bombardino. Il maestro fa l'appello e c'erano trecento persone a guardare.","insight":"Rocco era alla prova della banda dalle 22 alle 00:30, davanti a trecento persone."},{"id":"r3","q":"Chi conosce il codice dell'allarme?","a":"Io ho quello della parrocchia. Quello della confraternita ce l'hanno il priore e la restauratrice, che la sera lavorava nel laboratorio dietro l'altare. La chiave della teca, invece: io e il priore. Basta.","insight":"Il codice della confraternita: il priore e Chiara. La chiave della teca: Rocco e il priore."}]},{"id":"ennio","name":"Ennio Carlà","role":"Priore della confraternita, 63 anni","look":"Abito scuro, medaglione della confraternita al collo, capelli pettinati con cura. Gira il cappello tra le mani.","tell":"Parla del furto con parole da comunicato: «gesto sacrilego», «comunità ferita». Gira il cappello senza sosta, tranne quando nomini la Curia: lì si ferma di colpo. Due volte si passa un dito nel colletto, che non gli stringe.","questions":[{"id":"e1","q":"Quando ha lasciato la chiesa?","a":"Alle nove, dopo la vestizione della statua. Ho chiuso io il portone. Poi a casa, a letto: stamattina mi alzavo alle cinque.","insight":"Il priore dice di essere andato a casa alle 21 e di non essere più uscito."},{"id":"e2","q":"Mi parli del reliquiario.","a":"Argento massiccio, Seicento napoletano. Due chili e cento. Un tesoro. L'ho fatto periziare io, tre anni fa.","insight":"Il priore giura che il reliquiario era d'argento vero."},{"id":"e3","q":"In tasca ha un avviso di pignoramento.","req":["d5"],"a":"Il negozio è chiuso da due anni. Lo sanno tutti. Che c'entra con il santo?","aside":"Lo sanno tutti, dice. Ma la lettera la tiene in chiesa, piegata in tasca, dove la moglie non la trova.","insight":"Il priore è sommerso dai debiti e lo nasconde anche in casa.","lie":true},{"id":"e4","q":"Dall'anno scorso il reliquiario non annerisce più. Come mai?","req":["d7"],"a":"L'avranno lucidato meglio. Chieda alla restauratrice, l'ha avuto lei in laboratorio.","aside":"Chiara l'ha avuto in mano due settimane fa. Non un anno fa.","insight":"Sul reliquiario che non annerisce, il priore ha scaricato subito su Chiara."}]},{"id":"chiara","name":"Chiara Montinaro","role":"Restauratrice, 36 anni","look":"Mani macchiate di pasta per argento, occhiali sulla testa. Seduta sul gradino dell'altare, fissa la teca vuota.","tell":"Si strofina il pollice sui polpastrelli, lo stesso gesto di quando lucida. Guarda la teca vuota, ma non come gli altri: le spalle le si abbassano, come a chi si toglie un peso. Quando parla il priore, lei trattiene il fiato.","questions":[{"id":"c1","q":"Dov'era stanotte?","a":"Al cinema all'aperto con mia sorella, fino a mezzanotte. Ho ancora il biglietto, lei ha le foto.","insight":"Chiara era al cinema con la sorella fino a mezzanotte."},{"id":"c2","q":"Lei ha il codice della confraternita.","a":"Sì, per il laboratorio. Ma la teca non l'ho mai aperta: la chiave non ce l'ho. Il reliquiario me lo portava il priore, e se lo riportava lui.","insight":"Chiara ha il codice dell'allarme, ma non la chiave della teca."},{"id":"c3","q":"Lei sembra sollevata. Perché?","req":["t_chiara"],"a":"(Abbassa la voce.) Perché adesso nessuno lo pesa. Quando l'ho pulito, sotto la base, dove l'argento era consumato, c'era ottone. Placcato. È una copia. L'ho detto al priore dieci giorni fa. Mi ha risposto: ci penso io, dopo la festa. E io sono stata zitta, perché era nel mio laboratorio e avrebbero pensato a me.","insight":"Il reliquiario era una copia placcata. Chiara l'aveva detto al priore dieci giorni fa.","lie":true}]}],"contradictions":[{"id":"x1","a":"e2","b":"c3","who":"ennio","reply":"Me l'ha detto, sì. Non ci ho creduto. È giovane, si sarà sbagliata.","aside":"Non ci ha creduto, ma non ha chiesto a nessuno di controllare. Ha solo aspettato che il reliquiario sparisse prima di lunedì.","insight":"Il priore sapeva che il reliquiario era falso e l'ha taciuto: sparita la copia, il perito della Curia non avrebbe trovato niente.","lie":true}],"bluff":{"text":"Annunci che i carabinieri hanno ritrovato il reliquiario in un cassonetto e che il perito della Curia lo pesa oggi stesso, prima della processione.","reactions":{"rocco":"«Grazie, San Fortunato.» Si fa il segno della croce e corre fuori a chiamare la banda.","ennio":"«Pesarlo? E perché pesarlo? L'importante è che sia tornato.» Il cappello gli scivola di mano.","chiara":"Si alza di scatto e guarda il priore. Non dice niente."},"insight":"Alla notizia del ritrovamento il priore non si è rallegrato: si è spaventato per la bilancia."},"culprit":"ennio","key":["x1","e3","r3"],"solution":"Il braccio d'argento era sparito un anno fa: sommerso dai debiti, Ennio l'aveva sostituito con una copia placcata e aveva venduto l'originale. Per un anno nessuno se n'è accorto, tranne l'argento, che ha smesso di annerire. Poi Chiara, pulendolo, ha visto l'ottone, e la Curia ha fissato la perizia per lunedì. Alle 23:10 Ennio è rientrato col codice della confraternita, ha aperto la teca con la sua chiave e ha rotto la finestra dall'interno per simulare un furto. Rocco era in piazza con la banda, Chiara al cinema: solo il priore aveva codice e chiave."},{"id":"stangadavanti","title":"L'ultima sosta","place":"Festa di San Rocco, Casamurgia (BA)","teaser":"Dodici uomini sotto il santo. Uno non arriva alla terza sosta.","intro":"A Casamurgia la statua di San Rocco la portano dodici uomini, e il posto davanti si eredita come una casa. Alla terza sosta della processione Vito Lamanna, capo dei portatori, 54 anni, si piega sotto la stanga e non si rialza più. Il medico della festa dice cuore. Sua moglie dice che Vito il cuore ce l'aveva di ferro, e ha chiesto al parroco di chiamarti.","details":[{"id":"d1","label":"La borraccia di Vito","text":"Metallo, col suo nome inciso. Ancora mezza piena. Il tappo è avvitato storto e l'acqua ha un odore amaro, che il limone non copre.","insight":"Qualcuno ha aperto la borraccia di Vito e l'ha richiusa in fretta."},{"id":"d2","label":"Il registro delle offerte","text":"Il libro del comitato. Offerte appuntate al manto del santo, processione del mattino: dichiarati 3.200 €. A margine, a matita, la grafia di Vito: «Contati io: 5.100. Parlare con N.»","insight":"Vito aveva scoperto che mancavano 1.900 € di offerte e voleva parlarne con qualcuno che comincia per N."},{"id":"d3","label":"Il foglio del medico","text":"Appunti del medico della festa: «Alla seconda sosta V.L. dice di vedere tutto giallo. Nausea. Polso irregolare. Alla terza, arresto.»","insight":"Vista gialla, nausea e aritmia: sono i segni di un avvelenamento da digitale."},{"id":"d4","label":"La foto di gruppo","text":"Sul telefono del parroco, ore 18:02: i portatori in posa davanti alla chiesa, camicie bianche e fasce rosse. Ci sono tutti. Manca solo Nicola Dimundo.","insight":"Alle 18:02 Nicola non era in piazza con gli altri portatori."},{"id":"d5","label":"Il cestino della sacrestia","text":"Tra le cartacce, un blister di digossina svuotato, farmaco per il cuore. Le compresse sono state spinte fuori tutte. L'etichetta col nome è stata strappata.","insight":"In sacrestia, dove stavano le borracce, qualcuno ha svuotato un blister di digossina."},{"id":"d6","label":"Il video della rissa","text":"Gira su tutti i telefoni del paese. Ieri sera, fuori dal bar: Lino Sisto spinge Vito contro un muro. «Sotto la stanga davanti non ci torni vivo.»","insight":"Lino ha minacciato Vito davanti a mezzo paese, per il posto davanti."},{"id":"d7","label":"Le chiavi della sacrestia","text":"Due copie soltanto. Una è del parroco, che la lascia a Dora. L'altra è del tesoriere del comitato feste.","insight":"In sacrestia potevano entrare solo Dora e il tesoriere del comitato."}],"suspects":[{"id":"lino","name":"Lino Sisto","role":"Portatore, 34 anni","look":"Spalle larghe, camicia bianca sudata, la fascia rossa ancora al collo.","tell":"Pugni stretti e mascella dura quando si parla del posto davanti. Ma quando dici «Vito è morto» gli trema il mento. La rabbia è per la stanga. Il lutto è vero.","questions":[{"id":"l1","q":"Ieri sera ha minacciato Vito davanti al bar.","req":["d6"],"a":"Ho detto una fesseria. Il posto davanti spettava a me, lui l'ha dato a suo figlio. Ma oggi alle cinque ero dal barbiere, alle sei nella foto di gruppo, alle sei e mezza sotto la stanga di sinistra. La sua borraccia non l'ho mai vista.","insight":"Lino ha un alibi dalle 17 in poi: il barbiere, la foto delle 18, la stanga dal lato opposto."},{"id":"l2","q":"Chi tiene i soldi della festa?","a":"Nicola. Tesoriere da dieci anni. Quest'anno però Vito s'era messo in testa di contare lui. Stamattina l'ha detto davanti a tutti: «Stasera i conti li guardo io.»","insight":"Vito aveva annunciato che avrebbe controllato i conti del tesoriere, Nicola."},{"id":"l3","q":"Com'era Vito prima della processione?","a":"Un toro. Ha fatto la scalinata della chiesa di corsa, per sfottere noi giovani. Poi alla seconda sosta ha bevuto dalla borraccia e ha cominciato a sudare freddo."}]},{"id":"nicola","name":"Nicola Dimundo","role":"Tesoriere del comitato feste, 47 anni","look":"Camicia bianca stirata, fascia rossa, un mazzo di chiavi alla cintura.","tell":"Ogni volta che qualcuno nomina la sacrestia si tocca il mazzo di chiavi alla cintura, come per contarle. Quando parla di Vito dice «il povero Vito». Quando parla dei soldi dice «noi».","questions":[{"id":"n1","q":"Dov'era prima della processione?","a":"In piazza coi portatori, dalle cinque. Ci sono pure nella foto di gruppo, chiedete al parroco.","insight":"Nicola dice di essere stato in piazza dalle 17, e di essere nella foto di gruppo."},{"id":"n2","q":"Vito ha contato 5.100 euro. Lei ne ha dichiarati 3.200.","req":["d2"],"a":"Il povero Vito contava male. Le banconote appuntate al manto si staccano, volano, la gente se le mette in tasca. Succede ogni anno.","aside":"Millenovecento euro volati via dal santo. Si asciuga le mani sui pantaloni.","insight":"Nicola non sa spiegare i 1.900 euro che mancano dalle offerte.","lie":true},{"id":"n3","q":"Chi prepara le borracce dei portatori?","a":"Dora, in sacrestia. Acqua e limone, dodici borracce. Poi chiude a chiave. La chiave ce l'ha lei.","aside":"Non dice che una copia ce l'ha anche lui."},{"id":"n4","q":"In sacrestia c'è un blister di digossina vuoto. E lei la ritira ogni settimana.","req":["d5","o3"],"a":"Per mio padre, che ha il cuore malato. Mezzo paese prende quella roba.","aside":"Suo padre è ricoverato a Bari da un mese. Lì le medicine gliele dà l'ospedale.","insight":"Nicola ritira la digossina di un padre che è in ospedale e non la prende più.","lie":true}]},{"id":"dora","name":"Addolorata «Dora» Fiore","role":"Sacrestana, 63 anni","look":"Vestito blu della festa, capelli appena fatti, rosario attorcigliato alle dita.","tell":"Vestito buono, piega fresca, odore di lacca. Alle cinque del pomeriggio, per riempire borracce, nessuno si veste così. Quando dice «non mi sono mossa» si liscia la gonna.","questions":[{"id":"o1","q":"Quando ha riempito le borracce?","a":"Alle cinque. Acqua fresca e una fetta di limone, come ha sempre voluto il parroco vecchio. Poi ho chiuso e non mi sono mossa da lì davanti fino alla processione.","insight":"Dora giura di non essersi mai allontanata dalla sacrestia."},{"id":"o2","q":"Alle cinque non era vestita così. Quando è andata a cambiarsi?","req":["t_dora"],"a":"(Si porta il rosario alla bocca.) Dalle cinque e mezza alle sei e mezza. Sono andata a casa a farmi i capelli, mia nipote me li fa. Mi vergognavo a dirlo. Ho lasciato il santo da solo.","insight":"Dalle 17:30 alle 18:30 la sacrestia, con le borracce, è rimasta senza nessuno.","lie":true},{"id":"o3","q":"Conosce bene Nicola?","a":"Come un figlio. Povero, col padre ricoverato a Bari da un mese. Eppure lo vedo ancora in farmacia ogni settimana a ritirare la digossina del padre. Dice che fa scorta.","insight":"Nicola continua a ritirare la digossina del padre, che è in ospedale da un mese."}]}],"bluff":{"text":"Annunci che il tappo della borraccia è già in laboratorio, e che sul metallo le impronte restano per giorni.","reactions":{"lino":"«Bene. Così vedete che le mie mani stavano sulla stanga.»","nicola":"«Le borracce le ho portate io in piazza, tutte e dodici. Le mie impronte ci sono per forza.» Nessuno gliel'aveva chiesto.","dora":"«Ci saranno le mie, le ho riempite io!» Si fa il segno della croce."},"insight":"Al bluff delle impronte Nicola ha giustificato le sue sul tappo prima che qualcuno gliele contestasse."},"culprit":"nicola","key":["x1","n4","n2"],"solution":"Nicola rubava dalle offerte appuntate al santo, e Vito se n'era accorto: «Parlare con N.». Stasera avrebbe controllato i conti davanti al comitato. Mentre gli altri posavano per la foto delle 18, Nicola era in sacrestia con la sua chiave, lasciata vuota da Dora che era andata a farsi i capelli. Ha sciolto nella borraccia di Vito la digossina che ritirava per un padre ricoverato. Alla seconda sosta Vito vedeva giallo, alla terza il cuore si è fermato. Lino aveva minacciato Vito, ma alle sei era nella foto.","contradictions":[{"id":"x1","a":"n1","b":"d4","who":"nicola","reply":"Sono arrivato dopo, va bene. Ero in sacrestia a contare le offerte del mattino. Da solo.","aside":"Le offerte stasera doveva contarle Vito. Lo sapeva tutto il paese.","insight":"Alle 18 Nicola era solo in sacrestia con le borracce, e aveva mentito.","lie":true}]},{"id":"faroscialara","title":"Il faro di Punta Scialara","place":"Faro di Punta Scialara, costa di Vieste","teaser":"Centodiciassette gradini di ghisa. Il guardiano li conosceva a occhi chiusi.","intro":"Onofrio Lauriola, 71 anni, guardiano del faro da quaranta, è stato trovato all'alba in fondo alla scala a chiocciola. Per i carabinieri è scivolato: età, buio, gradini di ferro. Il figlio dice che suo padre quella scala la faceva anche dormendo. Tu guardi le pantofole ai piedi del morto e cominci a dargli ragione.","details":[{"id":"d1","label":"La scala a chiocciola","text":"Onofrio è in pantofole. A metà scala, sui gradini, impronte di sabbia bagnata e un filo d'alga ancora verde.","insight":"Stanotte qualcuno è salito nel faro dritto dalla spiaggia. Non Onofrio, che era in pantofole."},{"id":"d2","label":"Il registro del faro","text":"Ultima riga, ore 01:35, grafia tremante: «Di nuovo la barca senza fanali alla Cala del Monaco. Quarta volta. Scendo sul ballatoio a fotografarla col tele.»","insight":"All'1:35 Onofrio stava fotografando una barca senza luci nella cala sotto il faro."},{"id":"d3","label":"La macchina fotografica","text":"Sul ballatoio, una reflex con l'obiettivo lungo. Lo sportello della scheda è aperto. La scheda non c'è.","insight":"Chi l'ha ucciso si è preso le foto: il movente è in quelle foto."},{"id":"d4","label":"La lettera del resort","text":"Un'offerta della Scialara Retreat per trasformare il faro in suite di lusso. Sopra, un post-it di Onofrio: «Mai. Sopra il mio cadavere.»","insight":"La società del resort voleva il faro. Onofrio si opponeva."},{"id":"d5","label":"La Cala del Monaco","text":"Sulla sabbia, il solco fresco di una chiglia tirata a secco. Tra gli scogli, una martellina con il manico fasciato di cima blu e schegge di roccia bianca appena spaccata.","insight":"Nella cala qualcuno ha spaccato gli scogli: così si cavano i datteri di mare, pesca vietata."},{"id":"d6","label":"Il telefono di Onofrio","text":"Ultima chiamata in uscita alle 00:50, a «Tonino». Durata tre minuti.","insight":"Alle 00:50 Onofrio era sveglio e ha parlato con il figlio."},{"id":"d7","label":"Il pugno di Onofrio","text":"La mano destra è chiusa. Dentro, un bottone di corno scuro con un filo blu strappato.","insight":"Onofrio ha strappato un bottone a chi l'ha aggredito."}],"suspects":[{"id":"michele","name":"Michele Frattaruolo","role":"Pescatore, padrone della Santa Rosa","look":"Giaccone da marinaio blu, stivali di gomma, pelle cotta dal sale. È venuto «a vedere», dice.","tell":"Tiene il giaccone chiuso con la mano sinistra, come se avesse freddo, e fuori ci sono diciotto gradi. Quando si sposta la mano si vede che al secondo occhiello manca il bottone: il filo blu è ancora lì, strappato e pulito.","questions":[{"id":"m1","q":"Dov'era stanotte?","a":"A letto. Col maestrale che tirava non è uscito nessuno. Chieda al porto.","insight":"Michele giura di non essere uscito in mare stanotte."},{"id":"m2","q":"Conosceva Onofrio?","a":"Lo conoscevano tutti. Stava sempre col binocolo, a guardare il mare degli altri. Uno così prima o poi qualcosa lo vede.","aside":"Non dice «vedeva». Dice «qualcosa lo vede». Come una cosa pensata da tempo.","insight":"A Michele non andava giù che Onofrio sorvegliasse il mare."},{"id":"m3","q":"Onofrio stringeva un bottone di corno. Al suo giaccone ne manca uno.","req":["d7","t_michele"],"a":"L'ho perso settimane fa. Al porto, scaricando le cassette.","aside":"Il filo rimasto nell'occhiello è blu acceso. Un filo strappato da settimane, al porto, sarebbe già grigio di salsedine.","insight":"Michele mente sul bottone: l'ha perso stanotte, nel pugno di Onofrio.","lie":true}]},{"id":"ilaria","name":"Ilaria Notarangelo","role":"Architetta della Scialara Retreat","look":"Tailleur chiaro, cartellina sotto il braccio, occhiali da sole anche all'ombra.","tell":"Guarda l'orologio ogni due minuti e chiama il faro «l'immobile». È fredda, ma non evita mai una domanda e non ti fa aspettare le risposte: è impazienza, non paura.","questions":[{"id":"i1","q":"Onofrio aveva scritto: «Sopra il mio cadavere».","req":["d4"],"a":"Una frase da vecchio testardo. Ieri abbiamo litigato in piazza, lo sa mezza Vieste. Ma io gli immobili li compro con gli avvocati, non con le scale.","insight":"Ilaria aveva litigato in pubblico con Onofrio il giorno prima."},{"id":"i2","q":"Dov'era stanotte?","a":"A cena a Peschici con due assessori, fino all'una e mezza. Poi in albergo. Il portiere di notte mi ha dato la chiave alle due meno un quarto.","insight":"Ilaria ha un alibi verificabile: la cena con gli assessori e il portiere dell'albergo."},{"id":"i3","q":"Conosce Michele Frattaruolo?","a":"Il pescatore? Ieri sera, a cena, il cuoco ci ha offerto dei datteri di mare «fuori menu». Ha detto che glieli porta Michele, di nascosto. Io non li ho toccati: sono vietati, e io con gli assessori ci lavoro.","insight":"Michele vende di nascosto datteri di mare ai ristoranti."}]},{"id":"tonino","name":"Tonino Lauriola","role":"Figlio di Onofrio, 38 anni","look":"Occhi gonfi, felpa della squadra di calcio del paese. Non si siede.","tell":"La voce si rompe ogni volta che dice «papà», e lì il dolore è vero. Quando si nomina il resort si gratta il collo e guarda altrove: è vergogna, non colpa.","questions":[{"id":"t1","q":"Quando ha sentito suo padre l'ultima volta?","a":"Mi ha chiamato all'una meno dieci. Diceva: stanotte li fotografo, domani chiamo la Capitaneria. Gli ho detto di lasciar perdere, che non erano affari suoi.","insight":"Onofrio voleva fotografare la barca e denunciarla alla Capitaneria."},{"id":"t2","q":"Dov'era lei stanotte?","a":"In macchina sulla litoranea, tornavo da Mattinata. Verso l'una e mezza ho visto una barca senza luci entrare nella Cala del Monaco. Bianca, con la fascia verde. Da queste parti così c'è solo la Santa Rosa. Quella di Michele.","insight":"All'1:30 la Santa Rosa di Michele entrava senza luci nella cala sotto il faro."},{"id":"t3","q":"La società del resort le aveva offerto qualcosa?","req":["d4"],"a":"La gestione del bar. Se papà firmava. Non gliel'ho mai detto. Non me l'avrebbe perdonato.","insight":"Tonino avrebbe guadagnato dalla vendita del faro, e lo teneva nascosto.","lie":true}]}],"bluff":{"text":"Dici che la macchina fotografica caricava le foto da sola su internet, e che la Capitaneria le sta già guardando.","reactions":{"michele":"Si volta verso il mare, verso la cala. Poi chiede, piano, se al buio si riconosce una barca o si vede solo nero.","ilaria":"«Bene. Così la smettete di guardare me.»","tonino":"«Papà? Internet?» Poi ci pensa: «Gliel'ho regalata io quella macchina. Non so nemmeno se ce l'ha, il wifi.»"},"insight":"Al bluff delle foto Michele non si è chiesto chi fosse stato: si è chiesto se la barca si riconosceva."},"culprit":"michele","key":["m3","x1","d7"],"solution":"Da settimane Onofrio vedeva una barca senza luci alla Cala del Monaco: era la Santa Rosa di Michele, che spaccava gli scogli per cavare datteri di mare e venderli sottobanco ai ristoranti. Stanotte Onofrio la fotografa col tele e Michele vede il riflesso sul ballatoio. Sbarca, sale nel faro lasciando sabbia sui gradini, lotta con il vecchio e lo spinge giù per la scala, poi si prende la scheda. Ma all'una e mezza Tonino aveva già riconosciuto la sua barca dalla litoranea, e nel pugno di Onofrio è rimasto il bottone del suo giaccone. Il resort voleva il faro, ma Ilaria a quell'ora era a cena con due assessori.","contradictions":[{"id":"x1","a":"m1","b":"t2","who":"michele","reply":"Va bene, sono uscito. Mezz'ora, per i ricci. Il faro non l'ho nemmeno guardato.","aside":"I ricci si prendono di giorno, con la maschera. Di notte, spaccando gli scogli, si prendono i datteri.","insight":"Michele ammette di essere stato alla Cala del Monaco stanotte, sotto il faro, dopo aver giurato di non essere uscito.","lie":true}]},{"id":"frantoio","title":"La partita 14","place":"Frantoio Scarano, campagne di Bitonto","teaser":"Un frantoiano ai piedi del silo. Sembra un incidente.","intro":"All'alba del primo giorno di raccolta, Nicola Scarano, 67 anni, viene trovato morto ai piedi della scala del silo. I carabinieri parlano di caduta. Il figlio non ci crede e ti ha chiamato. Sul piazzale ci sono tre persone che avevano motivi per odiarlo, o per temerlo.","details":[{"id":"d1","label":"La scala del silo","text":"Nicola è a terra ai piedi della scala. Sui pioli non c'è una traccia di fango, mentre le sue scarpe sono impastate di terra del piazzale.","insight":"Nicola non è salito su quella scala: la caduta è una messinscena."},{"id":"d2","label":"Il registro delle molature","text":"Ultima riga, grafia di Nicola, ore 23:40: «Partita 14: NON certificare. Chiamare la Greco.»","insight":"Poco prima di morire Nicola ha bloccato la partita 14 e voleva parlare con Marta Greco."},{"id":"d3","label":"Il bicchiere blu","text":"Sul banco d'assaggio, un bicchiere blu da degustazione, di quelli che usano solo gli assaggiatori professionisti. Il fondo è ancora lucido d'olio.","insight":"Stanotte qualcuno ha assaggiato olio qui, con un bicchiere da professionista."},{"id":"d4","label":"Il cancello","text":"Il lucchetto è stato aperto con la chiave. Nessun segno di scasso.","insight":"Chi è entrato stanotte aveva la chiave."},{"id":"d5","label":"L'offerta d'acquisto","text":"Sulla scrivania, un'offerta da 2 milioni di una multinazionale dell'olio. Firmata da Antonio. Manca la firma del padre.","insight":"Antonio voleva vendere il frantoio, il padre no."},{"id":"d6","label":"La bacheca delle chiavi","text":"Un mazzo con l'etichetta «Pinto, restituite ieri ore 18».","insight":"Sandro ha restituito le chiavi ieri pomeriggio."},{"id":"d7","label":"Il telefono di Nicola","text":"Ultima chiamata in uscita alle 23:45, a «Marta Greco». Durata 41 secondi.","insight":"Alle 23:45 Nicola ha chiamato Marta Greco."}],"suspects":[{"id":"antonio","name":"Antonio Scarano","role":"Figlio, 35 anni","look":"Occhi rossi, felpa infilata al contrario. È lui che ti ha chiamato.","tell":"Le lacrime arrivano quando ricorda il padre da vivo, non quando si parla di soldi. Il senso di colpa c'è, ma riguarda l'ultima lite, non la morte.","questions":[{"id":"a1","q":"Dov'era stanotte?","a":"A casa. Mia figlia aveva la febbre, alle due ho chiamato la guardia medica. Potete controllare.","insight":"Antonio ha un alibi verificabile: la chiamata delle due alla guardia medica."},{"id":"a2","q":"Lei voleva vendere, suo padre no.","req":["d5"],"a":"Sì. Ieri ci siamo urlati addosso. L'ultima cosa che gli ho detto è stata «sei un vecchio testardo».","aside":"Si copre la faccia con le mani. Il pianto è vero."},{"id":"a3","q":"Chi ha le chiavi del frantoio?","a":"Io, papà e Marta Greco, la consulente. Le servono per i campionamenti. Sandro le aveva fino a ieri.","insight":"Le chiavi le hanno Antonio, Nicola e Marta. Sandro le aveva fino a ieri."}]},{"id":"sandro","name":"Sandro Pinto","role":"Operaio, licenziato ieri","look":"Mani grandi, voce alta. Si è presentato da solo appena ha saputo.","tell":"Alza la voce e ti guarda in faccia. È la rabbia rumorosa di chi si sente accusato ingiustamente. Chi mente di solito abbassa il volume.","questions":[{"id":"s1","q":"Perché l'hanno licenziata?","a":"Perché ho detto che la partita 14 puzzava di olio di semi. Mi ha dato del bugiardo. Poi ieri sera alle undici mi scrive: «Avevi ragione tu. Domani sistemo tutto.» Guardi, è qui.","insight":"Ieri sera Nicola ha scoperto che la partita 14 era tagliata con olio di semi."},{"id":"s2","q":"Dov'era stanotte?","a":"Al bar Centrale fino all'una, poi a casa. Chiedete a Mimmo, il barista."},{"id":"s3","q":"Chi certifica l'olio che esce da qui?","a":"La Greco. Assaggia lei e firma lei. Tutto quello che esce da qui come extravergine passa dalla sua firma.","insight":"Marta firma le certificazioni: la partita 14 l'avrebbe firmata lei."}]},{"id":"marta","name":"Marta Greco","role":"Assaggiatrice e consulente, 42 anni","look":"Impeccabile anche all'alba. Profumo costoso, taccuino in pelle.","tell":"Risponde prima che tu finisca la domanda: risposte preparate. Quando si nomina il registro si sistema un orecchino che era già a posto.","questions":[{"id":"m1","q":"Quando ha visto Nicola l'ultima volta?","a":"Ieri alle otto di sera, qui. Poi sono andata a casa. Da sola, purtroppo.","insight":"Marta dice di essere andata via alle 20 e di non essere più tornata."},{"id":"m2","q":"Nicola l'ha chiamata alle 23:45. Che cosa voleva?","req":["d7"],"a":"Ah, la chiamata. Parlavamo della raccolta di domani. Quaranta secondi, niente di importante.","insight":"Marta aveva taciuto la telefonata delle 23:45.","lie":true},{"id":"m3","q":"C'è un suo bicchiere da assaggio ancora lucido d'olio.","req":["d3","m1"],"a":"Ne lascio sempre qualcuno in giro. Sarà di ieri pomeriggio.","aside":"In dodici ore l'olio su un bicchiere si opacizza e fa la pellicola. Questo brilla.","insight":"Marta mente: ha assaggiato olio qui stanotte, dopo la chiamata.","lie":true},{"id":"m4","q":"Parliamo della partita 14.","req":["d2"],"a":"Io certifico quello che assaggio. Punto.","aside":"Poi, dopo un attimo: «Chi le ha parlato della partita 14?»","insight":"Sulla partita 14 Marta non si difende: vuole sapere chi ha parlato."}]}],"bluff":{"text":"Dici che la settimana scorsa Nicola aveva fatto installare una telecamera nel magazzino, e che non lo sapeva nessuno.","reactions":{"antonio":"«Papà? Una telecamera? Non si fidava nemmeno del bancomat.»","sandro":"«Meglio! Guardatela, così la finite con me.»","marta":"Chiede, con voce neutra, se la telecamera registra anche l'audio. Nessun altro lo chiede."},"insight":"Al bluff della telecamera Marta ha chiesto dell'audio: le preoccupa quello che si è detto, non quello che si è visto."},"culprit":"marta","key":["m3","m2","x1"],"solution":"Sandro aveva ragione: la partita 14 era tagliata con olio di semi e Marta l'aveva certificata extravergine per un compratore che la pagava bene. Ieri sera Nicola se ne accorge, blocca la partita sul registro e alle 23:45 la chiama. Marta arriva con la sua chiave e assaggia l'olio davanti a lui per convincerlo che sbaglia. Nicola minaccia di denunciarla. Lei lo colpisce e trascina il corpo ai piedi del silo per simulare una caduta, ma sui pioli non c'è il fango delle sue scarpe. E il bicchiere blu è rimasto sul banco.","contradictions":[{"id":"x1","a":"m2","b":"d2","who":"marta","reply":"Va bene. Mi ha parlato della partita 14. Gli ho detto che si sbagliava. Tutto qui.","aside":"Tutto qui, in quaranta secondi. Eppure stanotte l’olio l’ha assaggiato qui.","insight":"Marta ha mentito sulla chiamata: Nicola le aveva contestato la partita 14.","lie":true}]},{"id":"pittule","title":"Foglie d'alloro","place":"Sagra della pittula, Martano","teaser":"Il presidente della sagra crolla alla cassa. Il suo infuso non era d'alloro.","intro":"Ieri sera, alla chiusura della Sagra della pittula, Gigi Pellegrino, presidente del comitato, si è accasciato dietro la cassa con il cuore impazzito. È in cardiologia a Lecce, vivo per miracolo: nel sangue gli hanno trovato il veleno dell'oleandro. In paese tutti fanno lo stesso nome, quello del friggitore che Gigi ha cacciato dalla sagra. Il figlio di Gigi non ci crede, e ti ha chiesto di passare prima che smontino gli stand.","details":[{"id":"d1","label":"La tazza di Gigi","text":"Tazza di smalto con la scritta PRESIDENTE. Sul fondo, un dito d'infuso freddo e due foglie lunghe, strette, dure come cuoio, con una nervatura bianca al centro.","insight":"Nella tazza di Gigi c'erano foglie d'oleandro, non d'alloro."},{"id":"d2","label":"Il pentolone dell'infuso","text":"In cucina, il pentolone dell'infuso di fine serata. Foglie larghe e ovali, bucce di limone. L'hanno bevuto in dodici, volontari compresi. Nessuno sta male.","insight":"L'infuso della pentola era innocuo: l'oleandro è finito solo nella tazza di Gigi."},{"id":"d3","label":"La siepe dietro la cassa","text":"Oleandri fioriti, a un passo dal bancone della cassa. Due rametti spezzati di fresco: sul taglio, lattice bianco ancora appiccicoso.","insight":"Ieri sera qualcuno ha strappato foglie d'oleandro proprio dietro la cassa."},{"id":"d4","label":"L'agenda di Gigi","text":"Nella borsa del comitato. Alla data di ieri, a matita: «Dopo la chiusura: conti con Ada. 2019-2024, mancano 11.000?»","insight":"Gigi aveva trovato un ammanco e voleva fare i conti con Ada subito dopo la sagra."},{"id":"d5","label":"Il video di Tonino","text":"Sul telefono di un volontario, ore 20:20: Tonino Russo urla davanti allo stand delle pittule. «Te ne pentirai, Gigi! Te ne pentirai!»","insight":"Tonino ha minacciato Gigi davanti a mezza piazza."},{"id":"d6","label":"Il cestino della cassa","text":"Tra gli scontrini, un paio di guanti in lattice, di quelli per contare le monete. Sulle dita, macchie verdi e un velo di lattice bianco rappreso.","insight":"Con i guanti della cassa qualcuno ha maneggiato foglie fresche."},{"id":"d7","label":"Il messaggio del cardiologo","text":"Il figlio di Gigi ti mostra il telefono: «Glicosidi dell'oleandro. Ingestione probabile tra le 21:30 e le 22:30.»","insight":"Gigi ha ingerito il veleno tra le 21:30 e le 22:30."}],"suspects":[{"id":"ada","name":"Ada Mele","role":"Tesoriera del comitato, 54 anni","look":"Cardigan abbottonato fino al collo nonostante il caldo. La borsa della cassa stretta sulle ginocchia.","tell":"Tiene le mani chiuse a pugno sopra la borsa. Quando le apre per gesticolare, i polpastrelli sono arrossati, come di chi se li è strofinati a lungo. Chiede due volte come sta Gigi, e tutte e due le volte non aspetta la risposta.","questions":[{"id":"a1","q":"Dov'era ieri sera?","a":"Alla cassa, dalle sette a mezzanotte. Non mi sono mossa un minuto. Chi lascia la cassa di una sagra è un pazzo.","insight":"Ada dice di non essersi mai mossa dalla cassa."},{"id":"a2","q":"Ha visto la tazza di Gigi, ieri sera?","a":"No. L'infuso Gigi se lo beveva in cucina, con le cuoche. Alla cassa non l'ho mai vista.","insight":"Ada giura che la tazza di Gigi non è mai passata dalla cassa."},{"id":"a3","q":"Stanotte Gigi voleva fare i conti con lei. Mancano undicimila euro.","req":["d4"],"a":"Gigi i conti li sbaglia dal 2019. Sono conti suoi, non miei. Glielo dimostro con i quaderni.","aside":"Dice «quaderni». Il comitato tiene i conti al computer da tre anni.","insight":"Ada sapeva dell'ammanco, e sapeva che Gigi voleva parlarne stanotte.","lie":true},{"id":"a4","q":"I guanti della cassa sono macchiati di verde.","req":["d6"],"a":"Sono i miei, per le monete. Il verde? Avrò toccato la siepe. Ci si appoggiano tutti.","aside":"È una siepe d'oleandro. Non ci si appoggia nessuno.","insight":"Ada ammette di aver toccato la siepe d'oleandro con i guanti della cassa.","lie":true}]},{"id":"pamela","name":"Pamela Stifani","role":"Cuoca volontaria, 31 anni","look":"Grembiule infarinato, occhi gonfi. Ha ancora la retina nei capelli.","tell":"Si torce le mani nel grembiule e guarda il pentolone come si guarda una colpa. Ogni volta che qualcuno dice «veleno» trattiene il fiato. È il senso di colpa di chi crede di aver sbagliato, non di chi l'ha fatto apposta.","questions":[{"id":"p1","q":"Chi prepara l'infuso di Gigi?","a":"Io. Ogni sera: alloro del mio orto e bucce di limone. L'abbiamo bevuto tutti, dalla stessa pentola. Io due tazze.","insight":"Tutti hanno bevuto l'infuso dalla stessa pentola di Pamela."},{"id":"p2","q":"Chi ha portato la tazza a Gigi?","a":"Io, alle dieci meno cinque, alla cassa. Era lì con Ada a contare. Poi l'hanno chiamato sul palco per la lotteria e la tazza è rimasta sul bancone, accanto a lei. Venti minuti, più o meno.","insight":"Dalle 22 la tazza di Gigi è rimasta venti minuti sul bancone della cassa, accanto ad Ada, mentre lui era sul palco."},{"id":"p3","q":"Le foglie nella tazza sono del suo alloro?","req":["d1"],"a":"(Ne prende una e la gira.) Questa non è alloro. L'alloro è largo e profuma. Questa è dura, lunga... è oleandro. Come la siepe dietro la cassa. Io l'oleandro non lo tocco nemmeno per i fiori.","aside":"Si siede. Per la prima volta da stamattina respira.","insight":"Pamela riconosce le foglie: oleandro, come la siepe dietro la cassa."}]},{"id":"tonino","name":"Tonino Russo","role":"Friggitore, 58 anni","look":"Camicia a fiori aperta sul petto, voce che si sente dall'altra parte della piazza. È venuto da solo, «per chiarire».","tell":"Urla, ma ti guarda in faccia mentre urla e aspetta la tua risposta. Chi ha colpa urla guardando altrove. Quando nomini Gigi in ospedale gli trema il mento per un attimo: si conoscono da quarant'anni.","questions":[{"id":"t1","q":"Ieri sera ha minacciato Gigi davanti a tutti.","req":["d5"],"a":"Mi ha tolto lo stand dopo vent'anni! Gli ho detto di tutto, sì. Alle otto e venti. Poi sono tornato al mio locale a Calimera: trenta coperti, due camerieri, fino all'una. Chieda a chiunque.","insight":"Dalle 20:30 all'una Tonino era nel suo locale a Calimera, con trenta clienti."},{"id":"t2","q":"Perché Gigi l'ha cacciata?","a":"Dice per l'igiene. Io dico perché a novembre gli ho detto che la cassa della sagra non tornava. «Gigi, guarda chi conta i soldi.» Ecco la ricompensa.","insight":"Tonino aveva avvertito Gigi che i soldi della sagra non tornavano."},{"id":"t3","q":"Chi sta alla cassa, di solito?","a":"Sempre lei, la Mele. Da dieci anni. Non dà il cambio a nessuno, nemmeno per andare in bagno. Uno se lo chiede, perché.","insight":"Da dieci anni Ada non lascia la cassa a nessuno."}]}],"contradictions":[{"id":"x1","a":"a2","b":"p2","who":"ada","reply":"Ah, quella tazza. Può darsi. C'era tanta gente, chi se la ricorda una tazza.","aside":"Una tazza con scritto PRESIDENTE, a un palmo dalle sue mani, per venti minuti.","insight":"Ada ha mentito: la tazza di Gigi è rimasta venti minuti sola accanto a lei, alla cassa.","lie":true}],"bluff":{"text":"Annunci che Gigi si è svegliato e che nel pomeriggio parlerà con i carabinieri.","reactions":{"ada":"«Poverino. Con tutti quei farmaci sarà confuso, dirà cose senza senso.» Lo dice prima che qualcuno le chieda cosa ne pensa.","pamela":"Scoppia a piangere e si fa il segno della croce due volte.","tonino":"«Allora ditegli che Tonino non c'entra.» Ride, poi si asciuga gli occhi col dorso della mano."},"insight":"Alla notizia del risveglio di Gigi, Ada si è preoccupata di screditare quello che avrebbe detto."},"culprit":"ada","key":["x1","a4","a3"],"solution":"Da anni Ada si teneva una parte dell'incasso della sagra, e Tonino l'aveva capito prima di tutti. Gigi aveva rifatto i conti e voleva chiuderli con lei la sera stessa. Alle dieci, quando è salito sul palco per la lotteria, la sua tazza è rimasta sul bancone accanto ad Ada: lei ha strappato due foglie dalla siepe alle sue spalle, con i guanti della cassa, e le ha lasciate nell'infuso. Il pentolone era innocuo e Pamela non c'entrava. Tonino, a quell'ora, friggeva a Calimera davanti a trenta clienti."},{"id":"spartitomonteleone","title":"Notte sul porto","place":"Teatro Galante, Bari","teaser":"Una prima col sindaco in sala. Una vetrina vuota all'intervallo.","intro":"Il Teatro Galante riapre dopo tre anni con «Notte sul porto» di Saverio Monteleone. Nel foyer, sotto vetro, lo spartito autografo del 1891, il tesoro del teatro. Quando all'intervallo il pubblico esce, la vetrina è vuota e chiusa a chiave. Trecento persone nel foyer, tutte sospettate. Il sovrintendente vuole la polizia; il sindaco vuole prima te, e senza giornalisti.","details":[{"id":"d1","label":"La vetrina","text":"Richiusa a chiave, vetro intatto, nessun graffio sulla serratura. Sul velluto resta il segno rettangolare dello spartito.","insight":"Chi ha preso lo spartito ha aperto la vetrina con una chiave."},{"id":"d2","label":"Il registro della vigilanza","text":"«19:30 — allarme vetrina foyer escluso. Motivo: falsi allarmi ripetuti. Autorizza: direzione.»","insight":"L'allarme della vetrina è stato spento alle 19:30 su ordine della direzione."},{"id":"d3","label":"La polizza","text":"Rinnovata tre settimane fa. Valore assicurato dello spartito: da 200.000 a 900.000 €. Beneficiario: il teatro. Firma del sovrintendente.","insight":"Tre settimane prima del furto il valore assicurato è stato più che quadruplicato."},{"id":"d4","label":"La borsa di Samuele","text":"Sotto il leggio in buca: fotocopie dello spartito, pagina per pagina, fitte di annotazioni a matita.","insight":"Samuele conosce lo spartito a memoria, nota per nota."},{"id":"d5","label":"La cassaforte della direzione","text":"La chiave di riserva della vetrina è al suo posto. Accanto, una lettera di un antiquario di Ginevra: «Confermo l'interesse del mio cliente. Massima discrezione.»","insight":"Qualcuno della direzione è in contatto con un compratore privato all'estero."},{"id":"d6","label":"Il guardaroba","text":"Un tubo portadisegni nero, scontrino 17, depositato alle 20:35. Il primo atto era cominciato da mezz'ora. La guardarobiera ricorda solo «un signore in smoking». Stasera sono tutti in smoking.","insight":"Durante il primo atto, con il foyer vuoto, qualcuno ha lasciato un tubo portadisegni al guardaroba."},{"id":"d7","label":"Il programma di sala","text":"Primo atto: 20:00-21:15, senza interruzioni. A matita, qualcuno ha segnato «20:40 — assolo al pianoforte».","insight":"Il primo atto dura 75 minuti senza pause: chi è in buca non può uscire."}],"suspects":[{"id":"aldo","name":"Aldo Ferrante","role":"Sovrintendente del teatro, 61 anni","look":"Smoking impeccabile, garofano all'occhiello, voce da conferenza stampa.","tell":"Parla del teatro al passato: «era un gioiello», «avevamo un pubblico». Mentre ti ascolta tocca due volte il taschino dello smoking, dove si vede il bordo di un cartoncino.","questions":[{"id":"a1","q":"Dov'era durante il primo atto?","a":"Nel mio palco, dall'inizio alla fine, accanto al sindaco. Non ho perso una nota.","insight":"Aldo giura di non aver lasciato il palco durante il primo atto."},{"id":"a2","q":"Tre settimane fa ha fatto quadruplicare l'assicurazione.","req":["d3"],"a":"Valore di mercato aggiornato. Un Monteleone autografo vale quello. Lo dice il perito.","aside":"Non dice che il perito l'ha scelto lui.","insight":"Aldo ha alzato l'assicurazione a 900.000 euro poco prima del furto."},{"id":"a3","q":"L'allarme della vetrina l'ha fatto spegnere lei.","req":["d2"],"a":"Suonava ogni cinque minuti, alla prima, col sindaco in sala! Cosa dovevo fare, farlo suonare durante l'ouverture?","insight":"Aldo ammette di aver fatto spegnere l'allarme della vetrina alle 19:30."}]},{"id":"samuele","name":"Samuele Loiacono","role":"Maestro al pianoforte, 33 anni","look":"Frac un po' largo, capelli spettinati, dita macchiate di matita.","tell":"Quando parla dello spartito gli brillano gli occhi e muove le dita come se suonasse. Quando parli di furto si chiude, braccia conserte. È orgoglio ferito, non paura.","questions":[{"id":"s1","q":"Dov'era durante il primo atto?","a":"In buca, al pianoforte. Settantacinque minuti senza respirare. Alle 20:40 c'è il mio assolo, l'hanno sentito in duecento. Chieda al direttore d'orchestra.","insight":"Samuele era in buca per tutto il primo atto, e alle 20:40 suonava davanti a tutti."},{"id":"s2","q":"Lei ha fotocopiato lo spartito pagina per pagina.","req":["d4"],"a":"Lo studio da due anni. Sì, penso che stia meglio in un archivio che sotto una lampada in foyer. E sì, a Lecce mi hanno già accusato di aver rubato una lettera. Assolto. Lo sanno tutti, per questo guardate me.","insight":"Samuele è stato accusato di un furto d'archivio in passato, e assolto."},{"id":"s3","q":"Come stanno i conti del teatro?","a":"Male. Noi orchestrali non vediamo uno stipendio da aprile. Il sovrintendente ripete che «presto arriveranno soldi». Non ha mai detto da dove.","insight":"Il teatro è al verde e Aldo aspetta soldi «presto»."}]},{"id":"tonino","name":"Tonino Scarpa","role":"Custode del teatro, 62 anni","look":"Divisa blu, auricolare nell'orecchio, una sola chiave appesa al collo.","tell":"Odore di sigaretta sulla divisa. Ogni tanto sbircia il telefono tenuto basso: c'è la partita del Bari in diretta. Non è mai rimasto davanti a una vetrina in vita sua durante una partita.","questions":[{"id":"c1","q":"Dov'era durante il primo atto?","a":"Al mio posto, in foyer, vicino alla vetrina. Non è passato nessuno. Lo giuro sui miei figli.","insight":"Tonino giura di aver sorvegliato la vetrina per tutto il primo atto."},{"id":"c2","q":"Lei non era in foyer. Era a guardare la partita.","req":["t_tonino"],"a":"(Si toglie l'auricolare.) All'ingresso artisti. Lì il telefono prende. Verso le otto e mezza è sceso il sovrintendente dalla scala di servizio, con un tubo nero sotto il braccio. Mi ha fatto un cenno e ha tirato dritto verso il foyer. Io ho nascosto il telefono.","insight":"Verso le 20:30 Aldo è sceso dalla scala di servizio verso il foyer con un tubo nero.","lie":true},{"id":"c3","q":"Chi ha le chiavi della vetrina?","a":"Io, questa qui, sempre al collo. E la riserva, nella cassaforte del sovrintendente. Solo lui ha la combinazione.","insight":"La chiave di riserva della vetrina sta in una cassaforte che apre solo Aldo."}]}],"bluff":{"text":"Annunci che a fine spettacolo la polizia aprirà tutto quello che c'è al guardaroba, cappotto per cappotto.","reactions":{"aldo":"Si tocca il taschino dove c'è il cartoncino. Poi dice che è una perdita di tempo: «Il ladro sarà già a Brindisi.»","samuele":"«Aprite pure. Io ho un giubbotto e un ombrello.»","tonino":"«Il guardaroba? E che c'entra il guardaroba?» Guarda il telefono."},"insight":"Al bluff del guardaroba Aldo si è toccato il taschino con lo scontrino, e ha cercato di spostare le indagini lontano da lì."},"culprit":"aldo","key":["x1","c2","a2"],"solution":"Il furto non è avvenuto all'intervallo ma durante il primo atto, con il foyer vuoto. Alle 19:30 Aldo fa spegnere l'allarme. Alle 20:30 scende dalla scala di servizio, apre la vetrina con la chiave della sua cassaforte, arrotola lo spartito nel tubo e lo lascia al guardaroba: lo scontrino 17 ce l'ha nel taschino. Il teatro è al verde: Aldo avrebbe incassato 900.000 € dall'assicurazione e venduto l'originale a Ginevra. Samuele, il sospettato perfetto, alle 20:40 suonava davanti a duecento persone.","contradictions":[{"id":"x1","a":"a1","b":"c2","who":"aldo","reply":"Sono sceso un momento. Un problema con le luci del foyer.","aside":"Le luci si comandano dalla cabina, al terzo piano. Lui è sceso al pianterreno. Con un tubo.","insight":"Aldo ha lasciato il palco durante il primo atto e l'aveva negato.","lie":true}]},{"id":"trullostella","title":"Il trullo di troppo","place":"Trullo Stella, rione Monti, Alberobello","teaser":"Tre famiglie, un solo trullo. E il proprietario non risponde più.","intro":"Una coppia di Torino arriva al Trullo Stella con la ricevuta di un bonifico da 1.400 euro. Dentro c'è già un altro ospite, con un'altra prenotazione. Nel pomeriggio ne arrivano altri due. Il proprietario, Donato Recchia, 81 anni, è sparito da ieri mattina. In paese dicono che è scappato con i soldi. Tu pensi che un uomo di ottantun anni non sappia nemmeno cosa sia un bonifico online.","details":[{"id":"d1","label":"L'annuncio clonato","text":"Stesse foto del Trullo Stella, 90 euro a notte invece di 160, «pagamento anticipato con bonifico». L'IBAN è di una banca online. Intestatario: Donato Recchia.","insight":"I soldi dei turisti truffati finivano su un conto online a nome di Donato."},{"id":"d2","label":"La cassetta della posta","text":"Una busta della stessa banca online: «Ecco la tua nuova carta». È ancora sigillata. Il timbro è di due mesi fa.","insight":"Donato non ha mai aperto la posta di quella banca: il conto non l'ha aperto lui."},{"id":"d3","label":"Il raccoglitore dell'agenzia","text":"Tra i documenti degli ospiti, una fotocopia a colori, fronte e retro, della carta d'identità di Donato. È quella rinnovata a marzo. Accanto, la tessera sanitaria.","insight":"L'agenzia aveva copie recenti dei documenti di Donato: bastano per aprire un conto online."},{"id":"d4","label":"La casa di Donato","text":"Letto rifatto. Mancano le medicine per il cuore, il rasoio, la coppola della domenica.","insight":"Donato è partito da solo e con calma. Non l'ha portato via nessuno."},{"id":"d5","label":"Il cellulare di Donato","text":"Un vecchio telefono a tasti, lasciato sul tavolo della cucina. Ultimo SMS, ieri alle 7:12, da un numero non in rubrica: «Zio la finanza ti cerca per gli affitti in nero. Sparisci qualche giorno e lascia il telefono, ti rintracciano. Non dire niente a nessuno. G.»","insight":"Ieri alle 7:12 qualcuno firmato «G.» ha convinto Donato a sparire, e a sembrare colpevole."},{"id":"d6","label":"Il quaderno di Donato","text":"A matita, le prenotazioni che gli passa l'agenzia. Agosto: solo «Intini, 10 notti». In fondo: «Stagione morta. Il 30 finisce il contratto con Sabrina. Passo all'agenzia di Bari.»","insight":"Donato stava per togliere la gestione del trullo a Sabrina."},{"id":"d7","label":"La lettera della finanziaria","text":"Sul tavolo di Donato, un sollecito intestato al nipote Gianni: «Tre rate scadute. Ultimo avviso prima del recupero crediti.»","insight":"Gianni è pieno di debiti: il movente perfetto per una truffa."}],"suspects":[{"id":"gianni","name":"Gianni Recchia","role":"Nipote di Donato, 34 anni","look":"Camicia stropicciata, telefono in mano, le pellicine delle dita mangiate a sangue.","tell":"La gamba batte sotto il tavolo e si mangia le unghie. Ma quando parla dello zio ti guarda dritto e la voce si abbassa: ha paura per lui, non di te.","questions":[{"id":"g1","q":"Dov'è suo zio?","a":"Non lo so. Il telefono squilla a vuoto da ieri. Se lo zio scappa, va in un posto solo: la casedda della nonna verso Locorotondo. Ma lì non c'è campo, e senza macchina io non ci arrivo.","insight":"Se Donato è scappato, è quasi certamente nella casedda di campagna verso Locorotondo."},{"id":"g2","q":"L'annuncio del trullo l'ha fatto lei?","a":"Quello vero, sì. Tre giorni fa ho visto la copia e l'ho segnalata alla piattaforma. Ecco la mail, guardi l'ora. Chi fa una truffa non la denuncia.","insight":"Gianni ha segnalato l'annuncio clonato tre giorni fa, prima che arrivassero i truffati."},{"id":"g3","q":"Il messaggio a suo zio è firmato «G.».","req":["d5"],"a":"Io lo zio lo chiamo, non gli scrivo: gli SMS li legge con la lente. E il mio numero ce l'ha salvato come «Giannino». Se era mio, lo vedeva. Chi ha scritto sapeva che lui della finanza ha il terrore.","insight":"Il messaggio «G.» non viene dal numero di Gianni: qualcuno ha usato il suo nome."},{"id":"g4","q":"Lei ha tre rate scadute con una finanziaria.","req":["d7"],"a":"Seimila euro. Lo zio lo sa. Mi ha detto: vieni a lavorare ai trulli e li ripaghi. Io lo zio non lo derubo.","aside":"Si vergogna del debito, ma non abbassa gli occhi.","insight":"Donato conosceva i debiti di Gianni e lo stava aiutando."}]},{"id":"sabrina","name":"Sabrina Colucci","role":"Titolare dell'agenzia Chiavi del Trullo","look":"Tailleur blu, sorriso da accoglienza, un mazzo di chiavi con venti targhette colorate.","tell":"Sorride anche quando non serve. Il telefono con la cover dell'agenzia è sul tavolo. Ma dalla borsa, ogni tanto, vibra un secondo telefono, economico, da ricaricabile. Lei non lo guarda e ci mette sopra la mano.","questions":[{"id":"s1","q":"Come funziona la gestione del trullo?","a":"Chiavi, pulizie, check-in. Gli annunci li fa il nipote, i soldi vanno a Donato. Io prendo la mia percentuale e basta.","insight":"Sabrina dice di non toccare né annunci né soldi."},{"id":"s2","q":"Quando ha visto Donato l'ultima volta?","a":"L'altro ieri pomeriggio, per i conti. Era agitato. Continuava a dire che la finanza ce l'aveva con lui, che l'avrebbero arrestato.","insight":"Sabrina dice che già l'altro ieri Donato aveva paura della finanza."},{"id":"s3","q":"Nel suo raccoglitore c'è la carta d'identità di Donato.","req":["d3"],"a":"Me l'ha data lui, per il contratto di gestione. È normale.","aside":"Il contratto è del 2019. La carta d'identità fotocopiata è quella rinnovata a marzo.","insight":"Sabrina ha fotocopiato i documenti di Donato pochi mesi fa, non per il contratto.","lie":true},{"id":"s4","q":"L'SMS a Donato viene da un numero sconosciuto. E lei ha due telefoni.","req":["d5","t_sabrina"],"a":"Quello è per le signore delle pulizie. Una cosa di lavoro.","aside":"Il telefono di lavoro è quello sul tavolo, col logo dell'agenzia. L'altro l'ha appena spinto in fondo alla borsa.","insight":"Sabrina nasconde un secondo telefono: può essere quello dell'SMS firmato «G.».","lie":true}]},{"id":"rocco","name":"Rocco Intini","role":"Ospite del trullo, 52 anni","look":"Polo nuova, abbronzatura da tre giorni. Continua a guardare la porta del trullo.","tell":"Si volta ogni volta che si muove la tenda del trullo. All'anulare sinistro non ha la fede, ma c'è una striscia di pelle bianca dove la porta di solito.","questions":[{"id":"r1","q":"Come ha prenotato il trullo?","a":"In agenzia, dalla signora Colucci. Anticipo in contanti a maggio. Ho la ricevuta con il timbro.","insight":"La prenotazione di Rocco è regolare: passata dall'agenzia di Sabrina."},{"id":"r2","q":"Si è tolto la fede. Chi c'è nel trullo?","req":["t_rocco"],"a":"(Abbassa la voce.) Una persona. Non è mia moglie. Se finisco su un verbale, sono finito. Io con i soldi di nessuno c'entro.","insight":"Rocco nasconde un'amante, non una truffa.","lie":true},{"id":"r3","q":"Ha visto il proprietario in questi giorni?","a":"Il vecchio? Ieri mattina, verso le sette e mezza. Caricava una valigetta sulla Panda e parlava da solo: «In galera non ci vado. Non ci vado.»","insight":"Ieri alle 7:30, subito dopo l'SMS, Donato è partito spaventato dalla galera."}]}],"bluff":{"text":"Annunci che la banca online ha dato ai carabinieri l'indirizzo internet da cui è stato aperto il conto, e che domattina arriva il nome.","reactions":{"gianni":"«Finalmente. Così lo zio può tornare a casa.»","sabrina":"«Tanto sarà il wifi di qualche bar, no? Quelli li usano tutti.» Lo dice sorridendo, prima che qualcuno chieda niente.","rocco":"«Io ho pagato in contanti. Con internet non c'entro.»"},"insight":"Al bluff dell'indirizzo internet Sabrina ha subito spiegato perché non porterà a nessuno: sa bene come è stato aperto il conto."},"culprit":"sabrina","key":["x1","s4","s3"],"solution":"Sabrina sapeva che a fine mese Donato le avrebbe tolto la gestione. Con la fotocopia fresca della sua carta d'identità ha aperto un conto online a nome di lui, mai usato da Donato come prova la busta sigillata, e ha messo in rete un clone del Trullo Stella a prezzo stracciato, incassando anticipi per un trullo che lei stessa aveva già affittato a Rocco. Quando i truffati hanno cominciato ad arrivare, le serviva un colpevole: col secondo telefono ha scritto a Donato firmandosi «G.», come il nipote pieno di debiti. Il vecchio, terrorizzato dalla finanza, è scappato nella casedda di campagna. Ma Sabrina conosceva la storia della finanza prima ancora che partisse l'SMS.","contradictions":[{"id":"x1","a":"s2","b":"d5","who":"sabrina","reply":"Mi sarò confusa col giorno. Forse me l'ha detto ieri, al telefono.","aside":"Ieri alle sette Donato ha lasciato il telefono sul tavolo. E quell'SMS nessuno gliel'ha mai fatto leggere.","insight":"Sabrina conosceva la storia della finanza, che esisteva solo nell'SMS firmato «G.». Quell'SMS l'ha scritto lei.","lie":true}]},{"id":"veggente","title":"La veggente di Polignano","place":"Villa sulla scogliera, Polignano a Mare","teaser":"Una profezia di morte. Tre giorni dopo, la morte.","intro":"«Morirai vicino all'acqua, prima della luna piena.» Madame Serena l'aveva detto a Riccardo Dell'Aquila, 49 anni, durante una seduta a casa sua. Ieri notte, due giorni prima della luna piena, Riccardo è precipitato dalla terrazza sulla scogliera. In paese parlano di maledizione. Tu delle veggenti hai un'opinione precisa.","details":[{"id":"d1","label":"La ringhiera","text":"Ferro battuto, alta un metro e dieci, intatta. Sotto, venti metri di scogliera.","insight":"Da lì non si inciampa: bisogna scavalcare o essere sollevati."},{"id":"d2","label":"Due bicchierini","text":"Sul tavolino, due bicchierini di limoncello. Sul fondo di uno, un velo di polvere bianca che il limoncello non ha sciolto.","insight":"Nel limoncello di Riccardo c'era qualcosa. Forse un sedativo."},{"id":"d3","label":"L'home banking","text":"Sul tablet di casa, l'app della banca aperta: bonifico di 3.000 € da Giulia a «S. Lorusso», due settimane fa. Causale: «consulenza».","insight":"Giulia ha pagato 3.000 € a una certa S. Lorusso."},{"id":"d4","label":"Il biglietto della profezia","text":"Scritto a mano dalla veggente: «Acqua. Luna piena. Un tradimento. La lettera R.»","insight":"Profezia vaga, adatta a chiunque. Tranne la R: quella è un'informazione, non una visione."},{"id":"d5","label":"La polizza","text":"In un cassetto dello studio: polizza vita da 800.000 €, stipulata quattro mesi fa. Beneficiaria: Giulia.","insight":"Giulia incassa 800.000 € dalla morte di Riccardo."},{"id":"d6","label":"Il messaggio di Marco","text":"Sul telefono di Riccardo, dal fratello Marco: «Se non mi dai tempo per quei soldi te ne penti.»","insight":"Marco doveva soldi a Riccardo e l'ha minacciato."},{"id":"d7","label":"Il flacone in bagno","text":"Sonnifero prescritto a Giulia dieci giorni fa. Confezione da 30 compresse, ne restano 4.","insight":"In dieci giorni sono sparite 26 compresse di sonnifero."}],"suspects":[{"id":"serena","name":"Madame Serena","role":"Veggente, al secolo S. Lorusso","look":"Anelli a ogni dito, voce bassa. È venuta a «portare conforto».","tell":"Mentre tu la studi, lei studia te: frasi aperte, pause, aspetta la tua reazione per capire dove andare. È una truffatrice, su questo non ci sono dubbi. Ma quando si parla della morte il trucco si ferma: ha paura vera.","questions":[{"id":"v1","q":"Come ha previsto la morte di Riccardo?","a":"Le carte parlano a chi sa ascoltare. Lei, per esempio: ha perso qualcuno di importante, vero? Lo vedo.","aside":"Lettura a freddo da manuale: vale per chiunque."},{"id":"v2","q":"Da dove viene la R della profezia?","req":["d4"],"a":"Dalle carte!","aside":"Troppo in fretta. E per un istante guarda Giulia.","insight":"Alla domanda sulla R Serena ha guardato Giulia."},{"id":"v3","q":"Lei è S. Lorusso. Giulia le ha versato 3.000 euro.","req":["d3"],"a":"Va bene. Mi ha pagata per spaventarlo. Diceva che lui usciva in barca ubriaco e voleva che smettesse. I dettagli me li ha dati lei: l'acqua, la luna piena, la R. Io leggo le carte, non ammazzo la gente.","insight":"Giulia ha pagato la veggente e le ha dettato la profezia.","lie":true}]},{"id":"giulia","name":"Giulia Dell'Aquila","role":"Moglie, 44 anni","look":"Occhiali scuri in casa. Un fazzoletto stretto in mano, asciutto.","tell":"Il dolore arriva in ritardo: prima le frasi pratiche, poi le lacrime, come se si ricordasse di doverle aggiungere. Quando si parla della profezia le spalle si rilassano.","questions":[{"id":"g1","q":"Cosa è successo ieri sera?","a":"Un limoncello in terrazza, come ogni sera. Li ho versati io. Alle undici sono andata a letto. Riccardo era sconvolto dalla profezia, non dormiva più. Forse si è buttato. O è caduto.","insight":"Giulia ha versato i limoncelli e suggerisce il suicidio."},{"id":"g2","q":"Mancano 26 sonniferi in dieci giorni.","req":["d7"],"a":"Dormo male. Da mesi. Lo sanno tutti che dormo male.","insight":"Giulia non sa spiegare le 26 compresse sparite.","lie":true},{"id":"g3","q":"Parliamo della polizza da 800.000 euro.","req":["d5"],"a":"L'ha voluta lui. Io non volevo nemmeno firmare. L'ha voluta lui.","aside":"Ripete la stessa frase due volte. Una risposta provata allo specchio.","insight":"Sulla polizza Giulia ha una risposta preparata."}]},{"id":"marco","name":"Marco Dell'Aquila","role":"Fratello, 45 anni","look":"Tuta da lavoro del porto, arrivato di corsa da Bari.","tell":"Guarda il pavimento quando si parla di soldi e alza gli occhi quando si parla del fratello. È vergogna per il debito. Il dolore è vero.","questions":[{"id":"k1","q":"Ha minacciato suo fratello.","req":["d6"],"a":"Gli dovevo ventimila euro, gli ho scritto una cosa stupida. Ieri notte ero di turno al porto di Bari, dalle dieci alle sei. Ci sono le timbrature.","insight":"Marco ha un alibi: il turno di notte al porto, con le timbrature."},{"id":"k2","q":"Riccardo credeva alla veggente?","a":"Riccardo? Rideva degli oroscopi. È Giulia che ha voluto portarla in casa. Insisteva.","insight":"È stata Giulia a volere la seduta con la veggente."},{"id":"k3","q":"Com'era il loro matrimonio?","a":"Da un anno dormivano in stanze separate. Lui parlava di separazione.","insight":"Riccardo pensava di separarsi da Giulia."}]}],"bluff":{"text":"Annunci che l'autopsia ha già trovato un sedativo nel sangue di Riccardo.","reactions":{"serena":"«Sedativo?» Impallidisce. Non lo sapeva.","giulia":"«Li prendeva anche lui, ogni tanto, per dormire.» Risponde subito, a una domanda che nessuno le ha fatto.","marco":"«Sedato? Allora qualcuno l'ha aiutato a cadere.»"},"insight":"Al bluff del sedativo Giulia ha giustificato la cosa prima ancora che qualcuno la accusasse."},"culprit":"giulia","key":["v3","g2","d2","x1"],"solution":"Giulia ha costruito la maledizione. Ha pagato Serena per una profezia su misura (acqua, luna piena, la R di Riccardo) così che una morte sulla scogliera sembrasse destino, o suicidio. Ieri sera ha versato lei i limoncelli, con dentro le compresse del suo sonnifero. Quando Riccardo si è addormentato l'ha portato alla ringhiera. Il movente: la polizza da 800.000 € e una separazione in arrivo. La veggente è una truffatrice, ma non un'assassina.","contradictions":[{"id":"x1","a":"g1","b":"d2","who":"giulia","reply":"Ci avrà messo lui qualcosa. Io li ho solo versati.","aside":"Ha appena ammesso che nessun altro ha toccato i bicchieri.","insight":"Solo Giulia ha toccato i limoncelli: la polvere nel bicchiere l’ha messa lei.","lie":true}]},{"id":"barca-vuota","title":"Mare calmo","place":"Porto vecchio, Gallipoli","teaser":"La barca torna all'alba. Il pescatore no.","intro":"All'alba la «Stella Maris», il gozzo di Cosimo Tarantino, è stata trovata alla deriva vicino all'isola di Sant'Andrea. Motore spento, nessuno a bordo. La capitaneria cerca da sei ore e il porto dà già Cosimo per annegato. Il comandante, che ti deve un favore, ti ha chiesto di dare un'occhiata prima che diventi una tragedia ufficiale.","details":[{"id":"d1","label":"Il motore","text":"Spento. La chiave è girata su OFF e il serbatoio è quasi pieno.","insight":"Il motore l'ha spento una mano: chi cade in mare non gira la chiave."},{"id":"d2","label":"Le reti","text":"Piegate a poppa, asciutte. Nemmeno un'alga.","insight":"Stanotte Cosimo non ha calato le reti: non è uscito a pescare."},{"id":"d3","label":"La cima di poppa","text":"A poppa Cosimo teneva legato un canotto gonfiabile. Il canotto non c'è. La cima è stata sciolta, non tagliata né strappata.","insight":"Qualcuno ha lasciato la barca col canotto, con calma."},{"id":"d4","label":"La Panda di Dora","text":"Parcheggiata sotto casa. Sul tappetino del guidatore, sabbia bagnata e un filo d'alga. Sul cruscotto, lo scontrino di un distributore self-service di Lido Pizzo: ore 4:21.","insight":"Alle 4:21 la Panda di Dora era sulla costa, a Lido Pizzo."},{"id":"d5","label":"Il telefono di Cosimo","text":"Trovato nella cabina, carico. Ultimo messaggio inviato a Dora alle 3:12: «Mare calmo. Ti voglio bene.»","insight":"Cosimo ha lasciato il telefono a bordo dopo un ultimo messaggio a Dora."},{"id":"d6","label":"La cucina di casa","text":"Sul frigo, il portapillole settimanale di Cosimo, per la pressione. Vuoto. Anche la scatola nuova, comprata venerdì, è sparita.","insight":"Qualcuno ha portato via le pillole di Cosimo, una scorta di un mese. A un annegato non servono."},{"id":"d7","label":"La polizza","text":"Nella credenza: polizza infortuni, morte accidentale in mare, 300.000 euro. Beneficiaria Addolorata Tarantino. Il massimale è stato triplicato a marzo.","insight":"Se Cosimo risulta morto in mare, Dora incassa 300.000 euro. La polizza è stata triplicata a marzo."}],"suspects":[{"id":"nando","name":"Nando Scorrano","role":"Grossista di pesce, 60 anni","look":"Stivali di gomma, catena d'oro, un telefono che squilla ogni due minuti. Al porto lo chiamano «la banca».","tell":"Parla di Cosimo sempre al presente: «mi deve», «è uno che». Non per speranza: per contabilità. Quando parli di mare sbuffa, quando parli di soldi si avvicina. Cosimo lo vuole vivo, e si vede.","questions":[{"id":"n1","q":"Cosimo le doveva dei soldi.","a":"Quarantamila. Cambiali, scadenza venerdì. E un morto non paga, lo sa? Se lo volevo morto, ero scemo.","insight":"Cosimo doveva 40.000 euro a Nando, con scadenza venerdì."},{"id":"n2","q":"Dov'era stanotte?","a":"All'asta del mercato ittico, dalle tre e mezza alle sei. Ho comprato sei lotti. C'è il registro, ci sono le telecamere, ci sono cinquanta pescatori.","insight":"Nando era all'asta del pesce dalle 3:30 alle 6, davanti a cinquanta persone."},{"id":"n3","q":"Cosimo le ha detto qualcosa, ultimamente?","a":"Lunedì, al bar. «Venerdì ti pago, Nando. In un modo o nell'altro.» Ho pensato che vendeva la barca. Adesso quella barca non vale niente.","insight":"Cosimo aveva promesso di pagare venerdì, «in un modo o nell'altro»."}]},{"id":"samuele","name":"Samuele Nuzzo","role":"Mozzo, 19 anni","look":"Felpa col cappuccio, mani screpolate dal sale. Seduto su una bitta da ore, non se ne va.","tell":"Ogni tanto la mano va alla tasca dei jeans e controlla che qualcosa sia ancora lì. Guarda il mare aperto, non la barca: aspetta qualcuno, non un corpo. Quando parla di Cosimo la voce gli si rompe, ma non piange.","questions":[{"id":"s1","q":"Perché stanotte non era in barca?","a":"Mi ha scritto a mezzanotte: «Stanotte non venire, esco da solo.» In tre anni non era mai successo.","insight":"Stanotte, per la prima volta in tre anni, Cosimo ha voluto uscire da solo."},{"id":"s2","q":"Cosa controlla in quella tasca?","req":["t_samuele"],"a":"(Tira fuori le banconote.) Duecento euro. Me li ha dati ieri sera, al porto. «Per la settimana che non lavori.» Come se sapesse che non avrei lavorato. Non l'ho detto a nessuno, sembrava che l'avessi venduto.","insight":"Ieri sera Cosimo ha pagato in anticipo il mozzo: sapeva che non sarebbe tornato.","lie":true},{"id":"s3","q":"Com'era Cosimo in barca?","a":"Un maniaco. Il canotto lo legava con tre nodi. E il telefono non se lo portava mai, lo lasciava a casa. Diceva che in mare si sta zitti.","insight":"Cosimo non portava mai il telefono in barca: stanotte l'ha lasciato a bordo apposta."}]},{"id":"dora","name":"Addolorata «Dora» Tarantino","role":"Moglie di Cosimo, 49 anni","look":"Scialle nero, il telefono stretto in mano. Le amiche le fanno cerchio intorno.","tell":"Ha pianto, ma il trucco è fresco: se l'è rifatto stamattina, dopo la notizia. Quando il telefono vibra guarda lo schermo e lo gira in giù, senza rispondere. All'orlo dei jeans, sotto lo scialle, c'è sabbia umida.","questions":[{"id":"o1","q":"Quando ha sentito suo marito l'ultima volta?","a":"Alle tre e dodici mi ha scritto: «Mare calmo, ti voglio bene.» Io dormivo. L'ho letto alle sei e ho chiamato la capitaneria. Stanotte non sono uscita di casa.","insight":"Dora dice di aver dormito tutta la notte, senza uscire di casa."},{"id":"o2","q":"Le pillole di Cosimo sono sparite, anche la scatola nuova.","req":["d6"],"a":"Le avrò buttate io. Non lo so. Che importanza hanno delle pillole, adesso?","aside":"Gli occhi le vanno alla borsa. Non al mare.","insight":"Dora non sa spiegare le pillole sparite, e guarda la sua borsa.","lie":true},{"id":"o3","q":"La polizza è stata triplicata a marzo.","req":["d7"],"a":"L'ha voluta lui. Il mare è traditore, diceva sempre. Io non volevo nemmeno firmare.","insight":"Con la polizza triplicata a marzo, Dora incassa 300.000 euro se Cosimo è morto."}]}],"contradictions":[{"id":"x1","a":"o1","b":"d4","who":"dora","reply":"Non riuscivo a dormire. Sono andata a guardare il mare, dove va lui. Che c'è di strano?","aside":"Alle quattro di notte, a dodici chilometri da casa. E Cosimo pesca a sud di Sant'Andrea, non davanti alla spiaggia di Lido Pizzo.","insight":"Alle 4:21 Dora era sulla spiaggia di Lido Pizzo, e aveva giurato di non essere uscita.","lie":true}],"bluff":{"text":"Annunci che un peschereccio ha ripescato un corpo vicino a Sant'Andrea e che serve qualcuno della famiglia per il riconoscimento.","reactions":{"nando":"«Porca miseria.» Si siede su una cassetta del pesce. Sta facendo i conti, e si vede.","samuele":"Diventa bianco, corre in fondo al molo e vomita in acqua.","dora":"«Non è lui.» Lo dice subito, sicura. Solo un secondo dopo scoppia a piangere."},"insight":"Al bluff del corpo ripescato Dora ha detto «non è lui» prima ancora di vederlo."},"culprit":"dora","key":["x1","o2","o3"],"solution":"Cosimo non è annegato: è scappato, e Dora l'ha aiutato. Con le cambiali di Nando in scadenza, hanno deciso di farlo sparire in mare e incassare la polizza triplicata a marzo. Stanotte Cosimo è uscito da solo, dopo aver pagato in anticipo il mozzo; non ha calato le reti, ha lasciato a bordo il telefono con un messaggio d'addio, ha spento il motore ed è sceso a riva col canotto. Alle 4:21 Dora lo aspettava a Lido Pizzo con la Panda e le sue pillole per la pressione. Il corpo che cerca la capitaneria sta bene, ed è nascosto a mezz'ora da qui."},{"id":"fornocolonna","title":"Il criscito","place":"Forno Colonna, centro storico di Altamura","teaser":"Alle quattro il pane non esce. Esce solo il fumo.","intro":"Da cent'anni il Forno Colonna accende la legna alle due e mezza di notte. Stamattina, alle quattro, il garzone trova la stanza piena di fumo e Peppino Colonna, 71 anni, seduto accanto al forno, come se dormisse. Per i vigili del fuoco è una disgrazia: canna fumaria sporca. Ma Peppino quella canna la puliva ogni mese, e il paese lo sa.","details":[{"id":"d1","label":"La canna fumaria","text":"La serranda in basso è aperta. Eppure il tiraggio è zero: il fumo di una candela torna indietro.","insight":"La canna non è chiusa in basso: è tappata più su, sul tetto."},{"id":"d2","label":"Il terrazzo","text":"Si sale dalla scala del palazzo, porta con lucchetto a combinazione. Nel comignolo è infilato un sacco di juta del mulino, annerito. La combinazione la sanno i condomini: Tommaso Colonna e una signora di novant'anni.","insight":"Qualcuno ha tappato il comignolo dal terrazzo, dove salgono solo i condomini: in pratica, Tommaso."},{"id":"d3","label":"La bozza del testamento","text":"Nel cassetto della cassa, la bozza di un notaio di Altamura, datata la settimana scorsa: «Il forno e il marchio Colonna a Karim Benali.» Appuntamento per la firma: lunedì.","insight":"Lunedì Peppino avrebbe lasciato il forno al garzone, non al nipote."},{"id":"d4","label":"La madia","text":"Dentro, il criscito: il lievito madre di famiglia, cent'anni. Ha il segno fresco di un cucchiaio: qualcuno stanotte ne ha preso un pezzo.","insight":"Stanotte qualcuno è entrato nel forno a prendere un pezzo di lievito madre."},{"id":"d5","label":"Peppino","text":"Seduto sulla sedia di paglia accanto al forno, il grembiule addosso. La pelle è rosea, quasi colorita.","insight":"La pelle rosea è il segno del monossido di carbonio: Peppino è morto nel sonno, avvelenato dal fumo."},{"id":"d6","label":"Il preliminare","text":"In una cartellina sotto il bancone: un preliminare di vendita del marchio «Forno Colonna 1921» a un gruppo industriale di Bari. Firmato da Tommaso. Manca la firma del titolare.","insight":"Tommaso voleva vendere il marchio a un'industria; Peppino non aveva firmato."},{"id":"d7","label":"Il rilevatore di fumo","text":"Sopra la porta, il rilevatore di monossido. Senza batteria. La batteria è nel cassetto sotto, ancora nuova.","insight":"Qualcuno che conosceva il forno ha tolto la batteria al rilevatore."}],"suspects":[{"id":"karim","name":"Karim Benali","role":"Garzone, 24 anni","look":"Felpa infarinata, occhi rossi, il berretto di Peppino stretto in mano.","tell":"Voce roca, occhi che lacrimano: il fumo l'ha respirato davvero, entrando a salvarlo. Stringe il berretto di Peppino e non lo molla mai, nemmeno per gesticolare.","questions":[{"id":"k1","q":"Cosa è successo stanotte?","a":"Alle quattro meno cinque apro, e la stanza è grigia. Peppino sulla sedia, rosso in faccia come se dormisse. L'ho trascinato fuori. Troppo tardi. Il fumo dal camino non usciva, usciva tutto dentro."},{"id":"k2","q":"Peppino le lasciava il forno.","req":["d3"],"a":"Me l'ha detto la settimana scorsa, qui, davanti a Tommaso. Tommaso ha buttato a terra un vassoio di taralli e se n'è andato. Io non volevo niente. Volevo lui.","insight":"Tommaso sapeva del testamento: Peppino l'ha annunciato davanti a lui."},{"id":"k3","q":"Dov'era prima delle quattro?","a":"In pizzeria a Gravina fino alle due, a pulire. Poi il titolare mi ha dato un passaggio, mi ha lasciato qui davanti alle quattro meno cinque. Può chiamarlo.","insight":"Karim ha un alibi fino alle 3:55: la pizzeria e il passaggio del titolare."}]},{"id":"donato","name":"Donato Mastrangelo","role":"Fornaio rivale, 66 anni","look":"Grembiule ancora addosso, mani screpolate, un taglio fresco sul pollice.","tell":"Arrossisce ogni volta che il suo sguardo cade sulla madia di Peppino. Parla di Peppino con rabbia, ma ne parla al presente. Chi odia qualcuno da quarant'anni non si abitua in un'ora.","questions":[{"id":"o1","q":"Dov'era stanotte?","a":"Nel mio forno, qui di fronte, da mezzanotte. Come ogni notte da quarant'anni. Da solo. Di qua non ci metto piede.","insight":"Donato dice di non essere mai entrato nel Forno Colonna stanotte."},{"id":"o2","q":"Stanotte qualcuno ha preso un pezzo del criscito.","req":["d4"],"a":"(Diventa viola.) A mezzanotte. La porta di servizio non la chiude nessuno. Il mio lievito muore ogni estate, il suo ha cent'anni... Il forno era freddo, Peppino non c'era ancora. E uscendo, verso mezzanotte e dieci, ho visto una torcia sul terrazzo, sopra il forno. Ho pensato ai ladri. Ladro ero io.","insight":"A mezzanotte e dieci qualcuno con una torcia era sul terrazzo sopra il forno.","lie":true},{"id":"o3","q":"Chi ci guadagna dalla morte di Peppino?","a":"Io, dicono. Un concorrente in meno. Ma il marchio Colonna lo voleva l'industria, mica io. E Tommaso con quelli ci andava a pranzo, a Bari. Tutte le settimane.","insight":"Tommaso trattava da settimane con l'industria per il marchio."}]},{"id":"tommaso","name":"Tommaso Colonna","role":"Nipote, 38 anni, abita sopra il forno","look":"Camicia pulita, barba fatta, profumo. Alle cinque del mattino.","tell":"Mani curatissime, unghie spazzolate da poco. Ma sotto l'unghia del pollice destro resta un nero che non è farina: è fuliggine. E si è fatto la barba, la mattina in cui è morto suo zio.","questions":[{"id":"m1","q":"Dov'era stanotte?","a":"A letto, qui sopra. Ho il sonno pesante, non mi sono mai alzato. Mi ha svegliato Karim che urlava.","insight":"Tommaso dice di non essersi mai alzato stanotte."},{"id":"m2","q":"Ha firmato un preliminare per vendere il marchio.","req":["d6"],"a":"Lo zio aveva settantun anni. Prima o poi doveva lasciare. Ci avrebbe ripensato.","aside":"«Doveva lasciare». Già al passato.","insight":"Tommaso voleva vendere il marchio, lo zio si opponeva."},{"id":"m3","q":"Chi erediterà il forno?","a":"Io, credo. Sono l'unico parente. Lo zio di testamenti non ha mai parlato.","insight":"Tommaso dice di non sapere niente di un testamento."},{"id":"m4","q":"Ha fuliggine sotto l'unghia, e il comignolo è stato tappato dal terrazzo.","req":["d2","t_tommaso"],"a":"Ho pulito il barbecue sul terrazzo. Domenica.","aside":"Domenica era quattro giorni fa. Le unghie le ha spazzolate stamattina, e il nero è rimasto dove la spazzola non arriva.","insight":"Tommaso mente sulla fuliggine: stanotte ha messo le mani nel comignolo.","lie":true}]}],"bluff":{"text":"Annunci che il mulino numera i suoi sacchi e che tra un'ora saprai a chi è stato consegnato quello nel comignolo.","reactions":{"karim":"«I sacchi li scarico io, ogni lunedì. Controllate pure.»","donato":"«Io compro da un altro mulino, da trent'anni. Per principio.»","tommaso":"«Quei sacchi vuoti li teniamo tutti sul terrazzo. Ci può salire chiunque.» Poi si accorge di aver detto «sul terrazzo»."},"insight":"Al bluff del sacco Tommaso ha subito spiegato che i sacchi stavano sul terrazzo, dove il sacco era: sapeva da dove veniva."},"culprit":"tommaso","key":["x1","m4","o2"],"solution":"Peppino avrebbe firmato lunedì un testamento che lasciava il forno a Karim, e Tommaso aveva già promesso il marchio all'industria. Verso mezzanotte Tommaso sale sul terrazzo, dove solo lui ha accesso, e infila un sacco nel comignolo: Donato, che rubava il lievito, vede la sua torcia. Toglie anche la batteria al rilevatore. Alle due e mezza Peppino accende la legna, il fumo non esce, e il monossido lo addormenta per sempre. Tommaso si è spazzolato le unghie, ma la fuliggine sotto il pollice è rimasta.","contradictions":[{"id":"x1","a":"m3","b":"k2","who":"tommaso","reply":"Sì, lo sapevo. Una sparata da vecchio. Non l'avrebbe mai firmato.","aside":"L'appuntamento dal notaio era lunedì. Peppino è morto giovedì.","insight":"Tommaso sapeva che lo zio lo stava diseredando, e l'aveva negato.","lie":true}]},{"id":"marpiccolo","title":"Filare sette","place":"Impianto di mitilicoltura, secondo seno del Mar Piccolo, Taranto","teaser":"Un uomo che conosceva ogni palo del Mar Piccolo. Annegato tra i suoi.","intro":"All'alba i colleghi trovano Cataldo Fornaro, 58 anni, impigliato nelle cime del suo impianto di cozze, faccia in giù nell'acqua bassa. La Capitaneria parla di malore e caduta. La figlia dice che suo padre nuotava prima di camminare. Sul molo, mezzo quartiere indica già il vicino con cui litigava da un anno.","details":[{"id":"d1","label":"I polsi di Cataldo","text":"Su tutti e due i polsi, segni rossi a spirale, come di una cima stretta con forza.","insight":"Qualcuno ha tenuto Cataldo con una cima: non è scivolato da solo."},{"id":"d2","label":"Le calze del filare 7","text":"Tra le retine bianche di Cataldo, sei calze di cozze avvolte in una retina arancione. Le cozze dentro hanno il guscio nero opaco.","insight":"Sul filare 7 qualcuno coltiva cozze di nascosto."},{"id":"d3","label":"L'ordinanza sul pontile","text":"Un foglio plastificato: «Primo seno: vietata la raccolta di mitili per la vendita. Contaminazione.»","insight":"Le cozze del primo seno non si possono vendere. Spostate di nascosto nel secondo seno, sembrano pulite."},{"id":"d4","label":"La barca di Cataldo","text":"Una barca a remi, legata al palo del filare 7, nascosta dietro le calze. Dentro, una torcia frontale spenta e un thermos di caffè a metà.","insight":"Cataldo si era nascosto al buio dietro il filare 7: aspettava qualcuno."},{"id":"d5","label":"Il quaderno di bordo","text":"Nella cassetta della barca, grafia grossa: «Filare 7: sei calze arancioni. Non sono mie. Guscio nero, vengono dal primo seno. Stanotte vedo chi viene.»","insight":"Cataldo sapeva delle calze abusive e stanotte voleva sorprendere chi le portava."},{"id":"d6","label":"La diffida","text":"Lettera dell'avvocato di Nunzio Blasi: «I pali del suo impianto invadono la concessione del mio assistito per quattro metri.»","insight":"Nunzio e Cataldo erano in causa per i confini."},{"id":"d7","label":"Le mani di Cataldo","text":"Sotto le unghie della mano destra, pelle e sangue. Sulle mani di Cataldo non c'è un graffio.","insight":"Cataldo ha graffiato il suo aggressore."}],"suspects":[{"id":"nunzio","name":"Nunzio Blasi","role":"Mitilicoltore, impianto confinante","look":"Maglione sformato, stivaloni fino all'inguine, una voce che si sente dall'altra riva.","tell":"Urla, gesticola, si batte il petto: è la rabbia di chi sa di essere il primo sospettato. Si asciuga la fronte con un fazzoletto di carta azzurra, ruvida, di quelli dei distributori d'ospedale.","questions":[{"id":"n1","q":"Lei e Cataldo eravate in causa. E al bar ha detto che l'avrebbe annegato.","req":["d6"],"a":"Per quattro pali! Sì, l'ho detto. Qui si dice. Stanotte a mezzanotte mia moglie si è sentita male: ho chiamato il 118 alle 00:02 e sono stato al pronto soccorso con lei fino alle sette. C'è il foglio del triage.","insight":"Nunzio ha un alibi: dalla mezzanotte alle sette era al pronto soccorso con la moglie."},{"id":"n2","q":"Ha visto qualcosa ieri sera?","a":"Poco prima di mezzanotte, fumavo sul pontile. Un barchino a motore senza luci andava verso i pali di Cataldo. Fuoribordo piccolo. Cataldo no: lui va a remi, per non sbattere contro i pali.","insight":"Poco prima di mezzanotte un barchino a motore senza luci andava verso l'impianto di Cataldo."},{"id":"n3","q":"Che uomo era Cataldo?","a":"Testardo come un palo. Ma onesto. Troppo, per questo mare."}]},{"id":"carmela","name":"Carmela Fornaro","role":"Figlia di Cataldo, 29 anni","look":"Il giaccone del padre, due taglie più grande. Occhi asciutti, mascella stretta.","tell":"Parla del padre al presente e stringe il giaccone con tutte e due le mani. Risponde subito e con precisione: è dolore trattenuto, non una storia preparata.","questions":[{"id":"c1","q":"Quando è uscito suo padre?","a":"Alle undici. Ha detto: vado a vedere chi mi ruba il mare. Ha preso la torcia e il thermos, e basta.","insight":"Cataldo è uscito alle 23 per sorprendere qualcuno sul suo impianto."},{"id":"c2","q":"Queste retine arancioni le conosce?","req":["d2"],"a":"Qui usiamo tutti la bianca. L'arancione la compra solo Rino Caforio, in Grecia, perché costa meno. Ne ha la barca piena.","insight":"Le retine arancioni del filare 7 sono quelle di Rino Caforio."},{"id":"c3","q":"Suo padre aveva nemici?","a":"Nunzio, per i pali. Ma Nunzio abbaia e basta. Da una settimana papà era strano: non dormiva, contava le calze.","insight":"Da una settimana Cataldo sospettava che qualcuno usasse il suo impianto."}]},{"id":"rino","name":"Rino Caforio","role":"Trasportatore di cozze, 47 anni","look":"Canottiera, braccia da scaricatore. Il suo barchino col fuoribordo è ormeggiato al molo.","tell":"Tiene la mano destra in tasca o sotto l'ascella. Quando accende una sigaretta si vedono sul dorso tre graffi paralleli, freschi, ancora gonfi.","questions":[{"id":"r1","q":"Ha mai lavorato sull'impianto di Cataldo?","a":"Mai messo piede. Io carico e porto a Bari, per i grossisti. Coi pali ho chiuso da anni.","insight":"Rino giura di non avere niente a che fare con l'impianto di Cataldo."},{"id":"r2","q":"Dov'era stanotte?","a":"A letto dalle dieci. Alle cinque ero al mercato ittico, chieda a chi vuole.","insight":"Rino dice di aver dormito tutta la notte."},{"id":"r3","q":"Cataldo ha pelle sotto le unghie. Lei ha tre graffi freschi sulla mano.","req":["d7","t_rino"],"a":"Cozze. Chi lavora le cozze ha le mani a pezzi.","aside":"I tagli da guscio sono piccoli, storti, sparsi. Questi sono tre, dritti, paralleli: la distanza fra tre dita.","insight":"I graffi di Rino sono di unghie, non di gusci: è lui che Cataldo ha graffiato.","lie":true}]}],"bluff":{"text":"Dici che la Capitaneria ha una telecamera termica sul ponte girevole che di notte riprende tutto il Mar Piccolo.","reactions":{"nunzio":"«E allora vedranno che io stavo in ambulanza!»","carmela":"«Voglio vederlo. Voglio vedere chi era.»","rino":"Chiede se la termica arriva fino al canale tra il primo e il secondo seno, o si ferma prima. Nessuno aveva parlato del primo seno."},"insight":"Al bluff della telecamera Rino si è preoccupato del passaggio tra primo e secondo seno."},"culprit":"rino","key":["r3","x1","d7"],"solution":"Qualcuno spostava di nascosto cozze dal primo seno, dove non si possono vendere, sul filare 7 di Cataldo, per farle «ripulire» e rivenderle come buone. Cataldo se n'è accorto dal guscio nero e stanotte l'ha aspettato al buio, nascosto con la barca a remi. Poco prima di mezzanotte arriva un barchino a motore senza luci, come ha visto Nunzio, e le retine arancioni sono quelle che compra solo Rino. Cataldo lo affronta e gli graffia la mano; Rino lo tiene sott'acqua con una cima e lo lascia impigliato tra i filari. Nunzio aveva minacciato di annegarlo, ma a quell'ora era in ambulanza con la moglie.","contradictions":[{"id":"x1","a":"r1","b":"c2","who":"rino","reply":"Va bene, le calze sono mie. Da lui crescono meglio e lui non se ne accorgeva. È un furto d'acqua, non un omicidio.","aside":"«Non se ne accorgeva.» Cataldo se n'era accorto eccome, e stanotte lo aspettava.","insight":"Le calze abusive del filare 7, con le cozze del primo seno, sono di Rino. Cataldo stava per scoprirlo.","lie":true}]},{"id":"pizzica-palco","title":"Silenzio in piazza","place":"Festival «Luna e Tamburi», Corigliano d'Otranto","teaser":"Cinquemila persone in piazza. Alle 20:50 si spegne tutto.","intro":"Il festival «Luna e Tamburi» aspettava cinquemila persone per la serata finale, con Assunta Rizzo, la voce più amata della pizzica. Alle 20:50, dieci minuti prima dell'inizio, il palco è diventato buio: qualcuno ha tagliato il cavo principale dietro le roulotte degli artisti. Concerto annullato, piazza in rivolta. L'organizzatore giura che è stato il tecnico licenziato due giorni fa. Tu prima vuoi vedere il cavo.","details":[{"id":"d1","label":"Il cavo tagliato","text":"Il cavo di potenza è tagliato netto dietro le roulotte degli artisti, in piena vista. Accanto, nell'erba, delle cesoie da giardino nuove, col cartellino di una ferramenta di Maglie ancora attaccato.","insight":"Il sabotatore ha comprato le cesoie apposta: un dilettante, ma con un piano."},{"id":"d2","label":"Il generatore","text":"Spento con il pulsante d'emergenza, un grosso fungo rosso con la scritta STOP. Sulla plastica rossa, qualche brillantino dorato.","insight":"Chi ha spento il generatore aveva le dita piene di brillantini dorati."},{"id":"d3","label":"I bagni chimici","text":"In fila accanto al generatore, dalla parte opposta del palco rispetto alle roulotte.","insight":"I bagni chimici sono a due passi dal generatore."},{"id":"d4","label":"Il contratto di Assunta","text":"Cachet: 18.000 euro. Clausola 9: se il concerto è annullato per cause tecniche imputabili all'organizzazione, il cachet è dovuto per intero. Clausola 10: se è l'artista a rinunciare, penale di 30.000 euro.","insight":"Se il concerto salta per un guasto, Assunta incassa 18.000 euro. Se rinuncia lei, ne paga 30.000."},{"id":"d5","label":"Il foglio delle prevendite","text":"4.800 biglietti venduti su 5.000. Tutti da rimborsare.","insight":"Il festival era quasi esaurito: annullarlo è una rovina per chi lo organizza."},{"id":"d6","label":"La polizza del festival","text":"Nel furgone della produzione: polizza annullamento evento, scaduta il 30 giugno. Mai rinnovata.","insight":"Il festival non era assicurato: l'annullamento lo paga tutto l'organizzatore."},{"id":"d7","label":"La roulotte di Assunta","text":"Spray per la gola, miele, tre thermos d'acqua calda. Sul tavolino, un certificato di un foniatra di Bari, datato martedì: «Noduli alle corde vocali. Riposo vocale assoluto per 15 giorni.»","insight":"Da martedì Assunta aveva l'ordine di non cantare per quindici giorni."}],"suspects":[{"id":"rino","name":"Rino Calò","role":"Tecnico luci, licenziato due giorni fa","look":"Maglietta nera della crew, tronchese alla cintura per abitudine. Sa di birra.","tell":"Beve, sì: le mani gli tremano un po' e parla troppo forte. Ma parla del palco come un falegname parla della sua sedia. Davanti al cavo tagliato fa una smorfia di disgusto professionale, non di paura.","questions":[{"id":"r1","q":"Lei ha detto che senza di lei il palco non si accende.","a":"Ho detto che non si accende bene. Mica che lo spegnevo io. Alle nove meno venti ero al bar della piazza, e c'è il video di un amico che lo prova: guardi, 20:41, io con la birra in mano.","insight":"Alle 20:41 Rino era al bar della piazza, ripreso in un video."},{"id":"r2","q":"Il cavo è stato tagliato con delle cesoie nuove.","req":["d1"],"a":"Cesoie da giardino? Io ho questa. (Batte sulla tronchese.) E se lo tagliavo io, lo facevo sotto il palco, dove ci mettevano due ore a trovarlo. Questo l'ha fatto un dilettante, in piena vista, dietro le roulotte degli artisti.","insight":"Il cavo l'ha tagliato un dilettante, vicino alle roulotte degli artisti."},{"id":"r3","q":"Perché l'hanno licenziata?","a":"Perché bevo, dice Walter. E perché gli ho detto davanti a tutti che la polizza era scaduta, e lui non voleva sentirselo dire.","insight":"Rino sapeva che la polizza del festival era scaduta."}]},{"id":"assunta","name":"Assunta Rizzo","role":"Cantante, 41 anni","look":"Abito bianco di scena, fazzoletto rosso al collo, brillantini dorati sugli zigomi e sul dorso delle mani. Una tazza fumante sempre in mano.","tell":"Parla sottovoce, e non per timidezza: risparmia la voce, conta le parole, quando può annuisce. Quando nomini il concerto annullato non guarda il palco. Si tocca la gola.","questions":[{"id":"a1","q":"Dov'era alle 20:45?","a":"In roulotte. A scaldare la voce. Non sono uscita fino al buio.","insight":"Assunta dice di essere rimasta in roulotte fino al blackout."},{"id":"a2","q":"Il foniatra le ha ordinato quindici giorni di silenzio.","req":["d7"],"a":"(Sussurra.) I medici esagerano. Ho cantato con quaranta di febbre, io. Stasera avrei cantato.","aside":"Lo dice senza voce, pesando ogni sillaba.","insight":"Assunta non poteva cantare: aveva i noduli e l'ordine del medico di stare zitta.","lie":true},{"id":"a3","q":"Il suo contratto le paga il cachet se il concerto salta per un guasto.","req":["d4"],"a":"La clausola nove? Le scrive il mio agente, io non le leggo.","aside":"Non le legge, ma sa il numero.","insight":"Assunta conosce bene la clausola che le paga il cachet in caso di guasto."}]},{"id":"walter","name":"Walter Monaco","role":"Organizzatore del festival, 50 anni","look":"Camicia sudata, due telefoni, un auricolare. Non si è ancora seduto.","tell":"Ti risponde e intanto scrive messaggi. Gli aloni sotto le ascelle crescono ogni volta che qualcuno dice «rimborsi». Ha paura, tanta: ma del dopo, non di essere scoperto stasera.","questions":[{"id":"w1","q":"Chi ci guadagna, se il concerto salta?","a":"Nessuno! Io ci perdo tutto: quattromilaottocento biglietti da rimborsare, gli sponsor, i service. È stato Rino, ve lo dico io.","insight":"Walter perde tutto con l'annullamento, e accusa Rino."},{"id":"w2","q":"La polizza del festival è scaduta a giugno.","req":["d6"],"a":"(Abbassa la voce.) Non avevo i soldi per rinnovarla. Se lo sanno gli sponsor, in Puglia non lavoro più. Ma le pare che mi sabotavo da solo, senza assicurazione?","insight":"Walter nascondeva di non essere assicurato: l'annullamento lo rovina, non lo arricchisce.","lie":true},{"id":"w3","q":"Ha visto qualcuno dietro il palco prima del blackout?","a":"Alle nove meno un quarto ho bussato alla roulotte di Assunta per il cambio d'abito. Porta aperta, luce accesa, dentro nessuno. Ho pensato che fosse andata in bagno.","insight":"Alle 20:45 la roulotte di Assunta era vuota."}]}],"contradictions":[{"id":"x1","a":"a1","b":"w3","who":"assunta","reply":"Ero... ai bagni chimici. Due minuti.","aside":"I bagni chimici sono accanto al generatore. E ha ancora i brillantini sulle dita.","insight":"Alle 20:45 Assunta non era in roulotte ma dalla parte del generatore, e l'aveva negato.","lie":true}],"bluff":{"text":"Annunci che da Lecce sta arrivando un generatore di riserva: il cavo si ripara in mezz'ora e il concerto si fa alle dieci.","reactions":{"rino":"«E chi lo monta, voi?» Però sorride, e si alza per andare a vedere.","assunta":"Si porta la mano alla gola. «Alle dieci? Stasera?» Cerca con gli occhi il suo agente.","walter":"«Grazie a Dio!» Comincia a telefonare a tutti, con tutti e due i telefoni."},"insight":"Alla notizia che il concerto si sarebbe fatto, l'unica spaventata è stata Assunta."},"culprit":"assunta","key":["x1","d2","a2"],"solution":"Assunta non poteva cantare: da martedì aveva i noduli e l'ordine di stare zitta per quindici giorni. Rinunciare le sarebbe costato 30.000 euro di penale, mentre un guasto dell'organizzazione gliene faceva incassare 18.000. Ha comprato le cesoie a Maglie, alle 20:45 è uscita dalla roulotte, ha premuto il fungo rosso del generatore lasciandoci i brillantini del trucco di scena e ha tagliato il cavo dietro le roulotte. Rino in quel momento era al bar, in un video. Walter, senza assicurazione, era l'ultimo ad avere interesse a spegnere il suo palco."},{"id":"scoglimonopoli","title":"Luce d'oro","place":"Cala Pietrabianca, Monopoli","teaser":"Un milione di follower, un tramonto perfetto, un passo indietro.","intro":"Giada Leone, 24 anni, un milione di follower, sta posando sugli scogli di Cala Pietrabianca al tramonto. Fa un passo indietro per la foto e scivola giù per quattro metri. È viva, in coma al Policlinico di Bari. I carabinieri parlano di imprudenza. Ma Giada su quegli scogli ci è cresciuta, e sua madre ti ha chiesto di guardare la troupe.","details":[{"id":"d1","label":"Lo scoglio del set","text":"Sul punto esatto della posa, una chiazza unta e lucida. Profuma di cocco. Il mare lì non arriva nemmeno con la tramontana.","insight":"Qualcuno ha unto lo scoglio apposta, sul punto dove Giada doveva posare."},{"id":"d2","label":"Il video del drone","text":"La caduta ripresa dall'alto. Giada è sola sul bordo, nessuno a meno di trenta metri. Fa un passo indietro e il piede parte come sul ghiaccio.","insight":"Nessuno ha spinto Giada: è scivolata su una roccia asciutta."},{"id":"d3","label":"Il volo delle 11:30","text":"Sulla scheda del drone c'è anche un volo di prova di stamattina. In un angolo, sugli scogli deserti, una donna con un cappello di paglia a tesa larga, accovacciata proprio sul punto della caduta.","insight":"Stamattina alle 11:30 una donna con un cappello a tesa larga era accovacciata sul punto della caduta."},{"id":"d4","label":"Il cestino del parcheggio","text":"Un flacone di olio abbronzante al cocco, vuoto. Attaccato col nastro, lo scontrino di una farmacia di Monopoli: ore 11:05 di oggi.","insight":"L'olio al cocco è stato comprato stamattina alle 11:05 e buttato vuoto."},{"id":"d5","label":"Il telefono di Giada","text":"Ultima mail inviata ieri, a un avvocato: «Voglio vedere tutti i contratti che Martina ha firmato a mio nome. Credo che mi rubi.»","insight":"Giada sospettava che la sua manager le rubasse, e aveva chiamato un avvocato."},{"id":"d6","label":"La storia di Mattia","text":"Uno screenshot girato tra i follower. Storia di Mattia, tre settimane fa, poi cancellata: «Chi ti tocca si fa male. Ricordatelo.»","insight":"Mattia ha pubblicato una frase minacciosa dopo la rottura con Giada."},{"id":"d7","label":"I sandali di Giada","text":"Suola di corda, liscia. Sul tallone destro, una patina unta che profuma di cocco.","insight":"Giada è scivolata sull'olio al cocco."}],"suspects":[{"id":"mattia","name":"Mattia Scarcia","role":"Fotografo ed ex fidanzato, 29 anni","look":"Radiocomando del drone ancora al collo, nocche sbucciate.","tell":"Guarda il radiocomando quando nomini Giada, come se il video fosse ancora lì. Le nocche sbucciate sono di chi ha scavalcato gli scogli a mani nude per raggiungerla. Non si è ancora lavato il sangue.","questions":[{"id":"m1","q":"Dov'era quando è caduta?","a":"Al radiocomando, trenta metri indietro. Un drone con il vento di stasera non si pilota con una mano. L'ho vista cadere dallo schermo.","insight":"Mattia pilotava il drone: mani occupate e trenta metri di distanza."},{"id":"m2","q":"«Chi ti tocca si fa male.» L'ha scritto lei.","req":["d6"],"a":"Per il tizio che la molestava nei commenti, non per lei! Ma letta così sembra altro, lo so. Per questo l'ho cancellata.","insight":"La frase di Mattia era contro un molestatore, non contro Giada."},{"id":"m3","q":"Chi ha scelto il punto dello scatto?","a":"Martina. Io volevo la caletta a nord, la luce è migliore. Lei ha insistito: quello scoglio lì, nessun altro. Non l'ho mai vista insistere su una luce.","insight":"È stata Martina a imporre lo scoglio della caduta."}]},{"id":"martina","name":"Martina Fanelli","role":"Manager di Giada, 41 anni","look":"Pelle chiarissima, crema bianca sul naso, cappello di paglia a tesa larga.","tell":"Pelle di latte, protezione 50 sul naso, le braccia sempre all'ombra del cappello. Una che al sole non si abbronza: si difende. Quando parli di Giada abbassa la tesa del cappello.","questions":[{"id":"r1","q":"Quando è arrivata qui?","a":"Alle sette, in macchina con Giada. Prima ero in ufficio a Bari tutto il giorno. Questi scogli li ho visti stasera per la prima volta.","insight":"Martina dice di non essere mai stata sugli scogli prima delle 19."},{"id":"r2","q":"Giada aveva scritto a un avvocato per i suoi contratti.","req":["d5"],"a":"Non ne sapevo niente.","aside":"Non chiede quale avvocato, né perché. Abbassa la tesa del cappello.","insight":"Martina finge di non sapere che Giada voleva controllare i suoi contratti.","lie":true},{"id":"r3","q":"Chi ha scelto lo scoglio?","a":"Il fotografo. Io mi occupo dei contratti, non della luce.","insight":"Martina dice che il punto l'ha scelto Mattia."}]},{"id":"noemi","name":"Noemi Russo","role":"Truccatrice, 26 anni","look":"Unghie perfette, trousse aperta, il telefono sempre in mano.","tell":"Tiene il telefono con la fotocamera frontale accesa e si controlla nello schermo mentre ti parla. Quando dice «ero accanto alle borse» il pollice scorre, di riflesso, verso la galleria video.","questions":[{"id":"n1","q":"Che olio ha messo a Giada?","a":"Illuminante alla vaniglia, sulle gambe. Sulle piante dei piedi mai, non sono scema. Senta, profuma ancora.","insight":"L'olio di Noemi è alla vaniglia, e solo sulle gambe."},{"id":"n2","q":"Dov'era quando Giada è caduta?","a":"Accanto alle borse, a sistemare i trucchi. Non ho visto niente.","insight":"Noemi dice di non aver visto niente."},{"id":"n3","q":"Lei non sistemava i trucchi. Si stava filmando.","req":["t_noemi"],"a":"(Arrossisce.) Un video per il mio profilo, col tramonto. Ho duemila follower, lei un milione. Guardi: dietro di me si vede Martina. Non guarda il tramonto. Guarda i piedi di Giada. E quando cade non grida.","insight":"Nel video di Noemi, Martina fissa i piedi di Giada e non reagisce alla caduta.","lie":true}]}],"bluff":{"text":"Annunci che dal Policlinico hanno chiamato: Giada ha aperto gli occhi e tra poco potrà parlare.","reactions":{"mattia":"«Posso vederla?» Si alza prima di finire la frase.","noemi":"«Oddio, meno male!» E scrive subito un messaggio.","martina":"«Con una botta così non ricorderà niente, poverina. I medici dicono sempre così.» Nessun medico l'ha detto."},"insight":"Al bluff del risveglio Martina si è affrettata a dire che Giada non ricorderà niente."},"culprit":"martina","key":["x1","d4","x2"],"solution":"Giada aveva capito che Martina le rubava sui contratti e aveva chiamato un avvocato. Stamattina Martina compra l'olio al cocco a Monopoli e alle 11:30 va a ungere lo scoglio: il volo di prova del drone la riprende col suo cappello. Una donna che non si abbronza mai non ha altri motivi per comprare olio abbronzante. La sera impone quel punto preciso per la foto, e aspetta. Mattia, l'ex con la storia minacciosa, stava trenta metri indietro col drone in mano.","contradictions":[{"id":"x1","a":"r1","b":"d3","who":"martina","reply":"Va bene, sono passata stamattina. Un sopralluogo. Non è un reato.","aside":"Accovacciata sulla roccia, per un sopralluogo. Con un olio comprato mezz'ora prima.","insight":"Stamattina Martina era accovacciata sul punto della caduta, e l'aveva negato.","lie":true},{"id":"x2","a":"r3","b":"m3","who":"martina","reply":"Ho detto che quello scoglio era carino. Mattia esagera sempre.","insight":"È stata Martina a imporre il punto della caduta, e ha provato a scaricarlo su Mattia.","lie":true}]},{"id":"rinascita","title":"Rinascere","place":"Eremo delle Querce, Foresta Umbra, Gargano","teaser":"Dieci giorni per rinascere. Chiara non ha finito il terzo.","intro":"Nell'eremo in mezzo alla Foresta Umbra, trenta persone digiunano, meditano e pagano duemila euro a testa per «rinascere» con il Maestro Anael. Stamattina Chiara Ventura, 41 anni, è stata trovata morta nella sua cella: arresto cardiaco, dicono, colpa del digiuno. Il marito ha chiamato te. Il Maestro, quando ti vede, sorride come chi riconosce un collega.","details":[{"id":"d1","label":"La tazza di Chiara","text":"Sul comodino, una tazza di terracotta con il suo nome inciso. Sul fondo, un residuo verde scuro e un frammento di foglia lunga, dura, a punta.","insight":"Nella tazza di Chiara c'era una foglia che non è né malva né menta."},{"id":"d2","label":"Il pentolone della tisana","text":"In sala comune, mezzo pieno. Odore di malva e menta. Tutti gli altri ne hanno bevuto e stanno bene.","insight":"La tisana comune era innocua: il veleno era solo nella tazza di Chiara."},{"id":"d3","label":"Il giardino delle erbe","text":"Lungo il muro, una siepe di oleandri. Un ramo è spezzato di fresco e la linfa bianca è ancora appiccicosa.","insight":"Stanotte qualcuno ha spezzato un ramo di oleandro, che è un veleno per il cuore."},{"id":"d4","label":"L'atto di donazione","text":"Nella cella di Chiara: la sua casa di Trani donata alla «Comunità Rinascere». Appuntamento dal notaio dopodomani. Non firmato.","insight":"Il Maestro stava per ricevere una casa. Con Chiara morta, la perde."},{"id":"d5","label":"Il quaderno di Chiara","text":"Conti a matita: «4 ritiri × 30 persone × 2.000 €. Sul conto della comunità ne arriva la metà.» Sotto: «Domani ne parlo con V., prima che col Maestro.»","insight":"Chiara aveva scoperto che metà dei soldi della comunità spariva, e voleva parlarne con «V.»."},{"id":"d6","label":"La bacheca dei turni","text":"«Tisana della sera: Viola. Ognuno prende la sua tazza dal vassoio in sala.»","insight":"La tisana la prepara Viola. Di regola ognuno si serve da solo."},{"id":"d7","label":"Il registro della meditazione","text":"Meditazione notturna, dalle 22 alle 2. Tredici firme, in testa quella del Maestro. L'ultima, di Viola, è in fondo e con una penna blu: tutte le altre sono nere.","insight":"Il Maestro ha guidato la meditazione tutta la notte. Viola è arrivata dopo gli altri."}],"suspects":[{"id":"viola","name":"Viola Serracchia","role":"Braccio destro del Maestro, 36 anni","look":"Treccia rossa, tunica bianca, voce dolcissima. Porta il tè a tutti senza che nessuno lo chieda.","tell":"Tiene le mani nascoste nelle maniche larghe della tunica. Quando le tira fuori per sistemarsi la treccia, i polpastrelli di pollice e indice destro sono arrossati e lucidi, come irritati da qualcosa.","questions":[{"id":"v1","q":"Che cosa ha fatto ieri sera?","a":"Alle nove e mezza ho preparato la tisana e ho lasciato il vassoio in sala, come sempre. Ognuno prende la sua tazza. Poi sono andata alla meditazione.","insight":"Viola dice di aver lasciato il vassoio in sala senza portare tazze a nessuno."},{"id":"v2","q":"Chiara voleva parlare con «V.» dei soldi della comunità.","req":["d5"],"a":"«V.»? Qui siamo in tre con la V. E io non tocco soldi: i conti li tiene il Maestro.","insight":"Viola nega di occuparsi dei soldi della comunità."},{"id":"v3","q":"Qualcuno ha spezzato un oleandro stanotte. E lei ha le dita irritate.","req":["d3","t_viola"],"a":"Ortica. Ieri ho pulito l'orto.","aside":"L'ortica fa bollicine sparse sul dorso della mano. Questo è un arrossamento netto, solo sulla punta di due dita: le dita di chi spezza un ramo.","insight":"Viola mente sulle dita: ha maneggiato un ramo di oleandro.","lie":true}]},{"id":"anael","name":"Maestro Anael","role":"Guida spirituale, al secolo Aldo Scarpiello","look":"Barba bianca curata, piedi nudi, un sorriso che non arriva agli occhi.","tell":"Voce morbida, pause lunghe, ti tocca il braccio mentre parla: tecniche da palco, le conosci bene. Ma quando si parla dell'atto di donazione lancia un'occhiata al telefono. È la casa persa che lo agita, non la morta.","questions":[{"id":"a1","q":"Chi era Chiara per lei?","a":"Un'anima in cammino. Molto generosa con la comunità.","aside":"Generosa. Non buona, non cara. Generosa."},{"id":"a2","q":"Chiara stava per donarvi la sua casa.","req":["d4"],"a":"Dopodomani, dal notaio. Capisce perché non avevo nessun motivo di volerla morta? Anzi.","aside":"È la prima frase sincera che dice da quando sei arrivato.","insight":"La morte di Chiara fa perdere al Maestro una casa: gli conveniva viva."},{"id":"a3","q":"Chi gestisce i soldi della comunità?","a":"Viola. Io sono una guida, non un ragioniere. Non so nemmeno la password della banca.","insight":"È Viola a gestire i soldi della comunità."},{"id":"a4","q":"Dov'era stanotte?","a":"In meditazione con dodici anime, dalle dieci alle due. Anche Viola, arrivata un po' tardi. Aveva da sistemare le tazze, credo.","insight":"Il Maestro ha dodici testimoni. Viola è arrivata tardi alla meditazione."}]},{"id":"gabriele","name":"Gabriele Ferrante","role":"Marito di Chiara, 45 anni","look":"Barba di due giorni, la camicia di ieri, gli occhi rossi.","tell":"Stringe le chiavi della macchina come un rosario. Quando parla della setta alza la voce, quando parla di Chiara la perde. Rabbia e dolore, tutti e due veri.","questions":[{"id":"g1","q":"Perché era qui?","a":"Per portarmela a casa. Questa gente le aveva preso tutto, ora anche la casa. Ieri sera mi ha detto di no. Ho dormito in macchina nel parcheggio: senza di lei non me ne andavo.","insight":"Gabriele ha passato la notte in macchina, fuori dall'eremo."},{"id":"g2","q":"Dal parcheggio ha visto qualcosa?","a":"Si vede il corridoio delle celle. Alle dieci e un quarto una donna in tunica, con i capelli rossi raccolti, ha bussato da Chiara con una tazza in mano. È uscita a mani vuote.","insight":"Alle 22:15 una donna con i capelli rossi ha portato una tazza a Chiara."},{"id":"g3","q":"Avevate litigato?","a":"Urlato. L'ultima cosa che le ho detto è: «Sei in una setta.» Lei ha riso. Ha riso."}]}],"bluff":{"text":"Annunci che sulla tazza di Chiara ci sono impronte che non sono sue, e che stanno per confrontarle.","reactions":{"viola":"«Le tazze le ho lavate io, ieri pomeriggio. Tutte. Le mie impronte ci sono per forza.» Nessuno le aveva chiesto niente.","anael":"«Io non tocco le tazze degli altri. Io non tocco niente.»","gabriele":"«Bene. Trovatelo.»"},"insight":"Al bluff delle impronte Viola ha giustificato le sue prima ancora che qualcuno le trovasse."},"culprit":"viola","key":["x2","v3","x1"],"solution":"Il Maestro è un venditore di fumo, ma la morte di Chiara gli costava una casa. Era Viola a tenere i soldi della comunità, e se ne teneva metà: Chiara aveva fatto i conti e voleva parlarne con «V.» prima che col Maestro. Ieri sera Viola ha spezzato un ramo di oleandro, lasciandosi la linfa sulle dita, ha messo le foglie nella tazza di Chiara e gliel'ha portata in cella alle 22:15, come ha visto Gabriele dal parcheggio. Poi è andata alla meditazione, in ritardo, e ha firmato per ultima con un'altra penna. La tisana di tutti era innocua: il veleno era solo in quella tazza.","contradictions":[{"id":"x1","a":"v2","b":"a3","who":"viola","reply":"Va bene, i bonifici li faccio io. Il Maestro non sa accendere un computer. Dieci anni di lavoro gratis: qualcosa mi spettava.","aside":"«Mi spettava.» Metà di ogni ritiro.","insight":"Viola si teneva metà dei soldi della comunità. Era lei la «V.» del quaderno di Chiara.","lie":true},{"id":"x2","a":"v1","b":"g2","who":"viola","reply":"Chiara era debole per il digiuno. Le ho portato la tazza in cella, per gentilezza. Non volevo che pensaste male.","aside":"Per gentilezza. E subito dopo, in ritardo alla meditazione.","insight":"Viola ha portato di persona la tazza a Chiara alle 22:15, dopo aver detto che ognuno si serviva da solo.","lie":true}]},{"id":"guaritore-nardo","title":"L'acqua di luce","place":"Villa Perrone, Nardò","teaser":"Un guaritore, una bottiglietta benedetta, un morto nel letto.","intro":"Da maggio, ogni martedì, il «Maestro» Elio Fanizza impone le mani a Donato Perrone, 76 anni, diabetico, per novanta euro a bottiglietta. Stamattina Donato è stato trovato morto nel suo letto: coma ipoglicemico, troppa insulina. La figlia ha già chiamato i giornali: «Il ciarlatano ha ucciso mio padre». I ciarlatani li conosci bene. Proprio per questo vuoi guardare prima di dare ragione a qualcuno.","details":[{"id":"d1","label":"La penna d'insulina","text":"Sul comodino. Il selettore è fermo su 40 unità. Sul foglio della terapia attaccato all'armadio, il medico ha scritto: «8 unità la sera».","insight":"A Donato hanno iniettato cinque volte la sua dose."},{"id":"d2","label":"L'acqua di luce","text":"Una bottiglietta con l'etichetta dorata: «Acqua di luce – 90 €». Dentro: acqua, sale e un rametto di rosmarino.","insight":"Il rimedio del Maestro è acqua salata: una truffa, ma innocua."},{"id":"d3","label":"Il volantino del Maestro","text":"In fondo, in piccolo: «Non sospendete né modificate le terapie del vostro medico. Il Maestro affianca, non sostituisce.»","insight":"Il Maestro si tiene alla larga dalle medicine, e lo mette per iscritto."},{"id":"d4","label":"Il glucometro","text":"In memoria, due misurazioni di ieri: 20:52, glicemia 190. 22:48, glicemia 176.","insight":"Alle 22:48 qualcuno ha misurato la glicemia di Donato. Di solito si fa prima dell'insulina."},{"id":"d5","label":"Il testamento","text":"Nello studio, la bozza di un nuovo testamento, non firmata: la villa e gli uliveti a Rosaria Mazzotta, «per l'affetto e la cura». Un post-it: «Notaio, giovedì ore 10».","insight":"Giovedì Donato avrebbe lasciato la villa alla badante."},{"id":"d6","label":"La serratura elettronica","text":"Registro degli ingressi di ieri: 21:02 uscita badge 2. 22:41 ingresso badge 2. 22:58 uscita badge 2.","insight":"Chi ha il badge 2 è uscito alle 21:02 ed è rientrato alle 22:41, per diciassette minuti."},{"id":"d7","label":"Le ricevute","text":"Sei ricevute del Maestro, 250 euro a seduta. Pagate tutte con la carta di Loredana Perrone.","insight":"Era Loredana a pagare il guaritore."}],"suspects":[{"id":"elio","name":"Elio Fanizza, «il Maestro»","role":"Guaritore, 58 anni","look":"Camicia di lino bianca, tre braccialetti di legno, voce da radio notturna. Ti ha già toccato il braccio due volte.","tell":"Mentre lo osservi, lui osserva te: frasi aperte, pause, aspetta di vedere dove annuisci. Lettura a freddo da manuale. Ma quando si parla della penna d'insulina fa un passo indietro e mette le mani in tasca: quella roba non la tocca, e ci tiene che tu lo veda.","questions":[{"id":"e1","q":"Cosa ha fatto ieri sera a Donato?","a":"Imposizione delle mani, venti minuti. L'acqua di luce. Alle otto e mezza me ne sono andato, e dalle dieci ero in diretta sulla mia pagina: novanta persone collegate a pregare con me, fino a mezzanotte.","insight":"Il Maestro è andato via alle 20:30. Dalle 22 a mezzanotte era in diretta con novanta persone."},{"id":"e2","q":"La sua acqua di luce è acqua e sale.","req":["d2"],"a":"Acqua, sale, rosmarino. E fede. La fede ce la mette il cliente.","aside":"Non si scompone. È la cosa più sincera che ha detto finora.","insight":"Il Maestro ammette che la sua acqua è un trucco.","lie":true},{"id":"e3","q":"Chi l'ha chiamata in questa casa?","a":"La figlia. Mi ha cercato lei, a maggio: «Papà non crede ai medici, crede a lei.» Strano. Il vecchio a me non credeva per niente. Mi guardava come si guarda uno che vende pentole.","insight":"È stata Loredana a portare il guaritore in casa. Donato non ci credeva."}]},{"id":"rosaria","name":"Rosaria Mazzotta","role":"Badante, 53 anni","look":"Occhi gonfi, grembiule ancora addosso. Al dito una fede sottile, nuova.","tell":"Gira la fede col pollice senza accorgersene. Quando parla di Donato dice «lui», mai «il signore». Quando nomini Loredana si irrigidisce e guarda la porta.","questions":[{"id":"b1","q":"Dov'era ieri sera?","a":"Era la mia sera libera. La signora Loredana ha detto che l'insulina delle nove gliela faceva lei, e di andare pure. Ero a Galatone da mia sorella, a cena. Eravamo in dieci.","insight":"Rosaria era a cena a Galatone con dieci persone. L'insulina delle 21 doveva farla Loredana."},{"id":"b2","q":"Di chi è il badge 2?","req":["d6"],"a":"Il badge 1 è il mio, ed era nella mia borsa a Galatone. Il 2 è della signora Loredana. Il 3 era di lui, ma non usciva più di casa.","insight":"Il badge 2 è quello di Loredana."},{"id":"b3","q":"Quella fede è nuova.","req":["t_rosaria"],"a":"(La guarda.) Me l'ha data lui, a Pasqua. Ci volevamo sposare a settembre, in comune, senza feste. Lo sapeva solo il notaio. E forse lei.","insight":"Donato voleva sposare Rosaria. Forse Loredana lo sapeva.","lie":true}]},{"id":"loredana","name":"Loredana Perrone","role":"Figlia di Donato, 47 anni","look":"Tailleur grigio, occhiali da sole in casa. Il telefono sempre in mano: risponde ai giornalisti.","tell":"Parla del padre al passato con naturalezza, come se ci fosse abituata da tempo. Qualunque sia la domanda, la risposta finisce sul Maestro. Quando nomini Rosaria stringe la mascella e il telefono.","questions":[{"id":"l1","q":"A che ora è andata via ieri sera?","a":"Alle nove, dopo avergli fatto l'insulina. Otto unità, come sempre. Poi a casa mia, a Lecce. Non sono più tornata.","insight":"Loredana giura di essere andata via alle 21 e di non essere più tornata."},{"id":"l2","q":"Il guaritore lo pagava lei.","req":["d7"],"a":"Papà ci credeva, io volevo solo farlo contento. E adesso guardate cosa ha combinato quel ciarlatano.","aside":"Le hai chiesto chi pagava. Lei ti ha risposto su chi è il colpevole.","insight":"Loredana ha portato e pagato il guaritore, e ora lo accusa.","lie":true},{"id":"l3","q":"Giovedì suo padre lasciava la villa a Rosaria.","req":["d5"],"a":"La villa di mio nonno a una badante? Papà non era più lucido. Quello gli aveva confuso la testa con le sue acque.","insight":"Loredana sapeva del nuovo testamento: giovedì avrebbe perso la villa."}]}],"contradictions":[{"id":"x1","a":"l1","b":"b2","who":"loredana","reply":"Va bene, sono tornata. Avevo dimenticato il caricabatterie. Dieci minuti, papà dormiva.","aside":"Diciassette minuti. E un uomo che dorme non si misura la glicemia da solo.","insight":"Loredana è rientrata di nascosto alle 22:41, per diciassette minuti, mentre il padre dormiva.","lie":true}],"bluff":{"text":"Annunci che la penna d'insulina di Donato è di quelle nuove: registra ora e dose di ogni iniezione.","reactions":{"elio":"«Visto? Adesso lo vedete che io non c'entro.» È già tranquillo.","rosaria":"Stringe la fede e chiude gli occhi. «Allora sapremo chi.»","loredana":"«La seconda se l'è fatta lui, papà. Si confondeva sempre con le dosi.»"},"insight":"Al bluff della penna, Loredana ha detto che il padre si faceva le iniezioni da solo. Prima aveva detto che gliele faceva lei."},"culprit":"loredana","key":["x1","l3","l2"],"solution":"Il ciarlatano era un parafulmine. Loredana ha cercato il Maestro a maggio, quando ha capito che il padre voleva sposare Rosaria e lasciarle la villa, e l'ha pagato lei perché in casa ci fosse un colpevole pronto. Ieri sera ha mandato via Rosaria, è uscita alle 21:02 ed è rientrata alle 22:41 col suo badge. Ha misurato la glicemia al padre addormentato e gli ha iniettato 40 unità; alle 22:58 era già fuori. Il Maestro, a quell'ora, pregava in diretta con novanta persone: truffatore sì, assassino no."},{"id":"paliomurgia","title":"Scirocco non corre","place":"Masseria Pozzo Nuovo, tra Santeramo e Gioia del Colle","teaser":"Il favorito del palio sta morendo nel box. Il cane non ha abbaiato.","intro":"Scirocco è il cavallo da battere al Palio dei Casali, tra sei giorni. Stanotte alle undici la veterinaria lo trova nel box in un bagno di sudore, col cuore che batte a scatti. Vivrà, forse. Correre, mai. Il proprietario ha un nome in testa, quello del suo rivale, e ti ha chiamato per sentirselo confermare.","details":[{"id":"d1","label":"La mangiatoia","text":"Nella biada, frammenti di foglie verdi, lunghe e coriacee, sminuzzate a mano. Oleandro.","insight":"Scirocco è stato avvelenato con oleandro mescolato alla biada."},{"id":"d2","label":"La siepe","text":"Lungo il viale d'ingresso, la siepe di oleandri ha rami strappati di fresco. Strappati, non tagliati. Il lattice bianco è ancora appiccicoso.","insight":"Qualcuno ha strappato l'oleandro a mani nude, poche ore fa. Il lattice irrita la pelle."},{"id":"d3","label":"Il cancello elettrico","text":"La memoria registra: «20:47 apertura, telecomando n. 3 (fantino)». «21:12 uscita, telecomando n. 3.»","insight":"Ieri sera alle 20:47 qualcuno è entrato col telecomando del fantino, ed è rimasto 25 minuti."},{"id":"d4","label":"Il cane","text":"Brigante, pastore maremmano, abbaia a chiunque non sia di casa. Il custode giura che ieri sera non ha fatto un verso.","insight":"Chi è entrato ieri sera era uno di casa: il cane lo conosceva."},{"id":"d5","label":"Il biglietto del padrone","text":"Sulla bacheca della selleria, datato ieri: «Enzo, grazie di tutto. Al palio Scirocco lo monta il ragazzo.»","insight":"Ieri Enzo ha saputo che non avrebbe più montato Scirocco al palio."},{"id":"d6","label":"L'armadietto della veterinaria","text":"Siringhe usate, un flacone di cortisone quasi finito. Nel registro dei trattamenti di Scirocco mancano due pagine, strappate.","insight":"Qualcuno ha curato Scirocco di nascosto e ha fatto sparire le pagine del registro."},{"id":"d7","label":"Il fango del paddock","text":"Impronte fresche verso il box: stivaletti piccoli, numero 39, con la suola liscia da equitazione.","insight":"Chi è andato al box ieri sera ha il piede piccolo e porta stivali da cavaliere."}],"suspects":[{"id":"enzo","name":"Enzo Cassano","role":"Fantino, 31 anni","look":"Piccolo e asciutto, stivaletti da monta lucidi, guanti infilati in tasca.","tell":"Si strofina i palmi sui calzoni di continuo. Sono arrossati, con vesciche piccole come chicchi di riso. Ha i guanti da monta in tasca e non se li mette, nemmeno adesso che fa freddo.","questions":[{"id":"e1","q":"Dov'era ieri sera?","a":"A Santeramo, a cena con gli amici, dalle otto a mezzanotte. In scuderia non ci ho messo piede.","insight":"Enzo giura di non essere venuto in scuderia ieri sera."},{"id":"e2","q":"Ieri le hanno tolto Scirocco.","req":["d5"],"a":"Il padrone è libero. Ci sono altri cavalli, altri palii. Io sono giovane.","aside":"Lo dice sorridendo. Il sorriso si ferma sotto gli occhi.","insight":"Enzo ha perso la monta di Scirocco e fa finta che non conti."},{"id":"e3","q":"Ha i palmi pieni di vesciche. Il lattice dell'oleandro fa così.","req":["d2","t_enzo"],"a":"Le redini. Sono un fantino, cosa si aspetta?","aside":"Le redini fanno calli sulle dita, non vesciche sul palmo. E lui monta con i guanti: ce li ha in tasca.","insight":"Enzo mente sulle vesciche: ha strappato oleandro a mani nude.","lie":true}]},{"id":"gino","name":"Gino Pastore","role":"Allevatore rivale, 58 anni","look":"Due metri di uomo, scarpe numero 46, voce che riempie il cortile.","tell":"Urla, gesticola, ti punta il dito addosso. Ma quando parla di Scirocco malato abbassa la voce e chiede come respira. Un uomo di cavalli non gode di un cavallo che muore, nemmeno di quello dell'avversario.","questions":[{"id":"g1","q":"In piazza ha detto che Scirocco al palio non ci arriva.","a":"Intendevo che lo battevo io, con Tramontana! Ieri sera ero alla fiera di Foggia, col camion e due puledri. Rientrato alle due. C'è la ricevuta del casello.","insight":"Gino era a Foggia fino a notte: la ricevuta del casello lo prova."},{"id":"g2","q":"Come funzionano le cose al palio?","a":"Male. I fantini si comprano. I rioni non pagano per vincere, pagano per far perdere gli altri. E quest'anno il rione Borgo ha soldi da buttare e paura di Scirocco.","insight":"Al palio il rione Borgo paga i fantini per far perdere Scirocco."},{"id":"g3","q":"Il cane della masseria non ha abbaiato.","req":["d4"],"a":"Brigante? Quello a me mi mangia vivo. L'anno scorso mi ha strappato un pantalone qui al cancello. Chiedete al custode.","insight":"Brigante abbaia a Gino: se fosse venuto lui avrebbe svegliato la masseria."}]},{"id":"anna","name":"Anna Mele","role":"Veterinaria, 45 anni","look":"Zoccoli di gomma, camice sporco, stetoscopio in tasca. Non dorme da ieri.","tell":"Risponde con precisione su tutto, tranne quando si parla della zampa posteriore di Scirocco: lì diventa vaga e si guarda le mani. Nasconde qualcosa sul cavallo, non sull'avvelenamento.","questions":[{"id":"v1","q":"Come sta Scirocco?","a":"Vivo, per ora. Il cuore batte a scatti. Al palio non ci va, questo è sicuro."},{"id":"v2","q":"Cortisone, e due pagine strappate dal registro.","req":["d6"],"a":"Un'infiammazione al garretto. Il padrone non voleva che si sapesse prima del palio, perdeva valore. Le pagine le ho strappate io. Ma il cortisone non avvelena nessuno, e io quel cavallo lo curo da quando è nato.","insight":"Anna nascondeva una cura al garretto di Scirocco per conto del proprietario.","lie":true},{"id":"v3","q":"Chi dà la biada la sera?","a":"L'artiere, alle sei in punto. Dopo quell'ora nessuno ha motivo di toccare la mangiatoia. Le foglie ce le ha messe qualcuno dopo le sei.","insight":"L'oleandro è stato messo nella biada dopo le 18."}]}],"bluff":{"text":"Annunci che il rione Borgo ha già ammesso di aver pagato un fantino per questo palio.","reactions":{"enzo":"«Quale fantino? A palio siamo dieci.» Poi chiede, piano, se il Borgo ha fatto dei nomi.","gino":"«Era ora! Lo dico da vent'anni!»","anna":"«Io di rioni non so niente. Io curo cavalli.»"},"insight":"Al bluff sul rione Borgo Enzo ha voluto sapere se era stato fatto il suo nome."},"culprit":"enzo","key":["x1","e3","d7"],"solution":"Il rione Borgo aveva pagato Enzo per far perdere Scirocco. Ieri il padrone gli toglie la monta: Enzo non può più perdere apposta, e il patto salta. Allora toglie di mezzo il cavallo. Alle 20:47 entra col suo telecomando, il cane lo conosce e tace, strappa l'oleandro a mani nude e lo mescola alla biada. Le vesciche sui palmi e gli stivaletti del 39 nel fango lo tradiscono. Gino, il rivale che tutti accusano, era a Foggia; Anna nascondeva solo un garretto infiammato.","contradictions":[{"id":"x1","a":"e1","b":"d3","who":"enzo","reply":"Sono passato a salutarlo. Dieci minuti. Era il mio cavallo, no?","aside":"Venticinque minuti, dice il cancello. E l'ha detto solo quando ha dovuto.","insight":"Enzo è entrato in scuderia ieri sera alle 20:47, e l'aveva negato.","lie":true}]},{"id":"ulivetolisi","title":"Cenere d'ulivo","place":"Uliveto dei Lisi, campagne tra Ostuni e Carovigno","teaser":"Quaranta ulivi di cinquecento anni. Una notte sola per bruciarli.","intro":"Alle due di notte l'uliveto dei Lisi ha preso fuoco: quaranta ulivi monumentali, alcuni piantati prima della scoperta dell'America. Tutti guardano il pastore del terreno accanto, che ieri bruciava le stoppie e con i Lisi litiga da anni. L'assicurazione ti ha chiesto di dare un'occhiata prima di pagare seicentomila euro. Tu tocchi una foglia rimasta sui rami alti, e si sbriciola.","details":[{"id":"d1","label":"I rami alti","text":"I tronchi sono cavi e neri. Ma sui rami alti che il fuoco non ha raggiunto, le foglie sono color ruggine, arricciate, secche da mesi.","insight":"Gli ulivi erano morti prima dell'incendio: sono i segni della Xylella."},{"id":"d2","label":"La tanica nel canale","text":"Nel canale di scolo, una tanica verde da cinque litri col tappo rosso. Odore di miscela per motosega.","insight":"Il fuoco è stato appiccato con la miscela di una motosega."},{"id":"d3","label":"La polizza","text":"Stipulata ad aprile: 600.000 euro per quaranta ulivi monumentali «in ottimo stato vegetativo». Firmata da Vito Lisi, per conto dello zio. Allegata, la perizia dell'agronomo Sgobba.","insight":"Sei mesi fa Vito ha assicurato gli ulivi per 600.000 euro, dichiarandoli sani."},{"id":"d4","label":"Le stoppie del pastore","text":"Il campo accanto ha le stoppie bruciate. Il fuoco si è fermato alla fascia arata lungo il muretto. Oltre, un metro d'erba secca intatta. L'uliveto comincia dopo.","insight":"Le stoppie del pastore si sono spente alla fascia arata: l'uliveto è bruciato per un altro fuoco."},{"id":"d5","label":"Il capanno degli attrezzi","text":"Nel capanno di Vito, la motosega col serbatoio vuoto. Sullo scaffale, nella polvere, il segno pulito e rettangolare di una tanica che non c'è più.","insight":"Dal capanno di Vito manca una tanica."},{"id":"d6","label":"La lettera della Regione","text":"«Monitoraggio Xylella: sopralluogo previsto per il 15 del mese prossimo. In caso di positività, abbattimento obbligatorio.»","insight":"Tra un mese la Regione avrebbe certificato gli ulivi infetti. Addio assicurazione."},{"id":"d7","label":"Le foto della perizia","text":"Ulivi verdi, rigogliosi, carichi di olive. In una foto, appeso a un tronco, un cartello scritto a mano: «Vendesi olio nuovo 2019».","insight":"Le foto della perizia di aprile hanno anni: gli ulivi sani sono quelli di prima."}],"suspects":[{"id":"tommaso","name":"Tommaso Carrieri","role":"Pastore, terreno confinante","look":"Barba incolta, bastone di ulivo, odore di stalla. Ieri pomeriggio ha bruciato le stoppie.","tell":"Risponde a monosillabi e guarda in faccia. Sulle maniche ha macchie di sangue secco e paglia: non è fuliggine da incendio, è roba da stalla.","questions":[{"id":"p1","q":"Dov'era stanotte?","a":"Nella stalla. Una pecora non riusciva a partorire. Ho chiamato il veterinario alle due, è rimasto fino alle quattro. Le stoppie le avevo spente alle sei di ieri, col permesso del Comune.","insight":"Tommaso ha un alibi: il veterinario, dalle due alle quattro."},{"id":"p2","q":"Che rapporti aveva con i Lisi?","a":"Col vecchio buoni. Col nipote no: mi ha denunciato due volte per le pecore nell'uliveto. Ma là dentro da due anni non c'era più niente da mangiare. Erba secca e alberi morti.","insight":"Secondo Tommaso l'uliveto era morto da due anni."},{"id":"p3","q":"Ha visto qualcuno stanotte?","a":"Verso l'una e mezza, andando alla stalla. Fari sulla stradina dell'uliveto, poi spenti a metà. Il pick-up bianco dei Lisi: lo riconosco dal rumore, ha la marmitta rotta da un anno.","insight":"All'1:30 il pick-up di Vito era sulla stradina dell'uliveto, a fari spenti."}]},{"id":"vito","name":"Vito Lisi","role":"Nipote del proprietario, gestisce i terreni","look":"Camicia bianca, occhiali da sole in testa, pick-up bianco parcheggiato sulla strada.","tell":"Tiene le mani in tasca. Quando le tira fuori per indicare il pastore, sul dorso della destra i peli sono crespi e bruciacchiati, come dopo una fiammata presa troppo da vicino.","questions":[{"id":"l1","q":"Dov'era stanotte?","a":"A casa, a Ostuni. Dormivo. Mi hanno svegliato i pompieri alle tre.","insight":"Vito dice di non essersi mosso da Ostuni."},{"id":"l2","q":"Com'erano gli ulivi?","a":"Sani! Monumenti. Mio nonno ci faceva l'olio migliore della contrada. Adesso è tutto cenere, per colpa di quello e delle sue stoppie.","insight":"Vito giura che gli ulivi erano sani e accusa il pastore."},{"id":"l3","q":"Dal suo capanno manca una tanica. E lei ha la mano bruciacchiata.","req":["d5","t_vito"],"a":"Ho acceso il barbecue, domenica. Una fiammata.","aside":"Domenica è stata quattro giorni fa. I peli bruciati si spezzano e cadono in un paio di giorni: questi sono ancora arricciati.","insight":"Vito mente sulla mano: si è bruciato stanotte, accendendo il fuoco.","lie":true},{"id":"l4","q":"La Regione doveva controllare la Xylella tra un mese.","req":["d6"],"a":"Controlli di routine. Quegli alberi erano sani.","aside":"Lo ripete: sani. Come chi lo ha scritto su una polizza.","insight":"Vito sapeva del controllo della Regione in arrivo."}]},{"id":"sgobba","name":"Enrico Sgobba","role":"Agronomo, autore della perizia","look":"Gilet con dieci tasche, occhiali spessi, una cartellina stretta al petto.","tell":"Si toglie gli occhiali e li pulisce ogni volta che la domanda si avvicina alla perizia. Sudore sul labbro. È paura di perdere l'iscrizione all'albo, non di un fuoco.","questions":[{"id":"e1","q":"Com'erano gli ulivi ad aprile?","a":"Sani. Esemplari monumentali. La perizia l'ho firmata io.","insight":"Sgobba dice di aver visto gli ulivi sani ad aprile."},{"id":"e2","q":"In una foto della sua perizia c'è un cartello del 2019.","req":["d7"],"a":"(Pulisce gli occhiali a lungo.) Le foto me le ha date Vito. Quel giorno non sono andato. Mi ha pagato il doppio per fare in fretta. Non pensavo che...","insight":"Sgobba ha firmato la perizia senza vedere gli ulivi, con le foto vecchie che gli ha dato Vito.","lie":true},{"id":"e3","q":"Chi le ha chiesto la perizia?","a":"Vito. Lo zio non ne sapeva niente. «Non facciamolo preoccupare», diceva.","insight":"Il vecchio Lisi non sapeva della polizza: l'ha voluta Vito."}]}],"bluff":{"text":"Dici che ad agosto la Regione aveva già prelevato di nascosto un campione di rami dall'uliveto, e che i risultati arrivano domani.","reactions":{"tommaso":"«Allora vedrete che erano morti. Lo sa tutta la contrada.»","vito":"«Ad agosto? E chi li ha fatti entrare? Il terreno è privato.» Poi si corregge: «Comunque erano sani.»","sgobba":"Si toglie gli occhiali. «Ad agosto? Nessuno mi ha avvisato.»"},"insight":"Al bluff delle analisi Vito si è preoccupato di chi fosse entrato nel terreno, non di cosa avessero trovato."},"culprit":"vito","key":["x1","l3","x2"],"solution":"Gli ulivi erano morti di Xylella da due anni, come dicono le foglie secche sui rami alti e come sa tutta la contrada. Ad aprile Vito li ha assicurati per 600.000 euro con una perizia fatta su foto vecchie, all'insaputa dello zio. Tra un mese la Regione avrebbe certificato l'infezione e la polizza non sarebbe valsa niente. Così all'1:30 Vito arriva col pick-up a fari spenti, versa la miscela della sua motosega e appicca il fuoco, bruciandosi la mano. Le stoppie di Tommaso si erano spente alla fascia arata, e alle due lui era in stalla col veterinario.","contradictions":[{"id":"x1","a":"l1","b":"p3","who":"vito","reply":"Sono passato a controllare. Rubano la legna degli ulivi vecchi, lo sanno tutti. Cinque minuti e sono tornato a casa.","aside":"Cinque minuti all'una e mezza. Il fuoco è partito alle due.","insight":"Vito era all'uliveto mezz'ora prima dell'incendio, dopo aver giurato di non essersi mosso da Ostuni.","lie":true},{"id":"x2","a":"l2","b":"e2","who":"vito","reply":"Le foto erano belle. Gli alberi erano quelli. Che differenza fa l'anno?","aside":"Seicentomila euro di differenza.","insight":"Vito ha fatto assicurare ulivi che sapeva morti, con foto di anni prima.","lie":true}]},{"id":"otranto-recensione","title":"L'ultima recensione","place":"Dimora dei Sette Archi, Otranto","teaser":"Un ispettore di guide che non perdonava. Stanotte non ha fatto in tempo.","intro":"Fabrizio Landi scriveva per la Guida dei Cento Cortili, e mezzo sud tremava alle sue visite. Stamattina la cameriera l'ha trovato morto nella sua suite della Dimora dei Sette Archi: shock anafilattico. Era gravemente allergico alla frutta a guscio e girava sempre con l'adrenalina in tasca. Stanotte non l'aveva. La titolare, che ieri sera ci ha litigato davanti a tutti, ti ha chiamato prima che arrivino i giornali.","details":[{"id":"d1","label":"La giacca di Landi","text":"Sulla sedia della suite. Il taschino interno è deformato dalla sagoma di una penna d'adrenalina. È vuoto.","insight":"Landi portava sempre l'adrenalina addosso. Stanotte qualcuno gliel'ha tolta."},{"id":"d2","label":"I bicchierini sul terrazzo","text":"Due bicchierini da amaro sul tavolino d'angolo. In uno, un fondo scuro e denso che sa di mallo di noce.","insight":"Landi ha bevuto nocino: per un allergico alla frutta a guscio, veleno."},{"id":"d3","label":"Il carrello del bar","text":"Amari della casa, tutti con l'etichetta della Dimora. Nessun nocino. Sotto il carrello, il tappo a vite di una mignon: «Nocino della Nonna – Vignola (MO)».","insight":"Il nocino non viene dal bar: qualcuno l'ha portato da fuori, dall'Emilia."},{"id":"d4","label":"La cartella di Landi","text":"Fascicoli con nomi e cifre. «Carluccio – 15.000 – entro sabato.» Più sotto: «L.O. – foto 2019 – pagato tre volte. La quarta a Otranto.»","insight":"Landi ricattava Ottavia, e una certa «L.O.» che paga dal 2019. La quarta rata doveva arrivare qui."},{"id":"d5","label":"La telecamera della reception","text":"Registrazione dalle 23 all'1:10: Ottavia al bancone, sempre inquadrata. Un check-in tardivo, poi i conti.","insight":"Tra le 23 e l'1:10 Ottavia non si è mai mossa dalla reception."},{"id":"d6","label":"Il menu di Landi","text":"In cucina, scritto a mano dallo chef: «Tavolo 4 – ALLERGIA GRAVE FRUTTA A GUSCIO». Ogni piatto spuntato due volte.","insight":"In cucina l'allergia di Landi era nota e controllata."},{"id":"d7","label":"La vasca delle ninfee","text":"Nel cortile, sotto le finestre delle camere al piano terra. Sul fondo, tra le radici, una penna d'adrenalina ancora sigillata.","insight":"L'adrenalina di Landi è finita nella vasca sotto le camere del piano terra, senza essere usata."}],"suspects":[{"id":"livia","name":"Livia Orsini","role":"Ospite della camera 2, al piano terra, 42 anni","look":"Camicetta stirata di fresco, capelli raccolti, accento emiliano. Ha chiesto un caffè e non l'ha toccato.","tell":"Lo chiama «Fabrizio». Solo per nome, con naturalezza. Nessun altro, qui dentro, lo chiama così. Ha le unghie mangiate fino alla carne e chiude le mani per non fartele vedere.","questions":[{"id":"v1","q":"Conosceva Landi?","a":"No. L'ho visto ieri a cena per la prima volta. Un amaro in terrazza, due chiacchiere, e alle dodici meno un quarto ero a letto.","insight":"Livia dice di aver conosciuto Landi solo ieri sera."},{"id":"v2","q":"Nella cartella di Landi c'è una «L.O.» che paga dal 2019.","req":["d4"],"a":"Ci saranno mille persone con quelle iniziali, in Italia.","aside":"Non le hai chiesto se fosse lei. Ci è arrivata da sola.","insight":"Livia si è riconosciuta nella «L.O.» ricattata da Landi.","lie":true},{"id":"v3","q":"Cosa avete bevuto in terrazza?","req":["d2"],"a":"Un amaro della casa. L'ha versato lui, dal carrello.","insight":"Livia dice che il digestivo l'ha versato Landi, dal bar della casa."}]},{"id":"ottavia","name":"Ottavia Carluccio","role":"Titolare della Dimora, 55 anni","look":"Lino bianco, voce ferma, occhi rossi di rabbia più che di pianto.","tell":"Non nasconde niente: lo detestava e te lo dice guardandoti. Quando parla del litigio alza il mento. Abbassa la voce solo quando parla della reputazione della Dimora: è quella che ha paura di perdere.","questions":[{"id":"o1","q":"Ieri sera ha litigato con Landi.","a":"Mi ha chiesto quindicimila euro per una recensione buona. Gli ho detto di andare al diavolo, davanti a tutta la sala. Ne vado fiera.","insight":"Landi ricattava Ottavia, che ha rifiutato davanti a tutti."},{"id":"o2","q":"Dov'era tra le 23 e l'una?","a":"Alla reception. Una coppia arrivata tardi da Monaco, poi la cassa. La telecamera mi inquadra tutta la notte, se vuole guardarla.","insight":"Ottavia dice di essere rimasta alla reception tutta la notte, sotto la telecamera."},{"id":"o3","q":"Come ha prenotato la signora Orsini?","a":"Per telefono, tre settimane fa. Una cosa strana: voleva le stesse notti del signor Landi. Mi ha chiesto se lui aveva già confermato. Ho pensato che fossero amici.","insight":"Livia sapeva che Landi sarebbe stato qui e ha prenotato apposta le stesse notti."}]},{"id":"matteo","name":"Matteo Sticchi","role":"Chef, 34 anni","look":"Giacca da cuoco sbottonata, dita gialle di nicotina. Mastica una gomma alla menta con accanimento.","tell":"Mastica la gomma come se ne andasse della vita, e ogni tanto si annusa le dita: copre un odore. Quando nomini il cortile guarda altrove. Ha visto qualcosa, e non vuole spiegare perché era lì.","questions":[{"id":"m1","q":"Cosa ha cucinato per Landi?","a":"Un menu a parte, controllato due volte. Io con le allergie non scherzo: ieri in cucina non è entrata una noce.","insight":"Dalla cucina di Matteo non è uscita frutta a guscio."},{"id":"m2","q":"Landi parlava della sua allergia?","a":"Con tutti. Ieri ha rimandato indietro il pane per due semi, urlando «volete ammazzarmi?». L'ha sentito tutta la sala. Anche la signora emiliana al tavolo accanto.","insight":"Tutta la sala, Livia compresa, sapeva dell'allergia di Landi."},{"id":"m3","q":"Lei era in cortile stanotte. Cosa ha visto?","req":["t_matteo"],"a":"(Sputa la gomma.) Ero lì a fumare, verso mezzanotte. Se Ottavia lo sa mi caccia: in servizio non si fuma. Ho visto aprirsi una finestra del piano terra e qualcosa cadere nella vasca. Ho pensato a una sigaretta.","insight":"Verso mezzanotte qualcuno ha buttato qualcosa nella vasca da una finestra del piano terra.","lie":true}]}],"contradictions":[{"id":"x1","a":"v1","b":"o3","who":"livia","reply":"Va bene. Lo conoscevo. Sono venuta per dirgli in faccia che non avrei più pagato. Tutto qui.","aside":"Per dirglielo in faccia ha fatto novecento chilometri. E poi ci ha bevuto un amaro insieme.","insight":"Livia conosceva Landi, era una delle sue vittime e ha prenotato apposta le sue stesse notti.","lie":true},{"id":"x2","a":"v3","b":"d3","who":"livia","reply":"Il nocino... è di mia nonna, lo porto sempre in viaggio. Gliel'ho offerto io. Non sapevo niente della sua allergia.","aside":"L'allergia Landi l'ha urlata a tutta la sala, a un metro dal suo tavolo.","insight":"Il nocino l'ha portato e versato Livia, non il bar. E finge di non sapere dell'allergia.","lie":true}],"bluff":{"text":"Annunci che la penna d'adrenalina di Landi è stata ritrovata e che la scientifica ci ha trovato un'impronta.","reactions":{"livia":"«Dopo una notte in acqua?» Poi si ferma. Nessuno ha parlato di acqua.","ottavia":"«Bene. Così la smettete di guardare me.»","matteo":"Diventa pallido e guarda verso il cortile. Poi si mette in bocca un'altra gomma."},"insight":"Livia sapeva che la penna era stata in acqua. Nessuno gliel'aveva detto."},"culprit":"livia","key":["x2","x1","d7"],"solution":"Landi ricattava Livia dal 2019 con delle foto, e lei aveva già pagato tre volte. Ha prenotato apposta le sue stesse notti e si è portata da casa un nocino, sapendo, come tutta la sala, che Landi era allergico alla frutta a guscio. In terrazza gli ha offerto il «suo amaro» e intanto gli ha sfilato l'adrenalina dal taschino. Tornata in camera, al piano terra, l'ha gettata dalla finestra nella vasca delle ninfee, dove Matteo l'ha vista cadere. Ottavia lo odiava apertamente, ma tutta la notte è rimasta sotto la telecamera della reception."},{"id":"sedutacastellana","title":"Vieni con me","place":"Villa Fanizzi, campagne di Castellana Grotte","teaser":"Le luci si spengono. La moglie morta chiama. Il marito risponde.","intro":"Ernesto Fanizzi, 76 anni, vedovo da due, voleva risentire la voce di sua moglie Clara. Stasera, nella sua villa, il Professor Orfeo spegne le luci e la voce arriva: «Ernesto, vieni con me.» Quando le luci si riaccendono Ernesto è riverso sul tavolo, la mano stretta sullo spray per il cuore. Tutti accusano il medium. Tu i medium li conosci. Il problema è che il medium, forse, non c'entra.","details":[{"id":"d1","label":"Sotto il tavolo","text":"Una piccola cassa bluetooth fissata con nastro biadesivo sotto il piano, al centro.","insight":"La voce di Clara usciva da una cassa: il medium è un truffatore."},{"id":"d2","label":"Il tavolino","text":"Una delle tre gambe ha un piolo retrattile. Basta un ginocchio, dal posto del medium, per far «alzare» il tavolo.","insight":"Il tavolo che si muove è un trucco, azionato dal posto del medium."},{"id":"d3","label":"Lo spray di Ernesto","text":"Trinitrina sublinguale, nuovo. Pieno fino all'orlo. Uno spruzzo sulla lingua non pizzica, non brucia, non sa di niente.","insight":"Nello spray di Ernesto c'era acqua: la trinitrina vera pizzica sotto la lingua."},{"id":"d4","label":"Il cestino del bagno","text":"Uno spray di trinitrina vecchio, mezzo pieno, scadenza fra undici mesi. Accanto, la scatola del nuovo: «Farmacia Fanizzi, Putignano».","insight":"Lo spray buono, non scaduto, è stato buttato. Quello nuovo viene dalla farmacia di Filippo."},{"id":"d5","label":"Il contratto del medium","text":"Firmato da Ernesto la settimana scorsa: dieci sedute, 2.000 € l'una, pagamento a fine seduta. Stasera era la prima.","insight":"A Orfeo Ernesto vivo rendeva 20.000 euro. Morto, niente."},{"id":"d6","label":"La lettera nello studio","text":"Scritta da Ernesto al suo notaio, non ancora spedita: «Chiedere a Filippo la restituzione dei 180.000 € entro il mese. Altrimenti procedere.»","insight":"Ernesto stava per chiedere indietro a Filippo 180.000 euro, anche per vie legali."},{"id":"d7","label":"Il foglio del cardiologo","text":"Attaccato al frigo con una calamita: «In caso di dolore al petto: trinitrina sotto la lingua, subito. Evitare emozioni forti.»","insight":"In casa tutti sapevano che uno spavento poteva uccidere Ernesto, e che lo salvava solo lo spray."}],"suspects":[{"id":"orfeo","name":"Il Professor Orfeo","role":"Medium, al secolo Oronzo Pace","look":"Tunica scura, anello d'argento al pollice, voce impostata da teatro.","tell":"Ti tiene lo sguardo troppo a lungo, e ogni frase è aperta a metà: aspetta che tu la completi. Truffatore di mestiere. Ma quando guarda il corpo di Ernesto la voce da teatro gli si rompe: ha paura, e non l'aveva previsto.","questions":[{"id":"o1","q":"Cosa è successo al buio?","a":"Clara è venuta. L'avete sentita tutti. Ernesto ha detto «sì, amore mio» e poi... il cuore. L'emozione. Io sono solo un canale.","aside":"Parla a occhi socchiusi. Sta ancora recitando."},{"id":"o2","q":"La voce di Clara usciva da una cassa sotto il tavolo.","req":["d1"],"a":"(Un silenzio lungo.) La gente vuole una voce. Io gliela do. È teatro, non omicidio. Ernesto l'ho visto stasera per la prima volta, e stamattina ero a Lecce a fare una seduta per sei signore. Morto, mi è costato diciottomila euro.","insight":"Orfeo ammette il trucco, ma non era mai stato solo con Ernesto e la sua morte gli costa soldi.","lie":true},{"id":"o3","q":"Chi le ha dato i dettagli su Clara?","req":["o2"],"a":"Il nipote, Filippo. Mi ha cercato lui, un mese fa. Mi ha dato tutto: il soprannome, la canzone, la collana di perle. E una frase precisa da far dire a Clara: «Ernesto, vieni con me.» Su quella ha insistito.","insight":"È stato Filippo a ingaggiare Orfeo e a dettargli la frase che ha spaventato Ernesto."}]},{"id":"livia","name":"Livia Fanizzi","role":"Figlia, 44 anni","look":"Occhi gonfi, cardigan abbottonato storto, il telefono stretto nella mano sinistra.","tell":"Il pollice sinistro scorre sul telefono anche adesso, a vuoto. Quando dice «non l'ho mai lasciata» guarda il telefono, non te. Mente su qualcosa di piccolo, e se ne vergogna.","questions":[{"id":"l1","q":"Cosa ricorda del buio?","a":"Tenevo la mano di papà, a sinistra. Non l'ho mai lasciata. Mai.","insight":"Livia dice di non aver mai lasciato la mano del padre."},{"id":"l2","q":"Al buio lei ha lasciato la mano di suo padre e ha preso il telefono.","req":["t_livia"],"a":"(Piange.) Registravo. Volevo le prove che quel ciarlatano ci derubava. Senta. (Nella registrazione, dopo la voce di Clara, Ernesto ansima: «Lo spray... non fa niente... Filippo, non fa niente!»)","insight":"Al buio Ernesto ha usato lo spray, non ha funzionato, e ha chiamato Filippo.","lie":true},{"id":"l3","q":"Chi ha trovato il medium?","a":"Filippo. Diceva che a papà avrebbe fatto bene sentire la mamma. Io ero contraria. Per questo ho registrato.","insight":"La seduta l'ha voluta Filippo, non Livia."}]},{"id":"filippo","name":"Filippo Fanizzi","role":"Nipote e farmacista, 39 anni","look":"Occhiali sottili, giacca grigia, mani in tasca.","tell":"Tiene le mani in tasca e le tira fuori solo per sistemarsi gli occhiali. Parla dello zio come di un bugiardino: «evento cardiaco», «soggetto a rischio». Non dice mai «zio».","questions":[{"id":"f1","q":"Chi ha voluto la seduta?","a":"Livia. Io ero contrario, figuriamoci. Sono un uomo di scienza.","insight":"Filippo dice che la seduta l'ha voluta Livia."},{"id":"f2","q":"Chi si occupava dei farmaci di Ernesto?","a":"Io, da anni. Stamattina gli ho portato uno spray nuovo. Il vecchio era scaduto.","insight":"Filippo dice di aver sostituito lo spray stamattina perché quello vecchio era scaduto."},{"id":"f3","q":"Ernesto le chiedeva indietro 180.000 euro.","req":["d6"],"a":"Stavamo trattando. Il soggetto minacciava, poi perdonava. Funzionava così da sempre.","aside":"«Il soggetto». E la lettera dice «procedere»: non sembra un uomo che perdona.","insight":"Ernesto stava per chiedere a Filippo 180.000 euro: il movente."},{"id":"f4","q":"Nello spray che lei gli ha dato c'era acqua.","req":["d3"],"a":"Impossibile, era sigillato. Sarà un difetto di produzione. Capita.","aside":"Un farmacista che crede ai difetti di produzione della trinitrina.","insight":"Filippo non sa spiegare l'acqua nello spray che ha consegnato lui.","lie":true}]}],"bluff":{"text":"Annunci che il medico legale ha già notato una cosa: nessuno spray di trinitrina esce dalla fabbrica pieno fino all'orlo come quello di Ernesto.","reactions":{"orfeo":"«Spray? Io di medicine non so niente, faccio spettacolo!» Alza le mani.","livia":"«Ma papà se l'è spruzzato, l'ho sentito!»","filippo":"«I flaconi da duecento dosi sono pienissimi, sono tutti così. Lo dico da professionista.» Si sistema gli occhiali due volte."},"insight":"Al bluff sullo spray Filippo ha difeso il flacone con un dettaglio tecnico che nessuno gli aveva chiesto."},"culprit":"filippo","key":["x1","f4","l2"],"solution":"Il medium è un truffatore: cassa sotto il tavolo, piolo nella gamba. Ma a uccidere è stato Filippo, che doveva allo zio 180.000 euro e rischiava di finire davanti a un giudice. Un mese fa trova il medium e gli detta i ricordi di Clara e la frase «vieni con me», sapendo che quel cuore non regge uno spavento. Stamattina butta lo spray buono, non scaduto, e gli consegna un flacone della sua farmacia pieno d'acqua. Al buio Ernesto spruzza, non succede niente, e chiama Filippo. Livia l'ha registrato.","contradictions":[{"id":"x1","a":"f2","b":"d4","who":"filippo","reply":"Avrò letto male la data. Ero di corsa.","aside":"Un farmacista che legge male una scadenza. Sulla medicina che tiene in vita suo zio.","insight":"Filippo ha buttato uno spray buono per sostituirlo con il suo: la scadenza era una scusa.","lie":true},{"id":"x2","a":"f1","b":"l3","who":"filippo","reply":"Va bene, l'ho proposto io. Volevo che si desse pace.","insight":"È stato Filippo a volere la seduta, e aveva provato a scaricarla su Livia.","lie":true}]},{"id":"calici","title":"Il quinto calice","place":"Teatro dei Portici, Martina Franca","teaser":"Il numero lo faceva da trent'anni. Stasera il pubblico ha applaudito un morto.","intro":"Orfeo il Grande, al secolo Oreste Pace, 62 anni, chiude ogni spettacolo con il suo numero più famoso: cinque calici, uno col veleno, e uno spettatore che li mescola. Lui «legge» lo spettatore e beve sempre quello giusto. Stasera ha bevuto, ha sorriso e si è accasciato sul palco. Duecento persone hanno applaudito per dieci secondi, prima di capire. Tu eri in quarta fila.","details":[{"id":"d1","label":"I cinque calici","text":"Sul tavolino in scena. Quello da cui ha bevuto Orfeo ha una tacca minuscola sulla base, invisibile dalla platea. Dal fondo sale un odore di mandorle amare.","insight":"Orfeo ha bevuto dal calice con la tacca, quello che per il trucco era sempre acqua. Il veleno vero era lì."},{"id":"d2","label":"La scaletta dietro le quinte","text":"Attaccata al muro: «20:45 Sergio: riempire i calici. 21:10 Nives: vassoio in scena.»","insight":"I calici li riempie Sergio. Nives li porta in scena."},{"id":"d3","label":"Il camerino di Orfeo","text":"Stampati, gli screenshot di un canale video, «Magia Nuda», che svela i suoi numeri uno per uno. Tutti ripresi di nascosto dalla quinta sinistra. A penna, Orfeo: «È uno di casa. Lunedì avvocato.»","insight":"Qualcuno di casa filmava i numeri dalla quinta sinistra e li svelava online. Orfeo stava per denunciarlo."},{"id":"d4","label":"Il registro del retropalco","text":"Stasera tre firme soltanto: Orfeo, Nives, Sergio. La porta di servizio era chiusa dall'interno.","insight":"Dietro le quinte c'erano solo Orfeo, Nives e Sergio."},{"id":"d5","label":"Il cestino del retropalco","text":"Un paio di guanti di lattice appallottolati e una fialetta di vetro vuota, senza etichetta.","insight":"Chi ha avvelenato il calice ha usato guanti di lattice."},{"id":"d6","label":"La cassetta di Sergio","text":"Cacciaviti, nastro nero, una lima da orafo. In fondo, una microcamera da occhiello ancora nella scatola del caricatore.","insight":"Sergio ha una microcamera per filmare di nascosto."},{"id":"d7","label":"La citazione in tribunale","text":"Nel camerino, un atto: Lucio Ferrara, in arte Lucifer, cita Orfeo per plagio. Il numero conteso è quello dei calici.","insight":"Lucio accusava Orfeo di avergli rubato proprio il numero dei calici."}],"suspects":[{"id":"sergio","name":"Sergio Conversano","role":"Tecnico di scena, da vent'anni con Orfeo","look":"Maglia nera, cintura con gli attrezzi, mani da falegname. Fuma sul retro.","tell":"Unghie pulite per uno che maneggia attrezzi. Nelle pieghe delle nocche gli è rimasta una polvere bianca, fine, quella del talco dei guanti di lattice. Se la strofina via sui pantaloni quando lo guardi.","questions":[{"id":"s1","q":"Che cosa ha fatto prima del numero?","a":"Il solito. Botole, corde, e alle nove meno un quarto ho riempito i calici. Acqua dal rubinetto, e il blu nel calice finto. Poi il vassoio l'ha preso Nives.","insight":"Sergio ha riempito i calici alle 20:45."},{"id":"s2","q":"Conosce il canale «Magia Nuda»?","a":"Mai visto. Io lavoro con le mani, non col telefono.","insight":"Sergio dice di non sapere niente del canale che svela i trucchi."},{"id":"s3","q":"Nella sua cassetta c'è una microcamera da occhiello.","req":["d6"],"a":"Me l'ha chiesta il maestro, per rivedersi le prove.","aside":"Risposta pronta. Troppo pronta per una domanda che non si aspettava.","insight":"Sergio ha l'attrezzatura per filmare di nascosto, e la giustifica."},{"id":"s4","q":"Nel cestino ci sono guanti di lattice. E lei ha il talco sulle nocche.","req":["d5","t_sergio"],"a":"Li uso per le lampade. Le alogene non si toccano con le dita.","aside":"Le lampade si cambiano la mattina, a teatro vuoto. Stasera le luci erano del tecnico in cabina: Sergio non le ha toccate.","insight":"Sergio ha usato guanti di lattice stasera e mente sul perché.","lie":true}]},{"id":"nives","name":"Nives Semeraro","role":"Assistente di scena e compagna di Orfeo","look":"Ancora col costume di paillettes, trucco colato, uno scialle sulle spalle.","tell":"Continua a guardare verso la platea, sempre verso la stessa poltrona della fila C. Si sfila e si rimette un anello che non è una fede.","questions":[{"id":"n1","q":"Cosa è successo in scena?","a":"Tutto come sempre. Lo spettatore mescola, Orfeo «legge», e alla fine beve dal calice con la tacca, che è sempre acqua. Si è portato la mano alla gola. Ho pensato che improvvisasse.","insight":"Il veleno era nell'unico calice che Orfeo avrebbe sicuramente bevuto."},{"id":"n2","q":"I video del canale sono girati dalla quinta sinistra. Chi c'è lì?","req":["d3"],"a":"Alla sinistra? Solo Sergio, alla leva delle botole. Io sto sempre a destra, col vassoio. Sempre.","insight":"I video del canale sono girati dal posto di Sergio."},{"id":"n3","q":"Chi sapeva della tacca?","a":"Orfeo, io, e Sergio, che ha fatto i calici. Nessun altro al mondo. Orfeo non l'ha mai detto nemmeno al suo avvocato.","insight":"Della tacca sapevano solo Nives e Sergio."},{"id":"n4","q":"Continua a guardare la fila C. Il posto di Lucio.","req":["t_nives"],"a":"(Si stringe lo scialle.) Lucio mi ha offerto un posto nel suo spettacolo. Stavo per lasciare Orfeo. Non gliel'avevo ancora detto.","insight":"Nives stava per lasciare Orfeo e passare con Lucio. Non aveva bisogno di ucciderlo per andarsene.","lie":true}]},{"id":"lucio","name":"Lucio Ferrara","role":"Illusionista rivale, in arte Lucifer","look":"Mantello nero anche fuori scena, anelli d'argento, biglietto della fila C in mano.","tell":"Parla forte e si gira verso chi ascolta: vive di pubblico. Ma quando si parla di Orfeo morto smette di recitare e gli trema il mento. Lo odiava, e gli dispiace davvero.","questions":[{"id":"l1","q":"Dov'era durante lo spettacolo?","a":"Fila C, posto 7. Ho pagato il biglietto per vedere dal vivo il mio numero rubato. Non mi sono alzato nemmeno all'intervallo. Chieda ai miei vicini.","insight":"Lucio è rimasto in platea per tutto lo spettacolo."},{"id":"l2","q":"Lei ha fatto causa a Orfeo per il numero dei calici.","req":["d7"],"a":"Il numero è mio. Io uso un magnete sotto il tavolo. Lui come facesse non lo so: non me l'ha mai voluto dire, il ladro.","insight":"Lucio non sapeva come Orfeo riconoscesse il calice giusto."},{"id":"l3","q":"Dalla platea ha notato qualcosa?","a":"Il tecnico. Durante il numero delle corde era in quinta sinistra col telefono puntato sul palco. Durante un numero! Io uno così lo licenzio in tronco.","insight":"Durante lo spettacolo Sergio filmava dalla quinta sinistra."}]}],"bluff":{"text":"Annunci che Orfeo, sospettando qualcuno, stasera aveva spostato la tacca su un altro calice.","reactions":{"sergio":"«Non può averla spostata. La lima ce l'ho io, e...» Si ferma. Si accende una sigaretta.","nives":"«Impossibile. Il vassoio l'ho portato io, era tutto come sempre.»","lucio":"«Tacca? Quale tacca?» Curiosità pura, da collega."},"insight":"Al bluff della tacca Sergio ha detto subito che solo lui aveva la lima per farla."},"culprit":"sergio","key":["s4","x1","d1"],"solution":"Il veleno era nel calice con la tacca, l'unico che Orfeo avrebbe bevuto di sicuro. Della tacca sapevano solo Nives e Sergio. Sergio riempiva i calici alle 20:45, coi guanti di lattice che ha lasciato nel cestino e il talco rimasto sulle nocche. Il movente era nel camerino: da mesi Sergio filmava i numeri dalla quinta sinistra e li svelava sul suo canale, e lunedì Orfeo sarebbe andato dall'avvocato. Nives voleva solo andarsene, e Lucio, che non ha mai lasciato la fila C, la tacca non sapeva nemmeno che esistesse.","contradictions":[{"id":"x1","a":"s2","b":"n2","who":"sergio","reply":"Va bene, il canale è mio. Novecento euro al mese per trent'anni di segreti. Sa quanto rende un video da un milione di visualizzazioni?","aside":"Lo dice quasi con orgoglio. Poi si accorge di aver appena consegnato il movente.","insight":"Il canale «Magia Nuda» è di Sergio. Orfeo l'aveva scoperto e lunedì l'avrebbe denunciato.","lie":true}]},{"id":"cesareo-villette","title":"Le Dune Bianche","place":"Cantiere Le Dune Bianche, Porto Cesareo","teaser":"Quattordici villette sulla carta. Sul terreno, sabbia. E il geometra è sparito.","intro":"Quattordici famiglie hanno versato trentamila euro di caparra per una villetta alle Dune Bianche, a trecento metri dal mare di Porto Cesareo. Lunedì hanno scoperto che il permesso di costruire è falso e che le caparre sono sparite. Il geometra Aldo Miglietta, che firmava tutto, non si trova da venerdì sera: la sua auto è al parcheggio di Torre Lapillo. Per tutti è scappato coi soldi. Il costruttore ti ha chiamato perché, dice, «se è scappato, voglio sapere con chi».","details":[{"id":"d1","label":"Il permesso di costruire","text":"Appeso nella baracca del cantiere, con timbro e firma di Aldo Miglietta. Il numero di protocollo, sul sito del Comune, corrisponde a una tettoia autorizzata nel 2016.","insight":"Il permesso è falso: il numero è preso da un'altra pratica."},{"id":"d2","label":"I preliminari","text":"Quattordici contratti di vendita. La firma di Aldo è identica in tutti, al millimetro, compresa una piccola sbavatura sulla M.","insight":"Aldo non ha firmato i preliminari: la sua firma è stata copiata e stampata."},{"id":"d3","label":"L'estratto conto","text":"Conto «caparre Dune Bianche», intestato all'agenzia Leo Immobiliare. Lunedì mattina: bonifico di 380.000 euro a «Salina Holding Ltd», La Valletta.","insight":"Le caparre sono uscite dal conto dell'agenzia di Sabrina verso Malta, il lunedì dopo la sparizione."},{"id":"d4","label":"L'agenda di Aldo","text":"Nella baracca. Ultima pagina scritta, venerdì: «Firme false?? Parlare con S. prima di andare in Procura.»","insight":"Aldo aveva scoperto le firme false e voleva parlarne con «S.» prima di andare in Procura."},{"id":"d5","label":"L'ipoteca","text":"Sulla scrivania di Gianni Quarta: ipoteca sulla sua casa di Leverano, a garanzia del mutuo per il terreno.","insight":"Gianni ha messo in garanzia la sua casa: da questa truffa ci perde tutto."},{"id":"d6","label":"Le telecamere del cantiere","text":"Registro dell'impianto: spente venerdì alle 19:02 dall'app, utente «agenzia». Riaccese lunedì mattina.","insight":"Venerdì alle 19:02 l'utenza dell'agenzia ha spento le telecamere del cantiere."},{"id":"d7","label":"L'auto di Aldo","text":"Una vecchia Punto al parcheggio di Torre Lapillo, chiusa a chiave. Sul sedile, la borsa da lavoro con il suo timbro. Nessuna valigia.","insight":"Aldo non è partito per una fuga organizzata: niente valigia, e il timbro lasciato in macchina."}],"suspects":[{"id":"gianni","name":"Gianni Quarta","role":"Costruttore, Sud Costruzioni, 61 anni","look":"Faccia bruciata dal sole, voce che copre le betoniere. Agita una cartellina di documenti mentre parla.","tell":"Urla, ma ti guarda negli occhi e ti porge i documenti prima che tu li chieda. Quando dice «la mia casa» gli si spezza la voce. È la rabbia di chi è stato fregato, non di chi ha fregato.","questions":[{"id":"g1","q":"Lei ha incassato le caparre?","a":"Io non ho visto un euro! Le caparre andavano all'agenzia, sul conto vincolato. Io per quel terreno ho messo in ipoteca pure casa mia!","insight":"Le caparre le gestiva l'agenzia di Sabrina, non Gianni."},{"id":"g2","q":"Aldo voleva parlare con «S.» prima della Procura. Sud Costruzioni?","req":["d4"],"a":"Aldo aveva il mio numero, mi chiamava pure per un sacco di cemento. E venerdì sera ero alla cresima di mio nipote a Leverano: duecento invitati e un fotografo.","insight":"Venerdì sera Gianni era a una cresima con duecento invitati."},{"id":"g3","q":"Chi le ha presentato Aldo?","a":"Sabrina, a maggio. «Un ragazzo bravo, uno che non fa domande.» Così me l'ha venduto.","insight":"È stata Sabrina a scegliere Aldo: «uno che non fa domande»."}]},{"id":"sabrina","name":"Sabrina Leo","role":"Agente immobiliare, 44 anni","look":"Blazer color sabbia, sorriso da vetrina, un portachiavi pieno di chiavi di case altrui.","tell":"Sorride sempre, anche quando parla dei soldi spariti: il sorriso arriva un attimo prima delle parole. Dice «povero Aldo», ma non chiede mai se l'hanno trovato. Quando le mostri un foglio lo gira per leggerlo: vuole sapere cosa sai tu.","questions":[{"id":"s1","q":"Chi curava le pratiche?","a":"Aldo. Tutto Aldo: permessi, firme, carte. Io vendo, non timbro. Povero Aldo. Si vede che aveva debiti.","insight":"Sabrina dice che firme e carte erano tutte di Aldo."},{"id":"s2","q":"Quando ha visto Aldo l'ultima volta?","a":"Giovedì, in agenzia. Venerdì mi ha solo telefonato, agitatissimo. Poi più niente.","insight":"Sabrina giura di non aver visto Aldo venerdì."},{"id":"s3","q":"Lunedì dal conto della sua agenzia sono partiti 380.000 euro per Malta.","req":["d3"],"a":"Una disposizione di Aldo. Il conto è dell'agenzia, ma i pagamenti ai fornitori li decideva lui, come direttore dei lavori.","aside":"Un direttore dei lavori non dà ordini sul conto di un'agenzia immobiliare. E lei lo sa benissimo.","insight":"Dal conto dell'agenzia di Sabrina sono partiti 380.000 euro per Malta, e lei ne dà la colpa ad Aldo.","lie":true},{"id":"s4","q":"Le telecamere del cantiere le ha spente la sua agenzia.","req":["d6"],"a":"Le spegniamo sempre il venerdì sera. Per la privacy dei clienti che vengono a vedere il cantiere nel weekend.","aside":"Nel weekend il cantiere è chiuso con la catena.","insight":"Venerdì sera Sabrina ha spento le telecamere del cantiere, con una scusa.","lie":true}]},{"id":"teresa","name":"Teresa Miglietta","role":"Moglie di Aldo, 39 anni","look":"Una felpa del marito, troppo grande. Due telefoni in mano, uno vecchio con la cover rotta.","tell":"Guarda sempre il telefono vecchio, mai il suo. Non ha l'aria di una moglie in lutto: ha l'aria di chi aspetta un messaggio. Quando le dici che il marito è un ladro non si arrabbia. Stringe le labbra e sta zitta.","questions":[{"id":"t1","q":"Quando ha visto suo marito l'ultima volta?","a":"Venerdì, alle sette e mezza. È uscito dicendo: «Vado al cantiere, Sabrina mi aspetta là, dobbiamo chiarire una cosa.» Non è più tornato.","insight":"Venerdì sera Aldo è andato al cantiere per incontrare Sabrina."},{"id":"t2","q":"Lei aspetta un messaggio su quel telefono vecchio.","req":["t_teresa"],"a":"(Te lo porge.) Martedì mi ha scritto da un numero nuovo. «Sto bene. Non dire niente. Lei dice che le firme sono mie e che se parlo la galera me la faccio io.» Lei. Non so chi è, lei. Ma lui ha paura.","insight":"Aldo è vivo e nascosto. Ha paura di una donna che minaccia di addossargli le firme.","lie":true},{"id":"t3","q":"Aldo aveva debiti?","a":"Aldo? Porta la stessa giacca da dieci anni. Se avesse avuto quattrocentomila euro, prima di scappare se ne sarebbe comprata una nuova.","insight":"Aldo non aveva debiti, né soldi da parte."}]}],"contradictions":[{"id":"x1","a":"s2","b":"t1","who":"sabrina","reply":"Va bene, ci siamo visti al cantiere. Cinque minuti. Era fuori di sé, farneticava di firme. L'ho calmato e se n'è andato.","aside":"«L'ho calmato.» Da quel momento nessuno l'ha più visto.","insight":"Venerdì sera Sabrina ha incontrato Aldo al cantiere, l'ultima prima che sparisse, e l'aveva negato.","lie":true},{"id":"x2","a":"s1","b":"d2","who":"sabrina","reply":"Tanti geometri hanno la firma su un timbro. Sarà così.","aside":"Nessun geometra ha la firma su un timbro. E i preliminari li prepara l'agenzia, non il geometra.","insight":"I preliminari li preparava l'agenzia di Sabrina, e la firma di Aldo ci è stata stampata sopra.","lie":true}],"bluff":{"text":"Annunci che Aldo è stato trovato vivo in un B&B di Veglie e che sta parlando con i carabinieri.","reactions":{"gianni":"«Finalmente! Adesso ci ridà i soldi.» Si siede, sfinito.","sabrina":"«Qualunque cosa dica, le firme sono sue. Ci sono i documenti.» Nessuno le aveva chiesto delle firme.","teresa":"Chiude gli occhi e sorride. Non chiede dov'è, né come sta."},"insight":"Alla notizia che Aldo parlava, Sabrina si è difesa subito sulle firme, prima che qualcuno la accusasse."},"culprit":"sabrina","key":["x1","x2","s3"],"solution":"La truffa l'ha costruita Sabrina: permesso falso, preliminari preparati dalla sua agenzia con la firma di Aldo stampata sopra, caparre sul conto dell'agenzia. Aldo, scelto perché «non faceva domande», si è accorto delle firme e venerdì è andato al cantiere a chiarire con lei. Sabrina aveva già spento le telecamere alle 19:02: lo ha minacciato di fargli pagare tutto, e Aldo è scappato così com'era, lasciando l'auto a Torre Lapillo senza nemmeno una valigia. Lunedì, con il geometra «in fuga» come colpevole perfetto, Sabrina ha spostato 380.000 euro a Malta. Aldo è vivo, e ha paura di lei."},{"id":"studiodentistico","title":"Il sorriso perfetto","place":"Studio dentistico Mancuso, quartiere Poggiofranco, Bari","teaser":"Trentamila euro, o le foto vanno a due famiglie.","intro":"Il dottor Sergio Mancuso, 52 anni, dentista, sposato, ha una relazione con la sua collega di studio, Irene Caputo, anche lei sposata. Stamattina nella cassetta dello studio c'era una busta: quattro foto di loro due, di notte, nella sala 2, e una lettera. «30.000 € in contanti, o le foto arrivano a tua moglie e al marito di Irene.» Sergio non vuole la polizia. Vuole sapere chi, dei suoi, lo sta tradendo.","details":[{"id":"d1","label":"La lettera","text":"Stampata al computer. La carta è quella intestata dello studio, con l'intestazione tagliata via: in alto resta un filo del logo blu.","insight":"La lettera è stampata su carta dello studio: il ricattatore lavora qui."},{"id":"d2","label":"Le foto","text":"Scattate dall'alto, dalla mensola della sala 2 dove sta la reflex per le foto dei sorrisi. Sergio si vede sempre in faccia. Irene sempre di spalle, o di profilo coperta dai capelli. In quattro scatti, mai il suo viso.","insight":"Chi ha piazzato la macchina ha fatto in modo che Irene non si riconoscesse mai."},{"id":"d3","label":"Il registro dell'allarme","text":"Giovedì scorso: «20:58 disattivato — codice 03 (E. Barone)». «23:40 riattivato — codice 03.»","insight":"Giovedì sera qualcuno è entrato con il codice d'allarme di Elisa."},{"id":"d4","label":"Il post-it","text":"Attaccato sotto la tastiera della reception: tutti i codici dell'allarme, scritti a penna, con una grafia tonda.","insight":"Chiunque abbia frugato alla reception può conoscere il codice di chiunque."},{"id":"d5","label":"La chat di Sergio","text":"Te la mostra lui, a malincuore. Giovedì, 20:41, Sergio a Irene: «Entra tu, io arrivo alle nove e un quarto.» Irene: «Ok. Ti aspetto in sala 2.»","insight":"Giovedì sera Irene è entrata per prima, da sola, un quarto d'ora prima di Sergio."},{"id":"d6","label":"La raccomandata","text":"Nella posta dello studio, per Irene, già aperta: uno studio legale di Bari. «Ricorso per separazione consensuale. Udienza fissata al 12 ottobre.»","insight":"Irene si sta già separando: la minaccia di mandare le foto a suo marito per lei non vale niente."},{"id":"d7","label":"Le istruzioni per il pagamento","text":"In fondo alla lettera: «Contanti in una scatola per impronte. Da lasciare nel laboratorio, armadietto 4.» L'armadietto 4 è quello di Elisa.","insight":"Le istruzioni del ricatto portano dritte all'armadietto di Elisa."}],"suspects":[{"id":"elisa","name":"Elisa Barone","role":"Igienista dentale, 29 anni","look":"Divisa verde, occhiaie, una foto di un bambino attaccata al badge.","tell":"Risponde di getto, senza pause, e ti guarda in faccia anche quando la domanda è brutta. Si arrabbia sul serio quando nomini l'armadietto. È la rabbia di chi si sente incastrata.","questions":[{"id":"e1","q":"Giovedì sera il suo codice ha disattivato l'allarme.","req":["d3"],"a":"Giovedì ero al matrimonio di mia cugina a Conversano, dalle sei all'una di notte. Trecento invitati e un videografo. Mi trovate in tutti i balli.","insight":"Giovedì sera Elisa era a un matrimonio a Conversano: alibi."},{"id":"e2","q":"Lei ha problemi di soldi?","a":"Un mutuo e un figlio di tre anni. Chi non ne ha? Ma chi ricatta non scrive di lasciare i soldi nel suo armadietto. Sarei scema.","insight":"Elisa fa notare che le istruzioni la accusano troppo apertamente."},{"id":"e3","q":"Chi usa la reflex della sala 2?","a":"La dottoressa Caputo. Fa le foto prima e dopo delle faccette. La regola lei, la carica lei. Se la tocchi ti uccide.","insight":"La reflex della sala 2 la usa e la regola solo Irene."}]},{"id":"irene","name":"Irene Caputo","role":"Dentista, collega di Sergio, 44 anni","look":"Camice su misura, fede ancora al dito, voce bassa e controllata.","tell":"Dice sempre «ci»: «ci ricatta», «ci rovina». Ma quando Sergio sparge le foto sul tavolo lei non le guarda nemmeno. Chi vede una foto per la prima volta la guarda. Lei le conosce già.","questions":[{"id":"i1","q":"Giovedì sera, come siete entrati?","a":"Mi ha aperto Sergio. Io l'allarme non l'ho toccato.","insight":"Irene dice di essere arrivata dopo Sergio e di non aver toccato l'allarme."},{"id":"i2","q":"Nelle foto lei non si vede mai in faccia.","req":["d2"],"a":"Fortuna. O forse il ricattatore vuole colpire lui, non me.","aside":"Un mezzo sorriso. Poi si ricorda che dovrebbe essere spaventata.","insight":"Il ricattatore ha protetto Irene, e lei non se ne stupisce."},{"id":"i3","q":"Lei si sta già separando.","req":["d6"],"a":"Sì. E allora? Non lo sapeva nessuno. Adesso lo sa lei.","aside":"Sergio si gira di scatto. Lui non lo sapeva.","insight":"Per Irene la minaccia era vuota: si separa già, e l'ha tenuto nascosto a Sergio.","lie":true}]},{"id":"tina","name":"Tina Sgaramella","role":"Segretaria, 47 anni","look":"Occhiali alla catenella, agenda aperta, penna dietro l'orecchio.","tell":"Sull'agenda aperta la sua grafia è tonda, con le «a» chiuse a ricciolo. Quando si parla di codici d'allarme chiude l'agenda e ci appoggia sopra la mano.","questions":[{"id":"s1","q":"Chi conosce i codici dell'allarme?","a":"Ognuno il suo. Io li so tutti a memoria, li ho impostati io.","insight":"Tina dice di sapere i codici a memoria."},{"id":"s2","q":"Sotto la sua tastiera c'è un post-it con tutti i codici. Scritto da lei.","req":["d4"],"a":"(Arrossisce.) Non ho memoria per i numeri, va bene? L'ha visto solo... la dottoressa Caputo, una volta. Due settimane fa. Frugava nel mio cassetto, cercava un modulo, disse.","insight":"Due settimane fa Irene ha frugato alla reception, dove c'erano tutti i codici.","lie":true},{"id":"s3","q":"Come vanno le cose tra i due dottori?","a":"Lei voleva diventare socia al cinquanta per cento. Un mese fa lui le ha detto di no, qui, a voce alta. Lei è uscita sbattendo la porta. Il giorno dopo era tutta miele.","insight":"Un mese fa Sergio ha negato a Irene la società: il rancore c'è."}]}],"bluff":{"text":"Annunci che la reflex della sala 2 salva ogni scatto anche su una seconda scheda, e che la stai facendo leggere adesso.","reactions":{"elisa":"«Magari! Così la finiamo con l'armadietto.»","irene":"«Quel modello ha uno slot solo.» Poi tace, e si guarda la fede.","tina":"«Una seconda scheda? Io non so neanche accenderla, quella.»"},"insight":"Al bluff della seconda scheda Irene ha corretto subito: conosce la reflex e sapeva che la copia non esisteva."},"culprit":"irene","key":["x1","i3","s2"],"solution":"La ricattatrice è la donna nelle foto. Sergio le aveva negato la società e Irene, che si stava già separando, aveva bisogno di soldi. Due settimane fa prende il codice di Elisa dal post-it di Tina. Giovedì entra per prima con quel codice, sistema la reflex della sala 2, che usa solo lei, e inquadra in modo che il suo viso non si veda mai. Poi lettera su carta dello studio e soldi nell'armadietto di Elisa, per incastrarla. Ma Elisa quella sera ballava a Conversano, e la minaccia di scriverlo al marito di Irene non spaventava nessuno.","contradictions":[{"id":"x1","a":"i1","b":"d5","who":"irene","reply":"Va bene, sono entrata io. Col codice di Elisa, sì: il mio avrebbe lasciato traccia. Per discrezione.","aside":"Sergio la fissa. Del codice di Elisa non sapeva niente.","insight":"Giovedì Irene è entrata per prima, da sola, col codice di Elisa: aveva un quarto d'ora nella sala delle foto.","lie":true}]},{"id":"zaffiri","title":"Gli zaffiri della nonna","place":"Masseria Le Due Torri, campagne di Fasano","teaser":"Dieci minuti di fuochi d'artificio. Novantamila euro di zaffiri.","intro":"Federica si è sposata oggi, in una masseria sopra Fasano, con la parure di zaffiri della nonna: collana, orecchini, bracciale. Alle undici li ha tolti per il cambio d'abito e li ha lasciati nella suite. A mezzanotte, dieci minuti di fuochi d'artificio sull'aia. All'una la cassetta era vuota. Nessuno ha lasciato la festa, e la sposa ti ha trovato tra gli invitati.","details":[{"id":"d1","label":"La cassetta della suite","text":"Aperta, vuota, nessun segno di forzatura. Federica ammette di non averla chiusa.","insight":"Chi è entrato non ha dovuto forzare niente: bastava entrare in suite."},{"id":"d2","label":"La serratura elettronica","text":"Il registro della porta: «23:40 tessera Ospite 2. 00:04 tessera Staff.»","insight":"Alle 00:04, durante i fuochi, qualcuno è entrato in suite con una tessera dello staff."},{"id":"d3","label":"La reception","text":"In cassaforte c'è una sola tessera Staff. Il registro: «Tessere Staff: 2. Una consegnata a B. Colaianni, wedding planner. Non restituita.»","insight":"L'unica altra tessera dello staff è quella della wedding planner, e non è mai tornata alla reception."},{"id":"d4","label":"La lista del personale","text":"Accanto al nome di un cameriere, a penna: «Lomuscio Cristian – precedente per furto (2021). Tenere d'occhio.»","insight":"Il cameriere Cristian ha un precedente per furto."},{"id":"d5","label":"Il video dei fuochi","text":"Dal tablet del videomaker: l'aia per tutti e dieci i minuti. Cristian col vassoio in primo piano, sempre. In fondo, il pirotecnico da solo al quadro, dal primo all'ultimo botto.","insight":"Cristian non si è mai mosso durante i fuochi. E il pirotecnico era solo."},{"id":"d6","label":"La scrivania del gestore","text":"Un fascicolo: «Colaianni Wedding – acconti non versati. Terzo sollecito.» Sotto, altri due solleciti di un fiorista e di un catering.","insight":"L'agenzia della wedding planner non paga i fornitori da mesi."},{"id":"d7","label":"Il furgone della planner","text":"Nel cortile, già carico di centrotavola e candelabri da riportare al noleggio. Sul cruscotto un biglietto: «Partenza appena finita la festa».","insight":"Le cose della planner lasceranno la masseria prima di tutti."}],"suspects":[{"id":"cristian","name":"Cristian Lomuscio","role":"Cameriere, 24 anni","look":"Camicia bianca, papillon storto, vassoio sempre in mano.","tell":"Mani ferme, sguardo stanco. Risponde senza premesse e senza giustificarsi: chi mente di solito spiega troppo. Lui aspetta solo che finisca.","questions":[{"id":"c1","q":"Dov'era durante i fuochi?","a":"Sull'aia col vassoio del brindisi. Il videomaker mi ha detto di stare fermo nell'inquadratura, e io sono stato fermo.","insight":"Cristian dice di essere rimasto sull'aia tutto il tempo, nel video."},{"id":"c2","q":"Lei ha un precedente per furto.","req":["d4"],"a":"Avevo diciannove anni. Una bici. Da allora ogni volta che sparisce qualcosa guardano me. Fate pure.","aside":"Non abbassa gli occhi. È stanchezza, non paura."},{"id":"c3","q":"Dopo i fuochi ha visto qualcosa di strano?","a":"A mezzanotte e dieci, più o meno, la planner è tornata sull'aia. Ma non dalla parte dei fuochi: dal vialetto delle suite. Con quella valigetta che non molla mai.","insight":"Alle 00:10 la planner tornava dal vialetto delle suite con la valigetta."}]},{"id":"alessia","name":"Alessia Loiacono","role":"Sorella della sposa e testimone","look":"Abito verde smeraldo, capelli raccolti, flûte sempre piena.","tell":"Si tocca il collo, sotto l'orecchio, dove la pelle è segnata da una linea rossa sottile, come quella di un fermaglio pesante. Mette via il telefono ogni volta che qualcuno le passa dietro.","questions":[{"id":"a1","q":"È salita in suite stasera?","a":"Alle undici e quaranta, a prendere lo scialle di Federica. Con la seconda tessera ospite. I gioielli erano nella cassetta aperta.","insight":"Alle 23:40 i gioielli erano ancora in suite."},{"id":"a2","q":"Lei ha provato la collana.","req":["t_alessia"],"a":"(Arrossisce.) Due minuti. Una foto. La nonna l'ha lasciata a lei, non a me, e io volevo vedere come mi stava. L'ho rimessa nella cassetta. Guardi l'ora della foto: 23:42.","insight":"Alle 23:42 Alessia ha provato la collana e l'ha rimessa a posto. La foto lo prova.","lie":true},{"id":"a3","q":"Chi può entrare in suite?","a":"Federica, io con la seconda tessera, e la planner. Quella ha la tessera per tutte le stanze.","insight":"La planner ha una tessera che apre la suite."}]},{"id":"beatrice","name":"Beatrice Colaianni","role":"Wedding planner, 40 anni","look":"Auricolare all'orecchio, tailleur nero, scarpe basse. Una valigetta rigida con scritto «Kit sposa».","tell":"Sorriso professionale che non si spegne mai. La valigetta del kit sposa la tiene stretta tra le caviglie, e quando si alza la solleva con due mani: il braccio si tende, pesa.","questions":[{"id":"b1","q":"Dov'era durante i fuochi?","a":"Col pirotecnico, al quadro. È il momento più delicato della serata. Non l'ho lasciato un secondo.","insight":"Beatrice dice di essere rimasta col pirotecnico per tutti i fuochi."},{"id":"b2","q":"Lei ha una tessera della suite?","a":"La tessera staff, sì. Ma l'ho lasciata alla reception prima dei fuochi. Io in suite senza la sposa non entro.","insight":"Beatrice dice di aver restituito la tessera alla reception prima dei fuochi."},{"id":"b3","q":"Il gestore aspetta i suoi acconti da mesi.","req":["d6"],"a":"Periodo difficile. Le spose pagano tardi, io pago tardi. Funziona così, in questo lavoro.","aside":"Mentre parla, sposta il piede contro la valigetta.","insight":"Beatrice è piena di debiti con i fornitori."},{"id":"b4","q":"Quella valigetta non la molla un secondo.","req":["t_beatrice"],"a":"È il kit d'emergenza della sposa. Spille, ago e filo, cerotti. Se salta un bottone, chi la salva, la sposa?","aside":"Federica balla da due ore e la valigetta non si è mai aperta. Spille e cerotti non pesano così.","insight":"La valigetta di Beatrice pesa troppo per un kit di spille."}]}],"bluff":{"text":"Annunci che i carabinieri stanno arrivando e che perquisiranno tutte le borse e tutti i veicoli prima che qualcuno esca.","reactions":{"cristian":"Posa il vassoio e allarga le braccia. «Cominciate da me, tanto.»","alessia":"«Anche i telefoni? Guardano anche le foto?» Poi arrossisce.","beatrice":"Si offre di organizzare lei le uscite, «per non rovinare la festa agli sposi», e chiede se i furgoni dei fornitori possono partire prima, «hanno orari col noleggio»."},"insight":"Al bluff della perquisizione Beatrice ha provato a far partire per primi i furgoni dei fornitori."},"culprit":"beatrice","key":["x2","d2","x1"],"solution":"Alle 23:42 la collana era ancora in suite: c'è la foto di Alessia, che l'ha provata di nascosto e rimessa a posto. Alle 00:04, a fuochi in corso, la porta si apre con una tessera staff. Quella della reception era in cassaforte; l'altra era di Beatrice, che giura di averla restituita e invece non l'ha mai fatto. Il video mostra il pirotecnico da solo per tutti i fuochi, e alle 00:10 Cristian la vede tornare dal vialetto delle suite. Beatrice, piena di debiti, ha messo gli zaffiri nella valigetta del kit sposa e contava di portarli via col furgone. Cristian, col suo precedente, era il colpevole perfetto, ma per dieci minuti non è mai uscito dall'inquadratura.","contradictions":[{"id":"x1","a":"b1","b":"d5","who":"beatrice","reply":"Mi sono allontanata un attimo, a prendere le stelline per gli ospiti. Due minuti.","aside":"Le stelline le ha distribuite lei alle undici, prima della torta.","insight":"Beatrice ha lasciato il pirotecnico durante i fuochi, proprio mentre qualcuno entrava in suite.","lie":true},{"id":"x2","a":"b2","b":"d3","who":"beatrice","reply":"Me la sarò dimenticata in tasca. Ma in suite non ci sono entrata.","aside":"La serratura dice il contrario. Alle 00:04.","insight":"La tessera di Beatrice non è mai tornata alla reception: è quella che ha aperto la suite alle 00:04.","lie":true}]}];
